    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/case-packages.mjs",
      "gitBlob": "96681600c918cc28f068f20f0c6f77cc99cafb33",
      "bytes": 5623,
      "sha256": "0bd157eebaee4ad2436a6f935c434c0328b695e72180ed145465646c301dd2a3",
      "content": "// MIT. Complete case/source package tools, using the original Support owner.\nconst id={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};\nconst sha={type:'string',pattern:'^[a-f0-9]{64}$'};\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};\nconst actor={type:'string',minLength:1,maxLength:200};\nconst page={offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:200},\n  q:{type:'string',maxLength:240}};\nconst source={type:'object',properties:{kind:{enum:['input','operation']},id},required:['kind','id'],additionalProperties:false};\nconst fileRead={source,name:{type:'string',minLength:1,maxLength:4096},expectedManifestSha256:sha,\n  expectedSha256:sha,readId:uuid,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:196608}};\nexport function casePackageTools(tool) {\n  const read={readOnly:true,idempotent:true},write={idempotent:true};\n  return [\n    tool('merchant_case_package_catalog','Inspect the original complete-package owner, configured Handoffs source aliases, source-owned byte limits and existing private case/source paths. Starts no transfer.',{},[],read),\n    tool('merchant_case_package_operations','Page retained package operations and their observed lifecycle. A saved RUNNING state alone does not establish a live worker.',page,[],read),\n    tool('merchant_case_package_inputs','Page original browser-received complete package inputs. Their original manifest and native member bytes remain retained.',page,[],read),\n    tool('merchant_case_package_status','Read one original operation, actual ownership in this process, native receiving progress and completion.',{id},['id'],read),\n    tool('merchant_case_package_prepare','Retain one complete package operation. Export selects an original saved case revision and preserves full history/all native source bundles. Inspect/receive selects an existing input or exported operation. Remote receiving uses one configured Handoffs source and original export. Keep this exact ID, actor and body after an interrupted reply.',\n      {id,kind:{enum:['export','inspect','receive','remote']},actor,caseId:uuid,revision:sha,source,\n        expectedManifestSha256:sha,profile:id,exportId:id},['id','kind','actor'],write),\n    tool('merchant_case_package_run','Start or join the exact retained operation through the original writer lease. Completed requests retain their first native result. Inspect status after a lost reply.',{id},['id'],write),\n    tool('merchant_case_package_pause','Pause the running package operation owned by this installed process and retain its native checkpoints. It cannot stop another owner.',{id},['id'],write),\n    tool('merchant_case_package_inventory','Page complete files, original immutable case revisions or every native source bundle, including historical and unassigned attachments.',\n      {source,expectedManifestSha256:sha,section:{enum:['files','sourceBundles','originalFiles','revisions']},bundleId:sha,manifestSha256:sha,...page},['source','expectedManifestSha256'],read),\n    tool('merchant_case_package_remote_inspect','Read the exact complete package manifest from a host-configured original Handoffs source. Returns original identity and full inventory; creates no local case.',\n      {profile:id,exportId:id},['profile','exportId'],{...read,openWorld:true}),\n    tool('merchant_case_package_open','Resolve the completed receiving operation to its current original saved case. Preserves any later receiver edits and returns the independently usable source directory.',\n      {id},['id'],read),\n    tool('merchant_case_package_file','Read a bounded range of one whole-package file using the original immutable descriptor reader. Continue its readId or reopen the same expected SHA/offset after expiry. Large native source archives stay streamed.',\n      fileRead,['source','name','expectedManifestSha256','expectedSha256'],read),\n    tool('merchant_case_package_original_file','Read an actual original member inside one package-declared native source bundle after that source is available in the original local source service. This includes unassigned historical attachments.',\n      {source,expectedManifestSha256:sha,bundleId:sha,manifestSha256:sha,path:{type:'string',maxLength:4096},\n        expectedSha256:sha,readId:uuid,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:196608}},\n      ['source','expectedManifestSha256','bundleId','manifestSha256','path','expectedSha256'],read),\n    tool('merchant_case_package_file_release','Release an original immutable file reader owned by this package selection.',{source,readId:uuid},['source','readId'],write),\n    tool('merchant_case_package_export_manifest','Read the original complete-export manifest descriptor for native receiving. Fetch case-source-package.json through the original leased file route; its complete inventory includes all retained native bundles.',\n      {exportId:id},['exportId'],read),\n    tool('merchant_case_package_export_file','Read a complete export file through the original retained-download protocol. All names and SHA identities are bound to the exact completion manifest.',\n      {exportId:id,file:{type:'string',maxLength:4096},expectedManifestSha256:sha,expectedSha256:sha,\n        readId:uuid,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:196608}},\n      ['exportId','file','expectedManifestSha256','expectedSha256'],read),\n    tool('merchant_case_package_export_file_release','Release an original export file lease.',{exportId:id,readId:uuid},['exportId','readId'],write)\n  ];\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/commercial-receiving.mjs",
      "gitBlob": "303deec1f31cadd393ecbae5952809f696fb3364",
      "bytes": 3276,
      "sha256": "ccde7b5dfdafa2fa833b218febff8e0fd3629c2f9d07f29d7d464e81a18a921f",
      "content": "// MIT. Original full pricing and quotation receiving on the configured merchant case.\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};\nconst sha={type:'string',pattern:'^[a-f0-9]{64}$'};\nconst text=maxLength=>({type:'string',minLength:1,maxLength});\nconst path=text(4096),selected={id:uuid,expectedRevision:sha};\nconst quoted={...selected,revision:sha,quoteId:uuid,quoteSha256:sha,archiveSha256:sha};\nexport function commercialReceivingTools(tool){\n  const read={readOnly:true,idempotent:true},write={idempotent:true};\n  return [\n    tool('merchant_case_commercial_receiving_status','Read the current original case identity and actual in-process pricing/backup receiving work. Saved backup and case request IDs remain in their original native engines.',\n      {id:uuid},['id'],read),\n    tool('merchant_case_commercial_receiving_capture','Capture an existing saved SF97 plan and its complete original WORKSPACE_BACKUP. Supply the original private workspace/config and exactly one saved snapshot/history path. Keep backupRequestId, selected inputs and output directory after interruption. Inspect the retained source before attaching it.',\n      {...selected,pricingDirectory:path,pricingConfig:path,pricingSnapshot:path,pricingHistory:path,\n        planId:uuid,scenarioId:text(200),backupRequestId:uuid,directory:path},\n      ['id','pricingDirectory','pricingConfig','planId','backupRequestId','directory'],write),\n    tool('merchant_case_commercial_receiving_inspect','Verify the complete original retained pricing source, full workspace backup, original cost edition and supplier files. Returns exact source/file descriptors and the native pricing review; it does not append to the merchant case.',\n      {...selected,directory:path,expectedSourceSha256:sha},['id','directory'],read),\n    tool('merchant_case_commercial_receiving_attach','Attach the reviewed pricing source and complete original backup to this same case using the original two native request UUIDs. Record the merchant/source binding reason. Retry both original IDs, original case revision, actor, source SHA and exact input after a lost reply.',\n      {...selected,directory:path,expectedSourceSha256:sha,pricingRequestId:uuid,attachmentRequestId:uuid,\n        actor:text(200),bindingReason:text(4000)},\n      ['id','expectedRevision','directory','expectedSourceSha256','pricingRequestId','attachmentRequestId','actor','bindingReason'],write),\n    tool('merchant_case_commercial_receiving_case','Inspect one exact original quote and its retained complete pricing backup at a saved case revision. Choose archiveSha256 when the source has multiple original backups. Customer responses and source-case lineage remain unchanged.',\n      quoted,['id','quoteId','quoteSha256'],read),\n    tool('merchant_case_commercial_receiving_restore','Recover the original pricing TAR from the selected quote and restore its complete editable SF97 workspace through the original archive engine. Keep the retained archive outside the restore directory. Reopen verifies the same plan, pricing version, cost edition and every original supplier source.',\n      {...quoted,archive:path,directory:path},['id','quoteId','quoteSha256','archive','directory'],write),\n  ];\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/commercial-tariffs.mjs",
      "gitBlob": "be5e0e159bc511eed5ffb54843a346138472bf62",
      "bytes": 4661,
      "sha256": "eca538eb0f3f5b061e21a2343466dcdc83a364686c2c910ee770221a3bcb6993",
      "content": "// MIT. Original tariff-to-quotation lifecycle, source receiving and complete retained file reads.\nimport {MAX_RETAINED_CHUNK_BYTES} from '../retained-file-contracts.mjs';\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};\nconst sha={type:'string',pattern:'^[a-f0-9]{64}$'};\nconst text=maxLength=>({type:'string',minLength:1,maxLength});\nconst path=text(4096),selected={id:uuid,expectedRevision:sha};\nconst authoring={pricingDirectory:path,pricingConfig:path,pricingSnapshot:path,pricingHistory:path};\nconst quoted={...selected,revision:sha,sourceId:sha,quoteId:uuid,quoteSha256:sha};\nexport function commercialTariffTools(tool){\n  const read={readOnly:true,idempotent:true},write={idempotent:true};\n  return [\n    tool('merchant_case_commercial_tariff_status','Read this saved case, attached original tariff sources and active original listener requests. Recovery stays with the native selection, backup and case UUIDs.',\n      {id:uuid},['id'],read),\n    tool('merchant_case_commercial_tariff_catalog','Open original pricing and tariff history from its private directory/configuration and exactly one saved snapshot or history file. Lists original completed and pending selection requests without saving a new pricing selection.',\n      {...selected,...authoring},['id','pricingDirectory','pricingConfig'],read),\n    tool('merchant_case_commercial_tariff_selection','Inspect one exact original tariff portfolio and retained scenario/pricing result using the original portfolio validator. Pending original pricing operations remain with their existing UUIDs.',\n      {...selected,...authoring,selectionRequestId:uuid},['id','pricingDirectory','pricingConfig','selectionRequestId'],read),\n    tool('merchant_case_commercial_tariff_capture','Capture a completed original tariff selection, its two saved native results and matching complete pricing backup. Retain backupRequestId, selectionRequestId, exact input and destination for recovery. A completed capture can reopen after the authoring paths move.',\n      {...selected,...authoring,selectionRequestId:uuid,backupRequestId:uuid,directory:path},\n      ['id','selectionRequestId','backupRequestId','directory'],write),\n    tool('merchant_case_commercial_tariff_inspect','Verify the retained tariff source and full pricing backup, including every file in the later completed native pricing version. Returns original tier, quantity, uniform rate, rounding and file descriptors.',\n      {...selected,directory:path,expectedSourceSha256:sha},['id','directory'],read),\n    tool('merchant_case_commercial_tariff_attach','Attach the reviewed source to the current case using three original requests: pricing receive, backup attachment and tariff material. Keep all three UUIDs, original revision, actor, source hash and merchant/source reason after an interrupted response.',\n      {...selected,directory:path,expectedSourceSha256:sha,pricingRequestId:uuid,backupAttachmentRequestId:uuid,\n        tariffAttachmentRequestId:uuid,actor:text(200),bindingReason:text(4000)},\n      ['id','expectedRevision','directory','expectedSourceSha256','pricingRequestId','backupAttachmentRequestId','tariffAttachmentRequestId','actor','bindingReason'],write),\n    tool('merchant_case_commercial_tariff_case','Inspect an attached tariff or the exact saved quote tariff. Optional explicit monthlyRequests invokes the original tariff calculator and original saved-rate usage calculation side by side; it does not change the saved unit price.',\n      {...quoted,monthlyRequests:{type:'string',pattern:'^(0|[1-9][0-9]*)$',maxLength:16}},['id'],read),\n    tool('merchant_case_commercial_tariff_restore','Restore the original full pricing backup belonging to the exact quote, then receive and reopen its original selected tariff portfolio. Keep the archive outside the separate restore directory. Original native source/request identities are retained.',\n      {...quoted,archive:path,directory:path},['id','quoteId','quoteSha256','archive','directory'],write),\n    tool('merchant_case_commercial_tariff_file','Read the exact retained tariff source or original selected portfolio through the existing bounded file reader. Continue with readId, expectedSha256 and nextOffset. Existing merchant_case_commercial_file_reads/file_release manage these same reads; full case delivery uses merchant_case_export.',\n      {id:uuid,revision:sha,sourceId:sha,kind:{enum:['SOURCE','PORTFOLIO']},readId:uuid,expectedSha256:sha,\n        offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES}},\n      ['id','revision','sourceId','kind'],read),\n  ];\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/commercial.mjs",
      "gitBlob": "ef0f03942a88dfb65d1263ead77ab14720fe09cc",
      "bytes": 9277,
      "sha256": "d79bc59f73d63a14f4b603ee9439557a93754924c159ed38eb39a70bc26b621d",
      "content": "import {commercialReceivingTools} from './commercial-receiving.mjs';\nimport {commercialTariffTools} from './commercial-tariffs.mjs';\n// MIT. Quotation controls use the configured original SF74 case writer.\nimport {MAX_MATERIAL_BYTES} from '../../../stellar/scf-starforge-20261009/sf74-merchant-support-console/commissioning.mjs';\nimport {MAX_RETAINED_CHUNK_BYTES} from '../retained-file-contracts.mjs';\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};\nconst digest={type:'string',pattern:'^[a-f0-9]{64}$'};\nconst text=maxLength=>({type:'string',maxLength});\nconst object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});\nconst nullable=value=>({anyOf:[value,{type:'null'}]});\nconst rows=items=>({type:'array',maxItems:500,items});\nconst draft=object({parentId:nullable(uuid),title:text(400),customer:object({name:text(500),contact:text(2000)}),\n  currency:{const:'USD'},implementationSourceId:text(200),serviceSourceId:text(200),pricingSourceId:text(200),validThrough:text(10),\n  implementation:object({lines:rows(object({id:text(200),taskId:nullable(text(200)),title:text(2400),hours:text(40),rateUsd:text(40)}))}),\n  service:object({period:{const:'MONTH'},lines:rows(object({id:text(200),commitmentId:nullable(text(200)),title:text(2400),quantity:text(40),unitUsd:text(40)}))}),\n  pricing:object({routes:rows(object({routeId:text(200),monthlyRequests:text(24)}))}),\n  terms:object({scope:text(64000),deliverables:text(64000),exclusions:text(64000),payment:text(64000),acceptance:text(64000)}),\n  notes:text(16000)});\ndraft.properties.tariffSourceId=text(200);\ndraft.properties.performanceSourceId=text(200);\nconst selected={id:uuid,expectedRevision:digest},change={...selected,requestId:uuid,actor:text(200)};\nconst implementationSelection={quoteId:uuid,quoteSha256:digest,acceptanceId:uuid,\n  resolutions:{type:'object',additionalProperties:{enum:['accepted','current']}}};\nexport function commercialTools(tool) {\n  const read={readOnly:true,idempotent:true},write={idempotent:true};\n  return [\n    ...commercialReceivingTools(tool),\n    ...commercialTariffTools(tool),\n    tool('merchant_case_commercial','Open the complete original saved quotation workspace: implementation editions, service terms, received SF97 pricing sources, unfinished draft, immutable quotes, actual customer responses and accepted-quote implementation adoption. Keep its current case revision for a new change.',\n      {id:uuid,revision:digest},['id'],read),\n    tool('merchant_case_commercial_preview','Review explicit work hours, service fees and monthly route requests against the retained original sources. Returns exact decimal calculations, a customer-readable proposal and reviewSha256. No case write.',\n      {...selected,draft},['id','expectedRevision','draft'],read),\n    tool('merchant_case_commercial_save_draft','Retain the complete unfinished quotation as an original implementation material. Keep requestId, actor, original case revision and exact draft across an interrupted reply; the original event replays after later edits.',\n      {...change,draft},['id','expectedRevision','requestId','actor','draft'],write),\n    tool('merchant_case_commercial_publish','Save an immutable quote edition from the exact reviewed draft and source bindings. A revision names its original parent. Customer acceptance is a separate recorded response.',\n      {...change,draft,reviewSha256:digest,parentId:nullable(uuid)},['id','expectedRevision','requestId','actor','draft','reviewSha256'],write),\n    tool('merchant_case_commercial_receive_pricing','Receive all five exact source files exported from an existing original SF97 saved plan. The source reproduces the native scenario review and binds its original save request. Retain the complete sourceText, sourceSha256 and same request UUID after a lost reply.',\n      {...change,sourceText:text(MAX_MATERIAL_BYTES),sourceSha256:digest},\n      ['id','expectedRevision','requestId','actor','sourceText','sourceSha256'],write),\n    tool('merchant_case_commercial_receive','Record an actual customer acceptance, requested revision or decline for the exact immutable quotation bytes. Include the original response time and source reference. This preserves the implementation and service receiving states.',\n      {...change,quoteId:uuid,quoteSha256:digest,status:{enum:['ACCEPTED','REVISION_REQUESTED','DECLINED']},\n        observedAt:text(24),source:text(4096),note:text(16000)},\n      ['id','expectedRevision','requestId','actor','quoteId','quoteSha256','status','observedAt','source'],write),\n    tool('merchant_case_commercial_preview_implementation','Preview how an accepted quote creates or updates the saved implementation. Returns changes, conflicts and reviewSha256. Resolutions select accepted or current values using the returned conflict keys.',\n      {...selected,...implementationSelection},['id','expectedRevision','quoteId','quoteSha256'],read),\n    tool('merchant_case_commercial_adopt_implementation','Apply the reviewed accepted quote through the original case writer. Keep the exact case revision, immutable quote, recorded acceptance, reviewSha256, resolutions and requestId for identical recovery after an interrupted reply.',\n      {...change,...implementationSelection,reviewSha256:digest,note:text(16000)},\n      ['id','expectedRevision','requestId','actor','quoteId','quoteSha256','acceptanceId','reviewSha256'],write),\n    tool('merchant_case_commercial_compare','Compare two retained quote editions, exact decimal amounts, original source bindings, customer terms and their recorded responses.',\n      {...selected,beforeId:uuid,afterId:uuid},['id','expectedRevision','beforeId','afterId'],read),\n    tool('merchant_case_commercial_file','Read a complete retained customer Markdown or machine quotation through the original bounded file reader. The exact saved case revision reopens after later edits. Continue with readId, expectedSha256 and nextOffset; cold reopen uses the same selection and expectedSha256. Use merchant_case_export for the complete case.',\n      {id:uuid,revision:digest,quoteId:uuid,quoteSha256:digest,kind:{enum:['QUOTE','QUOTE_JSON']},\n        readId:uuid,expectedSha256:digest,offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES}},\n      ['id','revision','quoteId','quoteSha256','kind'],read),\n    tool('merchant_case_commercial_performance_preview','Review a complete original SF97 recorded usage source against its saved customer quote and exact tariff. Recomputes the native usage, payment identities, schedule arithmetic and original source files before returning the review identity.',\n      {...selected,sourceText:text(MAX_MATERIAL_BYTES),sourceSha256:digest,quoteId:uuid,quoteSha256:digest,tariffSourceId:digest},\n      ['id','expectedRevision','sourceText','sourceSha256','quoteId','quoteSha256'],read),\n    tool('merchant_case_commercial_performance_receive','Save the complete reviewed native usage source as original case material bound to the measured customer quote. Retain sourceText, sourceSha256, quote identities, reviewSha256, actor, requestId and expectedRevision unchanged to resume the original request.',\n      {...change,sourceText:text(MAX_MATERIAL_BYTES),sourceSha256:digest,quoteId:uuid,quoteSha256:digest,tariffSourceId:digest,reviewSha256:digest},\n      ['id','expectedRevision','requestId','actor','sourceText','sourceSha256','quoteId','quoteSha256','reviewSha256'],write),\n    tool('merchant_case_commercial_performance_revision','Prepare the ordinary quote draft for the measured quotation or a later edition. Enter an explicit whole proposedMonthlyRequests and optionally a newer saved tariff source for the same route. Retains customer scope, implementation, service and quote ancestry. Review and publish through the original quotation tools.',\n      {...selected,sourceId:digest,quoteId:uuid,quoteSha256:digest,proposedMonthlyRequests:{type:'string',pattern:'^[1-9][0-9]*$',maxLength:16},targetTariffSourceId:digest},\n      ['id','expectedRevision','sourceId','quoteId','quoteSha256','proposedMonthlyRequests'],read),\n    tool('merchant_case_commercial_performance_file','Read the full original performance source, complete case attachment or readable report. Continue the original file using readId, expectedSha256 and nextOffset; cold reopen uses the same saved case revision, source and expectedSha256. Original commercial file status and release tools also manage these reads.',\n      {id:uuid,revision:digest,sourceId:digest,kind:{enum:['SOURCE','ATTACHMENT','REPORT']},readId:uuid,expectedSha256:digest,\n        offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES}},\n      ['id','revision','sourceId','kind'],read),\n    tool('merchant_case_commercial_file_reads','List current original quotation file reads for this case, including exact descriptors and continuation IDs.',\n      {id:uuid},['id'],read),\n    tool('merchant_case_commercial_file_release','Close an original quotation file read after partial receiving. The immutable quote stays in the saved case for later reopen.',\n      {id:uuid,readId:uuid},['id','readId'],write),\n  ];\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/pricing-costs.mjs",
      "gitBlob": "fe9616cbca075852d6ac68c1c0760958c3a06a17",
      "bytes": 12182,
      "sha256": "aae827bfeb38bf0d72fd6029b238a29d89de77c35d5c8dee77234c3cd5ea4ad2",
      "content": "// MIT. Original tool metadata; provider runtimes load only when selected.\nimport { MAX_RETAINED_CHUNK_BYTES } from '../retained-file-contracts.mjs';\nimport { MAX_DOCUMENT } from '../../../stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/economics/limits-contracts.mjs';\n\nconst alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};\n\nconst uuid={type:'string',pattern:'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'};\n\nconst hash={type:'string',pattern:'^[0-9a-f]{64}$'};\n\nconst text={type:'string'};\n\nconst nullableText={anyOf:[text,{type:'null'}]};\n\nconst revision={anyOf:[hash,{type:'null'}]};\n\nconst object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});\n\nconst anyObject={type:'object'};\n\nconst base={workspace:alias};\n\nconst read={readOnly:true,idempotent:true};\n\nconst write={idempotent:true};\n\nconst page={offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:100}};\n\nconst delimiter={type:'string',enum:[',','\\t',';','|']};\n\nconst period=object({from:text,through:text});\n\nconst kind={type:'string',enum:['BILL','CREDIT_NOTE','QUOTE','USAGE','ACCOUNTING','SUPPORT']};\n\nconst metadata=object({label:text,name:text,kind,supplier:text,reference:text,period:{anyOf:[period,{type:'null'}]},note:text,url:nullableText},['label','name','kind']);\n\nconst field={anyOf:[object({column:text,trim:{type:'boolean'}},['column']),object({constant:text,trim:{type:'boolean'}},['constant']),{type:'null'}]};\n\nconst mapping=object(Object.fromEntries(['reference','supplier','kind','currency','amount','quantity','unit','description'].map(name=>[name,field])),[]);\n\nconst pinnedInput={input:alias,expectedSha256:hash,expectedBytes:{type:'integer',minimum:1,maximum:MAX_DOCUMENT}};\n\nconst receivedDraft=object({packageId:uuid,requestId:uuid});\nconst bookAdjustments=object({label:text,reason:text,periodAlignment:object({confirmed:{type:'boolean'},reason:text}),\n  coverage:{type:'array',maxItems:10000,items:anyObject}},[]);\nconst bookInput={book:anyObject,bookSource:object(pinnedInput),receivedDraft,bookAdjustments};\nconst receivingSelection={packageId:uuid,expectedPackageSha256:hash,pricingVersion:uuid,expectedPricingReportSha256:hash,\n  routeMappings:{type:'array',maxItems:10000,items:object({from:text,to:nullableText})},label:text,reason:text};\nconst receivingViews={type:'string',enum:['routes','routeCosts','units','lines','allocations','issues','groups','coverage',\n  'imports','sources','context','routeMappings','sourceMappings','lineMappings']};\n\nconst view={type:'string',enum:['routes','routeCosts','units','lines','allocations','issues','groups','coverage','imports','sources','pricingLinks','context']};\n\nconst routeIds={type:'array',minItems:1,maxItems:10000,items:text};\n\nconst proposal={edition:uuid,basis:{type:'string',enum:['BILLED','QUOTED']},routeIds};\n\nconst fileSelection={...base,kind:{type:'string',enum:['source','edition','export','received']},id:uuid};\n\nconst costToolDefinitions=[\n  ['merchant_pricing_cost_state','Read exact native cost/pricing revisions, counts and declared source/booking aliases. Whole source and history lists have separate paged operations.',base,['workspace'],read],\n  ['merchant_pricing_cost_list','Page the complete native originals, pricing reviews, cost editions or export receipts. after is the original opaque cursor; it does not change source identities.',{...base,kind:{type:'string',enum:['SOURCES','PRICING','EDITIONS','EXPORTS','RECEIVED']},after:nullableText,limit:page.limit},['workspace','kind'],read],\n  ['merchant_pricing_cost_inputs','List host-declared original source or complete cost-book files. This reveals aliases and labels; it does not read their contents or expose filesystem paths.',{...base,kind:{type:'string',enum:['SOURCE','BOOK','PACKAGE']},...page},['workspace'],read],\n  ['merchant_pricing_cost_input','Inspect the exact current SHA-256 and byte count of one host-declared source or complete cost book before selecting it. No source is imported.',{...base,kind:{type:'string',enum:['SOURCE','BOOK','PACKAGE']},input:alias},['workspace','kind','input'],read],\n  ['merchant_pricing_cost_upload','Retain one inspected original host file in the native immutable source store. Keep the exact expected bytes/hash, metadata and requestId across retry. Confirmed source IDs reopen even after the host file moves.',{...base,...pinnedInput,requestId:uuid,metadata},['workspace','input','expectedSha256','expectedBytes','requestId','metadata'],write],\n  ['merchant_pricing_cost_receive','Receive the complete original COST_EDITION TAR selected by its host-declared PACKAGE alias, byte count and SHA-256. Retain requestId, label and name across retry. The committed package and all original files reopen after the host input moves.',{...base,input:alias,expectedSha256:hash,expectedBytes:{type:'integer',minimum:1,maximum:512*1024*1024},requestId:uuid,label:text,name:text},['workspace','input','expectedSha256','expectedBytes','requestId','label','name'],write],\n  ['merchant_pricing_cost_received','Reopen a complete received cost package and page its original report, supplier sources, exact file set or local receiving drafts. Original TAR bytes use the received manifest/download kind.',{...base,packageId:uuid,view:{type:'string',enum:['routes','routeCosts','units','lines','allocations','issues','groups','coverage','imports','sources','files','drafts']},...page},['workspace','packageId'],read],\n  ['merchant_pricing_cost_receiving_review','Review every explicit original-to-local route mapping against a selected saved local pricing report. Original amounts remain exact; unassigned routes retain their money, and local coverage/period assessment starts unconfirmed. No local cost draft is written.',{...base,...receivingSelection,view:receivingViews,...page},['workspace',...Object.keys(receivingSelection)],read],\n  ['merchant_pricing_cost_receiving_draft','Retain the exact reviewed supplier originals through the native source store and save the complete local receiving draft. Its stable receivedDraft selector can feed cost_preview/cost_save with explicit local coverage and alignment adjustments.',{...base,...receivingSelection,reviewSha256:hash,requestId:uuid},['workspace',...Object.keys(receivingSelection),'reviewSha256','requestId'],write],\n  ['merchant_pricing_cost_capture','Capture the configured original supplier-usage or accounting file. This retains its native units and independent accounting groups; it does not infer an invoice or FX conversion.',{...base,kind:{type:'string',enum:['USAGE','ACCOUNTING']},requestId:uuid,label:text,reference:text,period:{anyOf:[period,{type:'null'}]},supplier:text,note:text},['workspace','kind','requestId'],write],\n  ['merchant_pricing_cost_source','Inspect a retained source with bounded CSV or native source rows. Whole original bytes remain downloadable; oversized display cells are explicitly marked and never rewrite them.',{...base,sourceId:uuid,delimiter,view:{type:'string',enum:['rows','headers','accounts','bindings','routes','options','keys','totals']},...page},['workspace','sourceId'],read],\n  ['merchant_pricing_cost_mapping','Apply an explicit original column/constant mapping and page every resulting sourceUUID:row line. The original file remains byte-identical and all row dispositions belong to the next native cost edition.',{...base,sourceId:uuid,delimiter,mapping,...page},['workspace','sourceId','mapping'],read],\n  ['merchant_pricing_cost_weights','Use the original exact signed allocation engine with explicit operator weights or retained HTTP-2xx counts. Quota dispatch units and billed money stay separate.',{...base,pricingVersion:uuid,line:object({amount:text,quantity:nullableText},['amount']),basis:{type:'string',enum:['OPERATOR_WEIGHT','HTTP_2XX_WEIGHT']},reason:text,routeIds,weights:{type:'array',minItems:1,maxItems:10000,items:object({routeId:text,weight:text})},...page},['workspace','pricingVersion','line','basis','reason'],read],\n  ['merchant_pricing_cost_preview','Review an inline cost book or an exact host-declared complete book through the original native validator. Page full source, route, line, allocation, coverage and issue lists; no edition is saved.',{...base,...bookInput,view,...page},['workspace'],read],\n  ['merchant_pricing_cost_save','Save the complete reviewed book as an immutable native edition under the original compare-and-swap. Keep requestId, expectedRevision and the exact book contents across an ambiguous reply; a host book avoids the MCP request-size limit.',{...base,...bookInput,requestId:uuid,expectedRevision:revision},['workspace','requestId','expectedRevision'],write],\n  ['merchant_pricing_cost_request','Find a committed native source, cost edition or export by its original requestId. UNKNOWN means no committed match is visible; it does not claim an interrupted write never ran.',{...base,kind:{type:'string',enum:['SOURCE','EDITION','EXPORT','RECEIVED']},requestId:uuid},['workspace','kind','requestId'],read],\n  ['merchant_pricing_cost_edition','Reopen one exact native cost edition and page its original normalized inputs, report, source binding and pricing links. Complete files remain available through the cost manifest/file operations.',{...base,edition:uuid,view,...page},['workspace','edition'],read],\n  ['merchant_pricing_cost_compare','Compare exact retained native cost reports and page changed lines, routes or currency/basis groups. Different input periods and missing amounts remain explicit.',{...base,before:uuid,after:uuid,view:{type:'string',enum:['changes','routes','groups']},...page},['workspace','before','after'],read],\n  ['merchant_pricing_cost_proposal','Review original cost-per-fulfilled proposals for explicitly selected routes and either quoted or billed USD. The native hash binds the whole selection; no price or payment term is changed.',{...base,...proposal,view:{type:'string',enum:['changes','originalRoutes','issues']},...page},['workspace','edition','basis','routeIds'],read],\n  ['merchant_pricing_cost_apply','Save an explicitly reviewed cost proposal through the original pricing model. Native per-route eligibility, exact proposal hash, original pricing expectedRevision and stable requestId remain authoritative; atomic payment amounts are unchanged.',{...base,...proposal,proposalSha256:hash,requestId:uuid,expectedPricingRevision:revision,label:text},['workspace','edition','basis','routeIds','proposalSha256','requestId','expectedPricingRevision','label'],write],\n  ['merchant_pricing_cost_export','Create the original complete cost-edition TAR or closed pricing/cost/scenario workspace backup. Repeat the same requestId and exact selectors after interruption, then download its original immutable archive.',{...base,kind:{type:'string',enum:['COST_EDITION','WORKSPACE_BACKUP']},requestId:uuid,edition:uuid},['workspace','kind','requestId'],write],\n  ['merchant_pricing_cost_manifest','Inspect an immutable original source, cost-edition file set or completed native export with exact file bytes and hashes. Export is the requestId from the original native package receipt.',fileSelection,['workspace','kind','id'],read],\n  ['merchant_pricing_cost_file','Read a bounded SHA-pinned chunk of the inspected original source, edition or native archive. Preserve kind/id/file/manifest hash, expected file hash, readId and nextOffset when continuing. Archives stream from the native verified descriptor.',{...fileSelection,file:text,expectedManifestSha256:hash,expectedSha256:hash,readId:uuid,offset:page.offset,limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES}},['workspace','kind','id','file','expectedManifestSha256'],read],\n  ['merchant_pricing_cost_file_release','Release only the selected workspace’s temporary original-file/archive read. This never removes an original or saved package.',{...base,readId:uuid},['workspace','readId'],read],\n];\n\nexport { costToolDefinitions, base, read, nullableText, page, alias, pinnedInput, uuid, metadata, write, text, period, delimiter, mapping, object, routeIds, bookInput, view, revision, proposal, hash, fileSelection, kind, field, anyObject };\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/pricing-performance.mjs",
      "gitBlob": "4804678ea1a472ceccb0c5f17b0ccc54d9996939",
      "bytes": 8821,
      "sha256": "f9703988fbc7b927b931c0e19c8f07be0b8f6137d1d0b977f30b6b043291d921",
      "content": "// MIT. Existing Pricing provider metadata for saved recorded-usage performance.\nimport {MAX_RETAINED_CHUNK_BYTES} from '../retained-file-contracts.mjs';\nconst object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});\nconst arbitrary={type:'object',additionalProperties:true};\nconst alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'};\nconst digest={type:'string',pattern:'^[a-f0-9]{64}$'};\nconst nullable=value=>({anyOf:[value,{type:'null'}]});\nconst label={type:'string',minLength:1,maxLength:100};\nconst monthly={type:'string',pattern:'^[1-9][0-9]*$',maxLength:16};\nconst base={workspace:alias};\nconst pagination={after:{type:'string',pattern:'^(0|[1-9][0-9]*)$'},limit:{type:'integer',minimum:1,maximum:100}};\nconst inputs=object({selectionRequestId:uuid,usageVersion:uuid,\n  basis:{type:'string',enum:['HTTP_2XX','NATIVE_SUCCESS','INBOX_ACCEPTED','SERVICE_CONSUMED_REQUESTS','SERVICE_2XX']},\n  optionId:nullable(digest),costEdition:nullable(uuid),costBasis:{type:'string',enum:['BILLED','QUOTED']},\n  servicePeriodSourceId:nullable(digest)},['selectionRequestId','usageVersion','basis']);\nconst snapshot=object({name:{type:'string',minLength:1,maxLength:300},text:{type:'string',maxLength:48*1024*1024}});\nconst source=object({schema:{type:'string',enum:['stellar-forge.merchant-tariff-performance-source.v1']},\n  id:digest,record:arbitrary,originals:arbitrary});\nconst selection={type:'object',properties:{schema:{type:'string',enum:['stellar-forge.merchant-tariff-selection.v1']},\n  planId:uuid,comparisonId:digest,tariffReviewSha256:digest,selectionSha256:digest,sourceSelection:arbitrary,\n  scenarioPlanInput:arbitrary,pricingInput:arbitrary},required:['schema','planId','comparisonId','tariffReviewSha256',\n  'selectionSha256','sourceSelection','scenarioPlanInput','pricingInput'],additionalProperties:true};\nconst read={readOnly:true,idempotent:true};\nconst method=name=>'merchant_pricing_performance_'+name;\nexport const PERFORMANCE_MCP_OPERATIONS=Object.freeze({\n  state:method('state'),sources:method('sources'),source:method('source'),servicePeriods:method('service_periods'),\n  captureServicePeriod:method('capture_service_period'),preview:method('preview'),save:method('save'),\n  list:method('list'),load:method('load'),capture:method('capture'),download:method('download'),\n  inspect:method('inspect'),receive:method('receive'),proposal:method('proposal'),\n  saveProposal:method('save_proposal'),commitProposal:method('commit_proposal')\n});\nexport const performanceToolDefinitions=[\n  [PERFORMANCE_MCP_OPERATIONS.state,'Read original saved Pricing sources, completed tariff selections, recorded performance and captured service periods through the existing opened Pricing alias.',base,['workspace'],read],\n  [PERFORMANCE_MCP_OPERATIONS.sources,'Page the existing immutable Pricing source reviews. Retain original UUIDs and nextAfter; the native source picker does not recapture operations.',{...base,...pagination},['workspace'],read],\n  [PERFORMANCE_MCP_OPERATIONS.source,'Read one complete original Pricing usage source, its actual observed period, HTTP/native option quantities and matching supplier editions.',{...base,version:uuid},['workspace','version'],read],\n  [PERFORMANCE_MCP_OPERATIONS.servicePeriods,'Page retained original opening/closing service-period comparisons. Request counts and purchased service units remain distinct.',{...base,...pagination},['workspace'],read],\n  [PERFORMANCE_MCP_OPERATIONS.captureServicePeriod,'Retain both complete original service snapshot texts under the same capture request UUID. The maintained service-period compiler validates their entitlement, allowance and request transitions.',{...base,requestId:uuid,label,opening:snapshot,closing:snapshot},['workspace','requestId','label','opening','closing'],{idempotent:true}],\n  [PERFORMANCE_MCP_OPERATIONS.preview,'Calculate performance for an explicitly selected completed tariff quote and recorded usage version. Exact native option, supplier cost and service source selectors retain their separate original populations.',{...base,inputs},['workspace','inputs'],read],\n  [PERFORMANCE_MCP_OPERATIONS.save,'Save the complete reviewed performance and every original source file. Preserve requestId, inputs and performanceSha256 across an interrupted save.',{...base,requestId:uuid,label,performanceSha256:digest,inputs},['workspace','requestId','label','performanceSha256','inputs'],{idempotent:true}],\n  [PERFORMANCE_MCP_OPERATIONS.list,'Page immutable saved performance summaries using the returned nextAfter value.',{...base,...pagination},['workspace'],read],\n  [PERFORMANCE_MCP_OPERATIONS.load,'Reopen a saved performance and its original proposal/native selection recovery requests. Preserve every original request UUID when continuing.',{...base,performanceId:uuid},['workspace','performanceId'],read],\n  [PERFORMANCE_MCP_OPERATIONS.capture,'Capture all four complete performance exports in the existing retained-file workflow. Returns the source ID, native record, manifest and exact file hashes; use download for every original byte.',{...base,performanceId:uuid},['workspace','performanceId'],read],\n  [PERFORMANCE_MCP_OPERATIONS.download,'Read SHA-pinned chunks from the complete captured performance source, JSON, HTML or CSV. Repeat the inspected manifest digest and returned readId/expectedSha256/nextOffset; original pricing_file_release closes a read.',{...base,performanceId:uuid,\n    file:{type:'string',enum:['source.json','review.json','review.html','usage.csv','manifest.json']},\n    expectedManifestSha256:digest,expectedSha256:digest,readId:uuid,\n    offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES}},\n    ['workspace','performanceId','file','expectedManifestSha256'],read],\n  [PERFORMANCE_MCP_OPERATIONS.inspect,'Read-only preflight of the complete portable performance envelope: recomputes its original source-bound calculations and retains complete original file descriptors.',{...base,source},['workspace','source'],read],\n  [PERFORMANCE_MCP_OPERATIONS.receive,'Receive the fully inspected original performance envelope into the existing private Pricing workspace with unchanged source/request identities and original paired service sources.',{...base,source},['workspace','source'],{idempotent:true}],\n  [PERFORMANCE_MCP_OPERATIONS.proposal,'Calculate a revised monthly tariff quote using an explicit positive proposedMonthlyRequests string and the original selected tariff Pricing source. Recorded-period quantity remains separately identified.',{...base,performanceId:uuid,proposedMonthlyRequests:monthly},['workspace','performanceId','proposedMonthlyRequests'],read],\n  [PERFORMANCE_MCP_OPERATIONS.saveProposal,'Save the reviewed monthly proposal through the original tariff workspace, then return its full native commercial selection. Exact UUID replay recovers the saved plan before obtaining a current native selection.',{...base,performanceId:uuid,proposedMonthlyRequests:monthly,proposalSha256:digest,requestId:uuid,label},\n    ['workspace','performanceId','proposedMonthlyRequests','proposalSha256','requestId','label'],{idempotent:true}],\n  [PERFORMANCE_MCP_OPERATIONS.commitProposal,'Save the explicitly reviewed complete merchant terms through the original scenario and Pricing writers. Retain the exact full selection, proposal request and both native request UUIDs for recovery.',{...base,performanceId:uuid,proposalRequestId:uuid,selection,planRequestId:uuid,pricingRequestId:uuid},\n    ['workspace','performanceId','proposalRequestId','selection','planRequestId','pricingRequestId'],{idempotent:true}]\n];\nexport const performanceClientOperations=Object.freeze({\n  'performance-state':PERFORMANCE_MCP_OPERATIONS.state,'performance-sources':PERFORMANCE_MCP_OPERATIONS.sources,\n  'performance-source':PERFORMANCE_MCP_OPERATIONS.source,'performance-service-periods':PERFORMANCE_MCP_OPERATIONS.servicePeriods,\n  'performance-capture-service':PERFORMANCE_MCP_OPERATIONS.captureServicePeriod,'performance-preview':PERFORMANCE_MCP_OPERATIONS.preview,\n  'performance-save':PERFORMANCE_MCP_OPERATIONS.save,'performance-list':PERFORMANCE_MCP_OPERATIONS.list,\n  'performance-load':PERFORMANCE_MCP_OPERATIONS.load,'performance-capture':PERFORMANCE_MCP_OPERATIONS.capture,\n  'performance-download':PERFORMANCE_MCP_OPERATIONS.download,'performance-inspect':PERFORMANCE_MCP_OPERATIONS.inspect,\n  'performance-receive':PERFORMANCE_MCP_OPERATIONS.receive,'performance-proposal':PERFORMANCE_MCP_OPERATIONS.proposal,\n  'performance-save-proposal':PERFORMANCE_MCP_OPERATIONS.saveProposal,'performance-commit-proposal':PERFORMANCE_MCP_OPERATIONS.commitProposal\n});\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/pricing-tariffs.mjs",
      "gitBlob": "12509ce34cc12edb7673de3b2b715f6f02bec65d",
      "bytes": 11254,
      "sha256": "b21265d27bf46de8f1d698768aca8bf1b715a58766993955c77fc7e90623db1f",
      "content": "// MIT. Source-owned metadata for the original Pricing workspace tariff workflow.\nimport { MAX_RETAINED_CHUNK_BYTES } from '../retained-file-contracts.mjs';\n\nconst object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});\nconst arbitrary={type:'object',additionalProperties:true};\nconst alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'};\nconst digest={type:'string',pattern:'^[a-f0-9]{64}$'};\nconst usd={type:'string',pattern:'^(0|[1-9][0-9]*)(\\\\.[0-9]{1,6})?$'};\nconst whole={anyOf:[{type:'integer',minimum:0,maximum:Number.MAX_SAFE_INTEGER},\n  {type:'string',pattern:'^(0|[1-9][0-9]*)$',maxLength:16}]};\nconst positive={anyOf:[{type:'integer',minimum:1,maximum:Number.MAX_SAFE_INTEGER},\n  {type:'string',pattern:'^[1-9][0-9]*$',maxLength:16}]};\nconst id={type:'string',pattern:'^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$'};\nconst routeId={type:'string',pattern:'^[A-Za-z0-9_-]{1,80}$'};\nconst label={type:'string',minLength:1,maxLength:100};\nconst base={workspace:alias};\nconst tier=object({upTo:{anyOf:[positive,{type:'null'}]},unitPriceUsd:usd});\nconst tariff=object({id,label:{type:'string',minLength:1,maxLength:120},routeId,\n  mode:{type:'string',enum:['graduated','volume']},\n  tiers:{type:'array',minItems:1,maxItems:64,items:tier}});\nconst preview={...base,version:uuid,tariffs:{type:'array',minItems:1,maxItems:12,items:tariff},\n  volumes:{type:'array',minItems:1,maxItems:24,items:whole}};\nconst retainedSelection={type:'object',properties:{\n  schema:{type:'string',enum:['stellar-forge.merchant-tariff-selection.v1']},\n  planId:uuid,comparisonId:digest,tariffReviewSha256:digest,selectionSha256:digest,\n  sourceSelection:arbitrary,scenarioPlanInput:arbitrary,pricingInput:arbitrary\n},required:['schema','planId','comparisonId','tariffReviewSha256','selectionSha256',\n  'sourceSelection','scenarioPlanInput','pricingInput'],additionalProperties:true};\nconst portfolio=object({schema:{type:'string',enum:['stellar-forge.merchant-tariff-portfolio.v1']},\n  plans:{type:'array',items:arbitrary},selections:{type:'array',items:arbitrary},sha256:digest});\nconst fileRead={view:{type:'string',enum:['manifest','file']},\n  file:{type:'string',minLength:1,maxLength:4096},expectedManifestSha256:digest,\n  expectedSha256:digest,readId:uuid,offset:{type:'integer',minimum:0},\n  limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES}};\nconst atomic={type:'string',pattern:'^[1-9][0-9]{0,38}$'};\nconst payment={routeId,paymentIndex:{type:'integer',minimum:0},expectedAmount:atomic};\nconst reprice={...base,version:uuid,sellerSha256:digest,\n  edits:{type:'array',minItems:1,items:object({...payment,amount:atomic})},\n  quoteValuations:{type:'array',minItems:1,items:object({...payment,atomicUnits:atomic,usd,\n    basis:{type:'string',minLength:4,maxLength:300}})}};\nconst saved={requestId:uuid,expectedRevision:{anyOf:[digest,{type:'null'}]},label};\nconst read={readOnly:true,idempotent:true};\n\nexport const TARIFF_MCP_OPERATIONS=Object.freeze({\n  state:'merchant_pricing_tariff_state',\n  source:'merchant_pricing_tariff_source',\n  preview:'merchant_pricing_tariff_preview',\n  save:'merchant_pricing_tariff_save',\n  list:'merchant_pricing_tariff_list',\n  load:'merchant_pricing_tariff_load',\n  selection:'merchant_pricing_tariff_selection',\n  commitSelection:'merchant_pricing_tariff_commit_selection',\n  download:'merchant_pricing_tariff_download',\n  bundle:'merchant_pricing_tariff_bundle',\n  inspectPortfolio:'merchant_pricing_tariff_inspect_portfolio',\n  receive:'merchant_pricing_tariff_receive',\n  repricingSource:'merchant_pricing_tariff_repricing_source',\n  downloadRepricing:'merchant_pricing_tariff_download_repricing',\n  downloadPricing:'merchant_pricing_tariff_download_pricing',\n  previewRepricing:'merchant_pricing_tariff_repricing_preview',\n  saveRepricing:'merchant_pricing_tariff_repricing_save',\n  stageRepricing:'merchant_pricing_tariff_repricing_stage'\n});\n\nexport const tariffToolDefinitions=[\n  [TARIFF_MCP_OPERATIONS.state,'Read the original Pricing state and saved tariff plans and selection recovery operations. Uses the existing opened Pricing alias.',base,['workspace'],read],\n  [TARIFF_MCP_OPERATIONS.source,'Read a saved native Pricing version, complete selected routes and commercial inputs for tariff planning. Historical seller changes remain explicit.',{...base,version:uuid},['workspace','version'],read],\n  [TARIFF_MCP_OPERATIONS.preview,'Compare exact graduated or volume schedules at selected whole monthly quantities. Shows actual volume-boundary drops, known costs, unknown inputs and the explicit rounded uniform per-request quote. The existing ledger retains fixed per-call settlement.',preview,['workspace','version','tariffs','volumes'],read],\n  [TARIFF_MCP_OPERATIONS.save,'Save the exact reviewed tariff schedules and quantities with their tariffReviewSha256, label and stable requestId. Repeat the original request after an interrupted reply.',{...preview,requestId:uuid,label,tariffReviewSha256:digest},['workspace','version','tariffs','volumes','requestId','label','tariffReviewSha256'],{idempotent:true}],\n  [TARIFF_MCP_OPERATIONS.list,'List saved tariff plans and retained original native selection operations, including operations available to resume.',base,['workspace'],read],\n  [TARIFF_MCP_OPERATIONS.load,'Load the complete retained tariff plan and exact review by its original planId.',{...base,planId:uuid},['workspace','planId'],read],\n  [TARIFF_MCP_OPERATIONS.selection,'Review one positive-volume comparison as an explicit fixed quote through the original scenario and Pricing engines. Returns complete commercial terms, current terms and the immutable selection body.',{...base,planId:uuid,comparisonId:digest},['workspace','planId','comparisonId'],read],\n  [TARIFF_MCP_OPERATIONS.commitSelection,'Commit the complete retained selection through the original scenario and Pricing writers. Both native request bodies are retained first. Preserve selection, planRequestId and pricingRequestId exactly across retries and process reopen.',{...base,selection:retainedSelection,planRequestId:uuid,pricingRequestId:uuid},['workspace','selection','planRequestId','pricingRequestId'],{idempotent:true}],\n  [TARIFF_MCP_OPERATIONS.download,'Inspect a complete tariff-plan file manifest, or read one SHA-pinned original file chunk. Default view:manifest; view:file requires file and expectedManifestSha256. Includes plan.json, tariffs.json and comparison.csv. Release temporary reads with merchant_pricing_file_release.',{...base,planId:uuid,...fileRead},['workspace','planId'],read],\n  [TARIFF_MCP_OPERATIONS.bundle,'Retain the full native tariff portfolio or select one original pricing request with selectionRequestId. The selected export contains its original plan and journal, including any pending result. Return the immutable file manifest; repeat portfolioSha256 to reopen those exact bytes after later saves or process restart. If both selectors are supplied, the retained export must contain exactly that selection and its plan. view:file uses only portfolioSha256 with original SHA-pinned chunks. The original Pricing backup accompanies this portfolio for receiving.',{...base,portfolioSha256:digest,selectionRequestId:uuid,...fileRead},['workspace'],{idempotent:true}],\n  [TARIFF_MCP_OPERATIONS.inspectPortfolio,'Validate the complete portfolio using the original read-only receiving source preflight after restoring its Pricing backup. Return its verified content digest, original plan/source identities and selection request/result identities. The whole input is checked; the reply summarizes those validated records. The receiver checks destination conflicts when receiving.',{...base,bundle:portfolio},['workspace','bundle'],read],\n  [TARIFF_MCP_OPERATIONS.receive,'Receive a complete original tariff portfolio after restoring its original Pricing backup. Validates complete saved reviews, source versions, original scenario/pricing request identities and existing completed native manifests before registering plans and selections.',{...base,bundle:portfolio},['workspace','bundle'],{idempotent:true}],\n  [TARIFF_MCP_OPERATIONS.repricingSource,'Read the original saved seller payment options, atomicAmount values, commercial terms, current price-decision revision and source/release availability.',{...base,version:uuid},['workspace','version'],read],\n  [TARIFF_MCP_OPERATIONS.downloadRepricing,'Inspect the original saved price-decision manifest or read an exact original decision/source-package file through the existing SHA-pinned file reader. Default view:manifest; view:file requires file and expectedManifestSha256.',{...base,decision:uuid,...fileRead},['workspace','decision'],read],\n  [TARIFF_MCP_OPERATIONS.downloadPricing,'Inspect the original saved Pricing manifest or read an exact original report, terms, seller or observation file through the existing SHA-pinned file reader. Default view:manifest; view:file requires file and expectedManifestSha256.',{...base,version:uuid,...fileRead},['workspace','version'],read],\n  [TARIFF_MCP_OPERATIONS.previewRepricing,'Review native payment amounts for the saved fixed quote through the original exact atomic conversion. Supply exactly one of quoteValuations or atomic edits; zero paid prices retain the original validation error.',reprice,['workspace','version','sellerSha256'],read],\n  [TARIFF_MCP_OPERATIONS.saveRepricing,'Save the original reviewed native amount decision with its unchanged reviewSha256, expectedRevision and stable requestId. Exact request replay resolves a previously completed save.',{...reprice,...saved,reviewSha256:digest},['workspace','version','sellerSha256','requestId','expectedRevision','label','reviewSha256'],{idempotent:true}],\n  [TARIFF_MCP_OPERATIONS.stageRepricing,'Stage the retained original seller source using the saved native decision and exact reviewSha256. The existing release store and stable release ID recover an interrupted stage; original merchant release controls own subsequent activation.',{...base,decision:uuid,reviewSha256:digest},['workspace','decision','reviewSha256'],{idempotent:true}]\n];\n\nexport const tariffClientOperations=Object.freeze({\n  'tariff-state':TARIFF_MCP_OPERATIONS.state,'tariff-source':TARIFF_MCP_OPERATIONS.source,\n  'tariff-preview':TARIFF_MCP_OPERATIONS.preview,'tariff-save':TARIFF_MCP_OPERATIONS.save,\n  'tariff-list':TARIFF_MCP_OPERATIONS.list,'tariff-load':TARIFF_MCP_OPERATIONS.load,\n  'tariff-selection':TARIFF_MCP_OPERATIONS.selection,'tariff-commit':TARIFF_MCP_OPERATIONS.commitSelection,\n  'tariff-manifest':TARIFF_MCP_OPERATIONS.download,'tariff-bundle':TARIFF_MCP_OPERATIONS.bundle,\n  'tariff-inspect':TARIFF_MCP_OPERATIONS.inspectPortfolio,'tariff-receive':TARIFF_MCP_OPERATIONS.receive,\n  'tariff-price-source':TARIFF_MCP_OPERATIONS.repricingSource,\n  'tariff-price-manifest':TARIFF_MCP_OPERATIONS.downloadRepricing,\n  'tariff-review-manifest':TARIFF_MCP_OPERATIONS.downloadPricing,\n  'tariff-price-preview':TARIFF_MCP_OPERATIONS.previewRepricing,\n  'tariff-price-save':TARIFF_MCP_OPERATIONS.saveRepricing,'tariff-price-stage':TARIFF_MCP_OPERATIONS.stageRepricing\n});\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/pricing.mjs",
      "gitBlob": "e859beadb758790f97156a177bbd8dbb76cf1f8d",
      "bytes": 12971,
      "sha256": "a39950e2b9410b299f7b1c1671519640ea5d02e219b8c03680a46a0bfcf638bf",
      "content": "// MIT. Original tool metadata; provider runtimes load only when selected.\nimport { costToolDefinitions } from './pricing-costs.mjs';\nimport { tariffToolDefinitions } from './pricing-tariffs.mjs';\nimport { performanceToolDefinitions } from './pricing-performance.mjs';\nimport { MAX_RETAINED_CHUNK_BYTES } from '../retained-file-contracts.mjs';\n\nconst alias = { type: 'string', pattern: '^[a-z0-9][a-z0-9_-]{0,63}$' };\n\nconst uuid = { type: 'string', pattern: '^[0-9a-f-]{36}$' };\n\nconst digest = { type: 'string', pattern: '^[0-9a-f]{64}$' };\n\nconst revision = { anyOf: [digest, { type: 'null' }] };\n\nconst nullableText = { anyOf: [{ type: 'string' }, { type: 'null' }] };\n\nconst usd = { type: 'string', pattern: '^(0|[1-9][0-9]*)(\\\\.[0-9]{1,6})?$' };\n\nconst optionalUsd = { anyOf: [usd, { type: 'null' }] };\n\nconst object = (properties, required = Object.keys(properties)) => ({ type: 'object', properties, required, additionalProperties: false });\n\nconst commercial = object({ merchantName: { type: 'string', minLength: 1, maxLength: 160 },\n  sharedMonthlyFixedUsd: optionalUsd,\n  routes: { type: 'object', properties: {}, additionalProperties: object({ unitPriceUsd: usd,\n    priceBasis: { type: 'string', minLength: 4, maxLength: 300 }, perFulfilledUsd: optionalUsd,\n    perChallengeUsd: optionalUsd, monthlyPaidTarget: { type: 'integer', minimum: 0 } }) } });\n\nconst selection = object({ kind: { type: 'string', enum: ['SESSION', 'DURABLE_HISTORY'] },\n  from: nullableText, to: nullableText, routeId: nullableText }, ['kind']);\n\nconst edits = { type: 'array', minItems: 1, items: object({\n  routeId: { type: 'string', pattern: '^[A-Za-z0-9_-]{1,80}$' }, paymentIndex: { type: 'integer', minimum: 0 },\n  expectedAmount: { type: 'string', pattern: '^[1-9][0-9]*$' }, amount: { type: 'string', pattern: '^[1-9][0-9]*$' } }) };\n\nconst base = { workspace: alias };\n\nconst priceInput = { ...base, sellerSha256: digest, snapshotSha256: digest, commercial };\n\nconst quoteValuations = { type: 'array', minItems: 1, items: object({\n  routeId: { type: 'string', pattern: '^[A-Za-z0-9_-]{1,80}$' },\n  paymentIndex: { type: 'integer', minimum: 0 },\n  expectedAmount: { type: 'string', pattern: '^[1-9][0-9]{0,38}$' },\n  atomicUnits: { type: 'string', pattern: '^[1-9][0-9]{0,38}$' },\n  usd: { ...usd, maxLength: 64 },\n  basis: { type: 'string', minLength: 4, maxLength: 300 }\n}) };\n\nconst repriceInput = { ...base, version: uuid, sellerSha256: digest, edits, quoteValuations };\n\nconst saveInput = { requestId: uuid, expectedRevision: revision, label: { type: 'string', minLength: 1, maxLength: 100 } };\n\nconst page = { offset: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1, maximum: 200 } };\n\nconst fileSelection = { ...base, kind: { type: 'string', enum: ['review', 'decision', 'scenario'] }, id: uuid };\n\nconst read = { readOnly: true, idempotent: true };\n\nconst sourceViews = ['routes', 'reviews', 'decisions', 'days', 'sessions', 'observations'];\n\nconst reportViews = ['routes', 'issues', 'historyDays', 'historySessions', 'historyRoutes', 'periodDays', 'periodVariants'];\n\nconst scenarioId = { type: 'string', pattern: '^(?!baseline$)[A-Za-z0-9][A-Za-z0-9_-]{0,63}$' };\n\nconst scenarioChoice = { type: 'string', pattern: '^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$' };\n\nconst scenarioGoal = object({ monthlyContributionUsd: usd,\n  marginPct: { type: 'string', pattern: '^(0|[1-9][0-9]?)(\\\\.[0-9]{1,4})?$' } }, []);\n\nconst scenario = object({ id: scenarioId, label: { type: 'string', minLength: 1, maxLength: 120 },\n  sharedMonthlyFixedUsd: optionalUsd,\n  routes: { type: 'object', properties: {}, additionalProperties: object({\n    unitPriceUsd: usd, priceBasis: { type: 'string', minLength: 4, maxLength: 300 },\n    perFulfilledUsd: optionalUsd, perChallengeUsd: optionalUsd,\n    monthlyPaidTarget: { type: 'integer', minimum: 0, maximum: Number.MAX_SAFE_INTEGER } }, []) },\n  goal: scenarioGoal }, ['id','label']);\n\nconst scenarioInput = { ...base, version: uuid, scenarios: { type: 'array', maxItems: 12, items: scenario } };\n\nconst scenarioViews = ['scenarios','routes','goals','suggestionRoutes'];\n\nconst suggestionKind = { type: 'string', enum: ['BREAK_EVEN_PRICE','BREAK_EVEN_VOLUME','TARGET_PRICE','TARGET_VOLUME'] };\n\nconst scenarioPage = { view: { type: 'string', enum: scenarioViews }, scenarioId: scenarioChoice, suggestionKind, ...page };\n\nconst definitions = [\n  ...costToolDefinitions,\n  ...tariffToolDefinitions,\n  ...performanceToolDefinitions,\n  ['merchant_pricing_status', 'List host-declared pricing workspaces and their process-local capture/file-read state. Does not capture operations or open a workspace.', { ...base }, [], read],\n  ['merchant_pricing_open', 'Open the original SF97 workspace model and capture its configured native operations source. Reopening the same alias reuses its original captures. Original per-save compare-and-swap remains shared with the browser.', base, ['workspace'], { idempotent: true }],\n  ['merchant_pricing_close', 'Release this MCP handle\\'s source view and temporary file reads. Original saved reviews, price decisions and staged releases remain in their original stores.', base, ['workspace'], { idempotent: true }],\n  ['merchant_pricing_source', 'Capture current seller terms and original session/history observations, or page the same capture with captureSha256. Route pages include every ordered payment option and its saved commercial inputs. Use the returned seller/snapshot hashes for preview and save.',\n    { ...base, selection, captureSha256: digest, view: { type: 'string', enum: sourceViews }, ...page }, ['workspace'], read],\n  ['merchant_pricing_preview', 'Evaluate merchant-entered USD prices, costs and targets against the original captured observations. Page original route economics, issues or retained history details. Atomic payment amounts remain the seller\\'s declared values.',\n    { ...priceInput, view: { type: 'string', enum: reportViews }, ...page }, Object.keys(priceInput), read],\n  ['merchant_pricing_save', 'Save the original pricing report and exact captured source bytes. Retain requestId and repeat identical inputs after an interrupted reply; expectedRevision uses the pricing review head. Original native reconciliation is included when the host attached its outbox.',\n    { ...priceInput, ...saveInput }, [...Object.keys(priceInput), ...Object.keys(saveInput)], { idempotent: true }],\n  ['merchant_pricing_load', 'Load the original commercial inputs from a saved pricing version against the current seller configuration. Capture current observations before previewing or saving another version.',\n    { ...base, version: uuid }, ['workspace', 'version'], read],\n  ['merchant_pricing_compare', 'Compare two exact retained pricing reports with original seller, commercial, observation-kind and period compatibility. Page the same report view on each side.',\n    { ...base, leftVersion: uuid, rightVersion: uuid, view: { type: 'string', enum: reportViews }, ...page }, ['workspace', 'leftVersion', 'rightVersion'], read],\n  ['merchant_pricing_planning_source', 'Read one immutable saved review as a commercial planning source. Page its selected routes, complete ordered payment choices and original commercial assumptions. Original source hashes and unknown costs stay attached.',\n    { ...base, version: uuid, ...page }, ['workspace','version'], read],\n  ['merchant_pricing_planning_preview', 'Compare up to twelve explicit volume, USD quote and cost scenarios using the original saved review and analyzer. Page scenarios, route economics, goals, or a selected suggestion\\'s complete route inputs. Suggested plans are applied only by an explicit subsequent operation.',\n    { ...scenarioInput, ...scenarioPage }, Object.keys(scenarioInput), read],\n  ['merchant_pricing_planning_save', 'Save the exact reviewed comparison in the original private scenario store. Preserve requestId, reviewSha256 and the complete inputs across retries. selectedScenarioId is optional and names one explicit scenario.',\n    { ...scenarioInput, requestId: uuid, label: { type: 'string', minLength: 1, maxLength: 100 },\n      reviewSha256: digest, selectedScenarioId: { anyOf: [scenarioId,{ type: 'null' }] } },\n    [...Object.keys(scenarioInput),'requestId','label','reviewSha256'], { idempotent: true }],\n  ['merchant_pricing_planning_list', 'List retained comparison summaries from the original workspace. The native listing retains its newest one hundred entries; every older plan remains loadable by its exact planId.',\n    { ...base, ...page }, ['workspace'], read],\n  ['merchant_pricing_planning_load', 'Reopen one exact saved comparison after restart. Page its scenarios, route inputs and goal suggestions; use kind:scenario with the original manifest/file tools for its complete JSON, CSV and terms.',\n    { ...base, planId: uuid, ...scenarioPage }, ['workspace','planId'], read],\n  ['merchant_pricing_planning_selection', 'Load one explicitly selected saved scenario as commercial draft inputs against the current seller. Capture current observations before saving that draft or using planning_apply.',\n    { ...base, planId: uuid, scenarioId, ...page }, ['workspace','planId','scenarioId'], read],\n  ['merchant_pricing_planning_apply', 'Apply an explicitly selected saved scenario by saving a new original pricing review. Supply the inspected plan review hash, current seller/snapshot hashes, pricing expectedRevision and stable requestId. Equal retries recover through the original pricing save.',\n    { ...base, planId: uuid, scenarioId, reviewSha256: digest, sellerSha256: digest, snapshotSha256: digest, ...saveInput },\n    ['workspace','planId','scenarioId','reviewSha256','sellerSha256','snapshotSha256',...Object.keys(saveInput)], { idempotent: true }],\n  ['merchant_pricing_repricing_source', 'Read every complete ordered payment option from the selected original saved pricing review, its seller hash, current price-decision revision and source-release availability.',\n    { ...base, version: uuid }, ['workspace', 'version'], read],\n  ['merchant_pricing_repricing_preview', 'Review either explicit atomic edits or quoteValuations against the selected saved seller. A quote valuation identifies the original option, expected amount, atomicUnits, positive USD value and basis. It derives the smallest sufficient atomic price from the saved USD quote. The original compiler validates both configurations; the complete conversion is included in reviewSha256.',\n    repriceInput, ['workspace','version','sellerSha256'], read],\n  ['merchant_pricing_repricing_save', 'Retain the exact reviewed price changes, original source seller/report/terms and updated seller configuration. A configured original API package is regenerated by its original compiler. Retain requestId, reviewSha256 and the price-decision expectedRevision across retries.',\n    { ...repriceInput, ...saveInput, reviewSha256: digest }, ['workspace','version','sellerSha256', ...Object.keys(saveInput), 'reviewSha256'], { idempotent: true }],\n  ['merchant_pricing_repricing_stage', 'Stage this retained original API price decision through its configured SF82 release store. Use the saved decision and exact reviewSha256. The same stable release ID recovers an interrupted reply; inspect and activate it with the original merchant release controls.',\n    { ...base, decision: uuid, reviewSha256: digest }, ['workspace', 'decision', 'reviewSha256'], { idempotent: true }],\n  ['merchant_pricing_manifest', 'Read an original saved pricing-review, price-decision or scenario-plan manifest and its exact file hashes. kind:review uses a saved version ID; kind:decision uses a saved decision ID; kind:scenario uses a saved planId.',\n    fileSelection, ['workspace', 'kind', 'id'], read],\n  ['merchant_pricing_file', 'Read SHA-pinned chunks from a file named in the inspected original pricing manifest, including source-package files. Repeat all selectors with readId, expectedSha256 and nextOffset. Reopening a digest after expiry reads the same retained bytes.',\n    { ...fileSelection, file: { type: 'string', minLength: 1, maxLength: 4096 }, expectedManifestSha256: digest,\n      expectedSha256: digest, readId: uuid, offset: { type: 'integer', minimum: 0 },\n      limit: { type: 'integer', minimum: 1, maximum: MAX_RETAINED_CHUNK_BYTES } },\n    ['workspace', 'kind', 'id', 'file', 'expectedManifestSha256'], read],\n  ['merchant_pricing_file_release', 'Release this pricing workspace\\'s temporary immutable file snapshot.',\n    { ...base, readId: uuid }, ['workspace', 'readId'], read],\n];\n\nconst pricingTools = tool => definitions.map(parts => tool(...parts));\n\nexport { pricingTools, definitions, base, read, selection, digest, sourceViews, page, priceInput, reportViews, saveInput, uuid, scenarioInput, scenarioPage, scenarioId, repriceInput, fileSelection, alias, object, nullableText, commercial, revision, scenario, scenarioViews, scenarioChoice, suggestionKind, edits, optionalUsd, usd, scenarioGoal };\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/service-adjustments.mjs",
      "gitBlob": "63a7c07463a5040d3867509677b0db9dd6e83ebf",
      "bytes": 6612,
      "sha256": "6078c8c7cb2ff9bd849825240c8be1ab2ee8d7d763c09c8c63833ca5c94637c2",
      "content": "// MIT. Complete original saved-case adjustment and buyer handoff contract.\nimport {MAX_RETAINED_CHUNK_BYTES} from '../retained-file-contracts.mjs';\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};\nconst sha={type:'string',pattern:'^[a-f0-9]{64}$'},alias={type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'};\nconst text=maxLength=>({type:'string',maxLength}),int={type:'integer',minimum:0},document={type:'object',additionalProperties:true};\nconst page={offset:int,limit:{type:'integer',minimum:1,maximum:100}},selected={id:uuid,expectedRevision:sha};\nconst read={readOnly:true,idempotent:true},write={idempotent:true};\nconst material={...selected,expectedImplementationRevision:int,requestId:uuid,material:document};\nconst file={id:uuid,revision:sha,readId:uuid,offset:int,limit:{type:'integer',minimum:1,maximum:MAX_RETAINED_CHUNK_BYTES},expectedSha256:sha};\nexport function serviceAdjustmentTools(tool){\n  return [\n    tool('merchant_service_adjustment_read','Read saved Service reports, reviewed proposals, retained native intents and original outcomes. Select recordId for the complete original record; otherwise use summary pages.',{id:uuid,revision:sha,section:{enum:['overview','reports','proposals','intents','outcomes']},recordId:uuid,...page},['id'],read),\n    tool('merchant_service_adjustment_sources','List the original host-configured accounting workspace aliases for Service adjustments.',{},[],read),\n    tool('merchant_service_adjustment_accounting','Open or close the same accounting owner, read its current state, page retained reconciliations/payments, or inspect the selected original payment.',{action:{enum:['open','close','status','runs','events','event']},accountingId:alias,runId:uuid,eventId:sha,search:text(500),...page},['action','accountingId'],write),\n    tool('merchant_service_adjustment_preview','Prepare a complete reviewed proposal from an immutable Service report, selected incidents, explicit monetary basis and the original native payment preview. Retain the returned proposal without rewriting its body.',{...selected,input:document},['id','expectedRevision','input'],read),\n    tool('merchant_service_adjustment_prepare','Prepare record, returned-transfer verification or exact buyer capture against a saved proposal and the same admitted native controller. Save the returned intent before execution.',{...selected,input:document},['id','expectedRevision','input'],read),\n    tool('merchant_service_adjustment_retain','Save the complete reviewed proposal or prepared native intent as an original commissioning material. Preserve the requestId, case revision, implementation revision and full material across an interrupted reply.',material,Object.keys(material),write),\n    tool('merchant_service_adjustment_execute','Execute one saved native intent through its original accounting owner and append its retained outcome to the current case. Retry uncertain responses with the same requestId; a later observation of the original verification uses a new requestId and the same intent.',{id:uuid,intentId:uuid,requestId:uuid},['id','intentId','requestId'],{...write,openWorld:true}),\n    tool('merchant_service_adjustment_file','Read the complete original adjustment handover, customer document, saved case/workspace or captured native accounting/buyer file using a retained hash-pinned file reader.',{...file,proposalId:uuid,proposalSha256:sha,outcomeId:uuid,kind:{enum:['handover','customer-html','service-report','case','workspace','native-json','native-csv','native-html','buyer-source']}},['id','revision','proposalId','proposalSha256','kind'],read),\n    tool('merchant_service_buyer_read','Read original captured Service sources, prepared buyer/accountant intents and retained outcomes from the same case. Summary pages omit file bodies; select a recordId for its complete record.',{id:uuid,revision:sha,section:{enum:['overview','captures','intents','outcomes']},recordId:uuid,...page},['id'],read),\n    tool('merchant_service_buyer_sources','List original host-declared buyer expense workspace aliases and their existing input sources.',{},[],read),\n    tool('merchant_service_buyer_workspace','Explicitly open the original buyer owner, read its state, or close its exact owned instance.',{action:{enum:['open','status','close']},buyerWorkspace:alias,instanceId:text(160),view:{enum:['summary','sources','centers','periods','labels']},...page},['action','buyerWorkspace'],write),\n    tool('merchant_service_buyer_inspect','Inspect the original buyer workspace, received adjustment packets, purchase/credit coding basis and period report for an exact captured Service outcome.',{id:uuid,revision:sha,input:document},['id','input'],read),\n    tool('merchant_service_buyer_accountant_preview','Preview a complete original bookkeeping return against its issued buyer source and current retained handoffs. Retain the returned preview hash and explicitly selected superseded return IDs when preparing its saved acceptance intent.',{id:uuid,revision:sha,input:document},['id','input'],read),\n    tool('merchant_service_buyer_prepare','Prepare an original buyer receive/review/coding/period action, complete issued delivery or accountant handoff. The returned intent binds the Service capture, original workspace identities and exact native request. Retain it before execution.',{...selected,input:document},['id','expectedRevision','input'],read),\n    tool('merchant_service_buyer_retain','Save the complete prepared buyer/accountant intent into the original commissioning journal. Keep its original request and revision after an uncertain reply.',material,Object.keys(material),write),\n    tool('merchant_service_buyer_execute','Execute the saved exact buyer/accountant intent. Recover the original native request before any retry and append its result while preserving other case work.',{id:uuid,intentId:uuid,requestId:uuid},['id','intentId','requestId'],write),\n    tool('merchant_service_buyer_file','Read a complete retained buyer/accountant delivery file selected by the original case revision, outcome and filename.',{...file,outcomeId:uuid,name:text(240)},['id','revision','outcomeId','name'],read),\n    tool('merchant_service_adjustment_file_reads','Read this connection’s retained original Service/buyer file snapshots for the selected case.',{id:uuid},['id'],read),\n    tool('merchant_service_adjustment_file_release','Release this connection’s temporary file snapshot after complete receiving. The saved case and its original delivery remain.',{id:uuid,readId:uuid},['id','readId'],write)\n  ];\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/service.mjs",
      "gitBlob": "5deebcb9ea14f7b38e718896348c6f7b3ff327d7",
      "bytes": 4913,
      "sha256": "52a08a8f0e58871465434f79d79321e0e6f93ff8e614a677103e4b9495760ae4",
      "content": "// MIT. Complete service case operator contract; original SF74/SF93 modules execute.\nconst uuid={type:'string',pattern:'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'};\nconst digest={type:'string',pattern:'^[a-f0-9]{64}$'};\nconst alias={type:'string',pattern:'^[A-Za-z0-9_-]{1,64}$'};\nconst text=maxLength=>({type:'string',maxLength});\nconst integer=(minimum=0,maximum=Number.MAX_SAFE_INTEGER)=>({type:'integer',minimum,maximum});\nconst object=(properties,required=Object.keys(properties))=>({type:'object',properties,required,additionalProperties:false});\nconst nullable=value=>({anyOf:[value,{type:'null'}]});\nconst utc={type:'string',pattern:'^\\\\d{4}-\\\\d\\\\d-\\\\d\\\\dT\\\\d\\\\d:\\\\d\\\\d:\\\\d\\\\d\\\\.\\\\d{3}Z$'};\nconst date={type:'string',pattern:'^\\\\d{4}-\\\\d\\\\d-\\\\d\\\\d$'};\nconst windows={type:'array',maxItems:12,items:object({start:text(5),end:text(5)})};\nconst calendar=object({mode:{enum:['always','business']},timeZone:text(100),\n  week:{type:'array',maxItems:7,items:object({day:integer(1,7),windows})},\n  exceptions:{type:'array',maxItems:1000,items:object({date,windows})}});\nconst kinds=['ENDPOINT_UNAVAILABLE','OBSERVER_INCOMPLETE','HTTP_5XX','DISCONNECTED','DELIVERY_UNAVAILABLE','DELIVERY_BACKLOG','DELIVERY_EXHAUSTED'];\nconst terms=object({id:uuid,expectedRevision:nullable(integer(1)),title:text(500),customer:text(500),owner:text(240),reference:text(4000),\n  status:{enum:['proposed','active','ended']},incidentSourceId:alias,merchantId:alias,merchantBinding:digest,\n  effectiveFrom:utc,effectiveUntil:nullable(utc),calendar,\n  targets:{type:'array',minItems:1,maxItems:7,items:object({kind:{enum:kinds},responseMinutes:integer(1,527040),recoveryMinutes:integer(1,527040)})},\n  reviewedBy:text(240),note:text(8000)});\nconst capture=object({incidentSource:{type:'string',pattern:'^[a-z0-9][a-z0-9_-]{0,63}$'},merchantId:alias,\n  expectedSourceRevision:integer(1),expectedConfigHash:digest,expectedMerchantBinding:digest},\n  ['merchantId','expectedSourceRevision','expectedConfigHash','expectedMerchantBinding']);\nconst exclusion=object({id:uuid,incidentId:uuid,captureSha256:digest,from:utc,through:utc,\n  scope:{enum:['response','recovery','both']},reason:text(4000),reference:text(4000),reviewedBy:text(240)});\nconst selection=object({termsId:uuid,termsRevision:integer(1),from:date,through:date,asOf:utc,\n  captureSha256s:{type:'array',minItems:1,maxItems:1000,items:digest},\n  exclusionIds:{type:'array',maxItems:1000,items:uuid}});\nconst report=object({...selection.properties,expectedPreviewSha256:digest,reviewedBy:text(240),note:text(8000)});\nexport function serviceTools(tool){\n  const read={readOnly:true,idempotent:true};\n  return [\n    tool('merchant_support_service_snapshot','Read one complete original merchant incident history in its configured SF93 store transaction. Includes current or retired registration, source/config revisions and exact merchant binding for the next capture. Starts no watcher.',\n      {incidentSource:capture.properties.incidentSource,merchantId:alias},['merchantId'],read),\n    tool('merchant_service_read','Read the original saved case service summary or page through terms, captures, exclusions, reports and operator changes. recordId returns the complete selected original record; use its SHA to select one terms edition. Complete case exports preserve every source and unfinished form.',\n      {id:uuid,revision:digest,section:{enum:['summary','terms','captures','exclusions','reports','operations']},\n        recordId:text(64),offset:integer(),limit:integer(1,100)},['id'],read),\n    tool('merchant_service_change','Save a reviewed service change through the original case writer. action selects terms, capture, exclusion or report and the matching input object. Capture guards the inspected source/config/merchant binding. Retain the same requestId, expectedRevision and input after a lost response; exact replay returns the original result even after later case changes.',\n      {id:uuid,expectedRevision:digest,requestId:uuid,action:{enum:['terms','capture','exclusion','report']},\n        input:{anyOf:[terms,capture,exclusion,report]}},\n      ['id','expectedRevision','requestId','action','input'],{idempotent:true}),\n    tool('merchant_service_preview','Calculate a complete service report from an exact current case, terms history, selected original incident captures, named calendar and explicitly reviewed exclusions. Its previewSha256 binds the subsequent retained report.',\n      {id:uuid,expectedRevision:digest,selection},['id','expectedRevision','selection'],read),\n    tool('merchant_service_report','Render one retained original service report as complete JSON, incident CSV or printable HTML. Returns exact UTF-8 bytes/hash and filename; original reports and all selected sources stay in the case export.',\n      {id:uuid,revision:digest,reportId:uuid,format:{enum:['json','csv','html']}},['id','reportId'],read)\n  ];\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/catalog/support.mjs",
      "gitBlob": "0e31d97e2d6606dcee61b672bfb42627dd300a33",
      "bytes": 15147,
      "sha256": "36f658e6ca8e604b93feaff4c59da1a0318f628ab8d0b5dd145a37fedfaf4e55",
      "content": "import {commercialTools} from './commercial.mjs';\nimport {serviceAdjustmentTools} from './service-adjustments.mjs';\nimport {casePackageTools} from './case-packages.mjs';\n// MIT. Original tool metadata; provider runtimes load only when selected.\nimport { CASE_STATUSES } from '../../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-statuses.mjs';\nimport { MAX_RETAINED_CHUNK_BYTES } from '../retained-file-contracts.mjs';\nimport {serviceTools} from './service.mjs';\n\nconst uuid = { type: 'string', pattern: '^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' };\n\nconst digest = { type: 'string', pattern: '^[a-f0-9]{64}$' };\n\nconst alias = { type: 'string', pattern: '^[a-z0-9][a-z0-9_-]{0,63}$' };\n\nconst text = maximum => ({ type: 'string', maxLength: maximum });\n\nconst object = properties => ({ type: 'object', properties, additionalProperties: false });\n\nconst metadataSchema = object({ merchant: text(480), owner: text(480), status: { enum: CASE_STATUSES },\n  followUpOn: text(10), nextAction: text(2400), notes: text(16000) });\n\nconst termsSchema = { ...object({ workOrderRef: text(120), sellerDisplayName: text(200), relationshipOwner: text(200),\n  proposedWindow: text(8192), delivery: object({ scope: text(8192), deliverables: text(8192), acceptanceCriteria: text(8192) }),\n  merchantConsent: { ...object({ status: { enum: ['NOT_RECORDED', 'CONFIRMED'] }, receiptUrl: { type: ['string', 'null'], maxLength: 8192 } }), required: ['status'] },\n  commercial: { ...object({ priceApproval: { enum: ['NOT_APPROVED', 'OWNER_APPROVED_PROPOSAL'] }, feeUsd: { type: ['number', 'null'] },\n    costUsd: { type: ['number', 'null'] }, approvalReceiptUrl: { type: ['string', 'null'], maxLength: 8192 } }), required: ['priceApproval'] } }),\n  required: ['merchantConsent', 'commercial'] };\n\nconst selected = { id: uuid, expectedRevision: digest };\n\nconst page = { offset: { type: 'integer', minimum: 0 }, limit: { type: 'integer', minimum: 1, maximum: 100 } };\n\nconst notificationStatuses = ['PENDING', 'RETRY', 'IN_FLIGHT', 'PAUSED', 'EXHAUSTED', 'DELIVERED', 'CANCELLED'];\nconst incidentSource = { ...alias, description: 'Original host-declared incident source ID. Required when multiple sources have no host default.' };\nconst sourceTools = new Set(['merchant_support_profiles', 'merchant_support_configure', 'merchant_support_watch_status',\n  'merchant_support_watch_start', 'merchant_support_watch_stop', 'merchant_notifications', 'merchant_incident_notify',\n  'merchant_notification_update', 'merchant_incidents', 'merchant_incident_ack', 'merchant_incident_case']);\n\nfunction supportTools(tool) {\n  const read = { readOnly: true, idempotent: true };\n  return [\n    ...serviceTools(tool),\n    ...serviceAdjustmentTools(tool),\n    ...casePackageTools(tool),\n    ...commercialTools(tool),\n    tool('merchant_support_incident_sources', 'Inspect the original support connection mode, configured incident source IDs/labels, bound source-file digest and host default. Reads no arbitrary path and starts no watcher.', {}, [], read),\n    tool('merchant_support_destination', 'Inspect the currently selected source notification configuration at its exact revision. Slack resolves the original host token and reads the actual authenticated workspace/channel; webhook reports configuration resolution. Sends no notification.',\n      { incidentSource, expectedConfigRevision: { type: 'integer', minimum: 1 } }, ['expectedConfigRevision'], { ...read, openWorld: true }),\n    tool('merchant_incident_view', 'Open one retained original incident with its current revision, last notification ID, sanitized events and actual advertised routes from before/after capture files. Returns capture issues without replacing the original files or observing a seller.',\n      { incidentSource, id: uuid }, ['id'], read),\n    tool('merchant_support_profiles', 'List host-declared SF93 registration profiles, or inspect one original compiled configuration, its file digest, current configuration revision and actual changes. Notification values remain environment references.',\n      { profile: alias }, [], read),\n    tool('merchant_support_configure', 'Apply an inspected host profile through the original SF93 configuration transaction. Requires its exact source digest and current configuration revision. After a lost reply, inspect the current configuration before another change.',\n      { profile: alias, expectedSourceSha256: digest, expectedConfigRevision: { type: 'integer', minimum: 1 } }, ['profile', 'expectedSourceSha256', 'expectedConfigRevision']),\n    tool('merchant_support_watch_status', 'Read the original watcher record and this MCP operator\\'s actual ownership. A saved RUNNING record alone does not establish a live worker or ownership by this operator.', {}, [], read),\n    tool('merchant_support_watch_start', 'Start the ORIGINAL SF93 watcher for the exact inspected configuration. It acquires the existing kernel lease, polls configured local merchant endpoints and sends the existing configured incident notifications. Does not start a seller or delivery worker.',\n      { expectedConfigRevision: { type: 'integer', minimum: 1 }, expectedConfigHash: digest }, ['expectedConfigRevision', 'expectedConfigHash']),\n    tool('merchant_support_watch_stop', 'Stop only the original watcher started by this MCP process, using its exact instance ID. Waits for its original final state write and lease release. An identical completed stop can be reopened.',\n      { instanceId: uuid }, ['instanceId'], { idempotent: true }),\n    tool('merchant_notifications', 'Page through original incident notification records without message bodies, destination URLs or signing keys. Includes actual attempt counts, state and retry reason for recovery.',\n      { id: uuid, incidentId: uuid, status: { enum: notificationStatuses }, ...page }, [], read),\n    tool('merchant_incident_notify', 'Queue a NEW original reminder for the exact incident revision and current destination. Pass the latest expectedNotificationId from merchant_incident_view, or null when none exists, to atomically reject duplicate reminders after a lost response. Source-file mode requires that guard; legacy single-store callers may omit it.',\n      { id: uuid, expectedRevision: { type: 'integer', minimum: 1 }, expectedNotificationId: { anyOf: [uuid, { type: 'null' }] } }, ['id', 'expectedRevision']),\n    tool('merchant_notification_update', 'Retry an original paused/exhausted notification or cancel an unfinished one, using its exact attempt count and named operator. Existing destination, in-flight and completed-event checks remain authoritative.',\n      { id: uuid, expectedAttempts: { type: 'integer', minimum: 0 }, action: { enum: ['retry', 'cancel'] }, by: text(160) }, ['id', 'expectedAttempts', 'action', 'by']),\n    tool('merchant_support_sources', 'List host-configured original handoffs/workspace templates, or inspect one with its exact file digest, saved mapping and retained runtime findings. Reads no arbitrary path and starts no observation.',\n      { kind: { enum: ['handoff', 'workspace'] }, source: alias }, [], read),\n    tool('merchant_incidents', 'Read the original SF93 incident store. Returns actual condition, revision, capture and notification state; does not poll a seller or send a notification.',\n      { id: uuid, status: { enum: ['OPEN', 'ACKNOWLEDGED', 'RECOVERED', 'RETIRED'] }, ...page }, [], read),\n    tool('merchant_incident_ack', 'Acknowledge an original OPEN incident with its exact revision and named operator. The existing watcher may deliver its configured acknowledgment notification. Recovery remains based on original observations.',\n      { id: uuid, expectedRevision: { type: 'integer', minimum: 1 }, by: text(160), notes: text(2000) }, ['id', 'expectedRevision', 'by']),\n    tool('merchant_incident_case', 'Save one exact original incident using its host-configured SF74 workspace template and retained route. Supply a new case UUID. An identical retry reuses the initial case version while the incident selection is current. After an interrupted reply, read that original case ID and history first, especially if the incident or saved case has advanced.',\n      { id: uuid, incidentId: uuid, expectedIncidentRevision: { type: 'integer', minimum: 1 }, template: alias,\n        expectedTemplateSha256: digest, routeId: text(160) }, ['id', 'incidentId', 'expectedIncidentRevision', 'template', 'expectedTemplateSha256', 'routeId']),\n    tool('merchant_cases', 'Search original saved cases by text, work status or follow-up date, with their actual current revisions.',\n      { q: text(1000), status: { enum: CASE_STATUSES }, dueOn: text(10), ...page }, [], read),\n    tool('merchant_case_read', 'Reopen the current or a retained case revision, including original support review, exact source hashes and unfinished owner terms. Original source payloads stay in the private case store.',\n      { id: uuid, revision: digest }, ['id'], read),\n    tool('merchant_case_history', 'Page through original immutable case revisions; before is the nextBefore digest returned by a prior page.',\n      { id: uuid, before: digest, limit: { type: 'integer', minimum: 1, maximum: 100 } }, ['id'], read),\n    tool('merchant_case_import', 'Import an exact host-configured complete SF74 handoff as a new case, preserving all original source bytes, metadata and raw owner terms. Inspect its alias first; supply a new UUID and exact file digest.',\n      { id: uuid, source: alias, expectedSourceSha256: digest }, ['id', 'source', 'expectedSourceSha256']),\n    tool('merchant_case_update', 'Save owner-entered metadata or terms and workorder source choice as a new original case version. Uses the exact current revision; omitted fields and original captures are preserved. Recording a proposal does not send or accept it.',\n      { ...selected, metadata: metadataSchema, terms: termsSchema, workorderSource: { enum: ['diagnostic', 'runtime'] }, baselineOnly: { type: 'boolean' } }, ['id', 'expectedRevision']),\n    tool('merchant_case_restore', 'Restore a retained case revision as a new current version through the original writer. Preserves later versions in history and requires the current expected revision.',\n      { ...selected, revision: digest }, ['id', 'expectedRevision', 'revision']),\n    tool('merchant_case_workorder', 'Prepare the original SF77 workorder from an exact saved case revision, its selected original sources and recorded owner terms. Returns the original packet without seller, payment or contact calls.', selected, ['id', 'expectedRevision'], read),\n    tool('merchant_case_implementation', 'Read the saved merchant implementation, assigned work, original workorders, deliverables, technical/customer receiving and comparable measurements. Use the returned nextOffset to read a full selected section.',\n      { id: uuid, revision: digest, section: {enum:['overview','tasks','materials','receiving','measurements','events','editions','files','comparisons']},\n        offset:{type:'integer',minimum:0},limit:{type:'integer',minimum:1,maximum:200} }, ['id'], read),\n    tool('merchant_case_implementation_prepare', 'Use the original saved case and SF77 builder to create or update its implementation work. Retain one requestId for lost-response recovery; exact replay reopens the original edition. New source fields preserve operator edits for selective adoption.',\n      { ...selected,expectedImplementationRevision:{type:'integer',minimum:0},requestId:text(160),actor:text(200),recordedAt:text(40) },\n      ['id','expectedRevision','expectedImplementationRevision','requestId','actor']),\n    tool('merchant_case_implementation_apply', 'Apply assigned work, original deliverables, source-field choices, receiving/corrections or effort measurements through the original case writer. Supply the exact case and implementation revisions and retain the original requestId and payload for replay.',\n      { ...selected,command:{...object({type:{enum:['record_workorder','select_workorder','update_plan','save_tasks','accept_source_changes','add_material','record_receiving','record_measurement']},\n        requestId:text(160),expectedRevision:{type:'integer',minimum:0},actor:text(200),recordedAt:text(40),payload:{type:'object'}}),\n        required:['type','requestId','expectedRevision','actor','payload']} }, ['id','expectedRevision','command']),\n    tool('merchant_case_export', 'Publish or resume a private named export of the exact saved case, complete original support handoff, implementation and service reports. includeWorkorder adds the original SF77 packet, HTML and checklist. Repeating the same original request completes its retained export or returns its verified completion, including after later case edits.',\n      { ...selected, exportId: alias, includeWorkorder: { type: 'boolean' } }, ['id', 'expectedRevision', 'exportId']),\n    tool('merchant_support_export_status', 'Inspect a named support export and verify the retained original files against its completion manifest. Reconcile an interrupted export before choosing a new ID.',\n      { exportId: alias }, ['exportId'], read),\n    tool('merchant_support_export_manifest', 'Read the original completion manifest and its exact file digest without rereading every exported payload. MANIFEST_RETAINED identifies the saved manifest; individual file retrieval verifies the original bytes. Includes this operator\\'s active file reads.',\n      { exportId: alias }, ['exportId'], read),\n    tool('merchant_support_export_file', 'Retrieve a named original support export file in bounded base64 chunks. Pin the completion manifest and repeat the returned readId/expectedSha256 for continuation. After restart or expiry, omit readId and resume at the saved offset with the same digests. Does not regenerate an export.',\n      { exportId: alias, file: { enum: [...exportNames, 'support-export.json'] }, expectedManifestSha256: digest,\n        readId: uuid, expectedSha256: digest, offset: { type: 'integer', minimum: 0 },\n        limit: { type: 'integer', minimum: 1, maximum: MAX_RETAINED_CHUNK_BYTES } },\n      ['exportId', 'file', 'expectedManifestSha256'], read),\n    tool('merchant_support_export_file_release', 'Release this operator\\'s unfinished verified support-file read. Its original export and case remain retained.',\n      { exportId: alias, readId: uuid }, ['exportId', 'readId'], { idempotent: true }),\n  ].map(value => sourceTools.has(value.name) ? { ...value, inputSchema: {\n    ...value.inputSchema, properties: { ...value.inputSchema.properties, incidentSource }\n  } } : value);\n}\n\nconst exportNames = ['case.json', 'merchant-workspace.json', 'merchant-support.json', 'support.html',\n  'owner-terms.json', 'packet.json', 'seller-packet.html', 'acceptance-checklist.md',\n  'merchant-commissioning.json','merchant-implementation.html','merchant-implementation-tasks.csv',\n  'merchant-service.json','merchant-service-report.json','merchant-service-report.csv','merchant-service-report.html'];\n\nexport { supportTools, alias, digest, uuid, notificationStatuses, page, text, selected, metadataSchema, termsSchema, exportNames, object };\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/host-files.mjs",
      "gitBlob": "a366cc4aa3e3ee3dfb7cb88320b84fcb00ab2fad",
      "bytes": 2195,
      "sha256": "19b96e241973e80bcfe907223f7b06cb6aa52214ccf37d52b1078ec109508055",
      "content": "// MIT. Original host file primitives shared by configuration and retained downloads.\nimport { lstat, open, readFile } from 'node:fs/promises';\n\nexport const failure = (code, message) => Object.assign(new Error(message), { code });\n\nexport function identifier(value, label = 'Identifier') {\n  if (typeof value !== 'string' || !/^[a-z0-9][a-z0-9_-]{0,63}$/.test(value))\n    throw failure('INVALID_PARAMS', label + ' must use 1–64 lowercase letters, digits, underscores or hyphens.');\n  return value;\n}\n\nexport async function privateSupportDirectory(path) {\n  const info = await lstat(path);\n  if (!info.isDirectory() || info.isSymbolicLink() || process.platform !== 'win32' && (info.mode & 0o077))\n    throw failure('CONFIGURATION_ERROR', 'Support storage and exports require an existing private directory (0700).');\n  return path;\n}\n\nexport async function writePrivate(path, value) {\n  const handle = await open(path, 'wx', 0o600);\n  try { await handle.writeFile(typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value, null, 2) + '\\n'); await handle.sync(); }\n  finally { await handle.close(); }\n}\n\nexport const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);\nexport function exact(value, keys, required = []) {\n  if (!plain(value) || Object.keys(value).some(key => !keys.includes(key)) || required.some(key => !Object.hasOwn(value, key)))\n    throw failure('INVALID_PARAMS', 'Supply only the declared fields, including every required field.');\n}\nexport function line(value, label = 'Text') {\n  if (typeof value !== 'string' || !value.trim() || value.length > 240 || /[\\x00-\\x1f\\x7f]/.test(value))\n    throw failure('INVALID_PARAMS', label + ' must be nonempty single-line text up to 240 characters.');\n  return value.trim();\n}\nexport async function fileBytes(path, maximum = 4 * 1024 * 1024) {\n  const info = await lstat(path);\n  if (!info.isFile() || info.size > maximum) throw failure('SOURCE_INVALID', 'Expected a regular source file within its size limit.');\n  const bytes = await readFile(path);\n  if (bytes.length > maximum) throw failure('SOURCE_INVALID', 'Source file grew beyond its size limit.');\n  return bytes;\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/PERFORMANCE.md",
      "gitBlob": "139d72503301b75c348d5788f344762ca485db51",
