IMIT)\n        throw this.#fail('READ_CAPACITY', 'Finish or release an existing file read before opening another.');\n      if (typeof load === 'function' && loadFile !== undefined || typeof loadFile === 'function' && load !== undefined ||\n          typeof load !== 'function' && typeof loadFile !== 'function')\n        throw this.#fail('INVALID_FILE', 'Select exactly one original Buffer loader or retained-file loader.');\n      if (loadFile && !expectedSha256)\n        throw this.#fail('INVALID_FILE', 'Retained-file acquisition requires its original expectedSha256.');\n      this.#readStats.set(scope, (this.#readStats.get(scope) ?? 0) + 1);\n      const original = await (loadFile ?? load)();\n      const native = !loadFile && original?.readonlyFileHandle !== undefined;\n      let size, sha, memory = null, handle = null, identity = null;\n      try {\n        // A returned immutable handle transfers before any later scope/metadata\n        // refusal, so every admitted-but-unpublished descriptor is still closed.\n        if (native) handle = this.#ownNativeHandle(original.readonlyFileHandle);\n        this.#assertOpening(scope);\n        if (loadFile) {\n          const copied = await this.#copyOriginalFile({ ...original, scope }, directory, expectedSha256);\n          size = copied.size; sha = copied.sha256; handle = copied.handle;\n        } else if (native) {\n          size = original.bytes; sha = original.sha256;\n          if (!Number.isSafeInteger(size) || size < 0 || size > this.#maxImmutableFileBytes ||\n              typeof sha !== 'string' || !SHA256.test(sha) || typeof original.name !== 'string' || !original.name)\n            throw this.#fail('FILE_SOURCE_INVALID', 'Use exact native file metadata with a SHA256 and a byte count within this source owner’s declared native file limit.');\n          if (expectedSha256 && sha !== expectedSha256)\n            throw this.#fail('FILE_CHANGED', 'The native file metadata differs from the requested SHA256.');\n          identity = await this.#verifyNative(handle, size, sha, scope);\n        } else {\n          if (!Buffer.isBuffer(original?.bytes) || typeof original?.name !== 'string')\n            throw this.#fail('INVALID_FILE', 'The original Buffer loader must return bytes and a download name.');\n          const bytes = original.bytes;\n          this.#capacity(bytes.length); size = bytes.length; sha = digest(bytes);\n          if (expectedSha256 && sha !== expectedSha256)\n            throw this.#fail('FILE_CHANGED', 'The original file differs from the requested SHA256.');\n          if (bytes.length <= MEMORY_SNAPSHOT_LIMIT) memory = Buffer.from(bytes);\n          else { handle = await this.#snapshotHandle(directory, scope); await handle.writeFile(bytes); }\n        }\n        this.#assertOpening(scope);\n        const read = { id: randomUUID(), key, scope, kind, size, native, identity, tail: Promise.resolve(),\n          closed: false, memory, handle,\n          metadata: { name: original.name, contentType: original.type ?? (original.name.endsWith('.json') ? 'application/json'\n            : original.name.endsWith('.tar') ? 'application/x-tar' : 'application/octet-stream'), bytes: size, sha256: sha } };\n        this.#reads.set(read.id, read); handle = null; this.#touch(read); return read;\n      } catch (error) {\n        if (native && handle && !String(error.code ?? '').startsWith(this.#prefix + '_'))\n          throw this.#fail('SNAPSHOT_UNAVAILABLE', 'The original native descriptor could not be verified. Reopen its original artifact.');\n        throw error;\n      } finally {\n        await this.#closeFile(handle, scope).catch(() => {});\n      }\n    });\n    let opening = this.#opening.get(scope);\n    if (!opening) { opening = new Set(); this.#opening.set(scope, opening); }\n    opening.add(pending);\n    const remove = () => { opening.delete(pending); if (!opening.size) this.#opening.delete(scope); };\n    this.#readTail = pending.then(remove, remove);\n    return pending;\n  }\n  async read(options) {\n    const { scope, key, readId, expectedSha256, offset = 0, limit = 65536 } = options;\n    this.#assertOpening(scope);\n    if (!Number.isSafeInteger(offset) || offset < 0 || !Number.isSafeInteger(limit) || limit < 1 || limit > MAX_RETAINED_CHUNK_BYTES ||\n        expectedSha256 !== undefined && !SHA256.test(expectedSha256))\n      throw this.#fail('INVALID_CHUNK', 'Use a nonnegative byte offset, a bounded chunk and an exact SHA256.');\n    if ((offset > 0 || readId) && !expectedSha256)\n      throw this.#fail('INVALID_CHUNK', 'Repeat expectedSha256 when continuing a read or resuming at a later offset.');\n    const read = readId ? this.#reads.get(readId) : await this.#open(options);\n    if (!read || read.closed || read.releasing)\n      throw this.#fail('READ_NOT_FOUND', 'This file read completed, expired or was released. Open a new original read using the same expectedSha256 to resume.');\n    if (read.scope !== scope || read.key !== key) throw this.#fail('READ_CONFLICT', 'Use this readId only for its original scope and file selection.');\n    if (expectedSha256 && expectedSha256 !== read.metadata.sha256) throw this.#fail('FILE_CHANGED', 'The read snapshot differs from the requested SHA256.');\n    if (offset > read.size) { if (!readId) await this.release(scope, read.id); throw this.#fail('INVALID_CHUNK', 'Use an offset within the verified original file.'); }\n    const pending = read.tail.then(async () => {\n      if (read.closed) throw this.#fail('READ_NOT_FOUND', 'This original file read has completed or been released.');\n      this.#touch(read);\n      try {\n        const identity = read.native ? await this.#beforeNativeChunk(read) : null;\n        const length = Math.min(limit, read.size - offset), chunk = read.memory ? read.memory.subarray(offset, offset + length) : Buffer.alloc(length);\n        if (read.handle) {\n          let position = 0;\n          while (position < length) {\n            const result = await read.handle.read(chunk, position, length - position, offset + position);\n            if (!result.bytesRead) throw this.#fail('SNAPSHOT_UNAVAILABLE', 'The private verified read snapshot is unavailable.');\n            position += result.bytesRead;\n          }\n        }\n        if (read.native && !sameIdentity(identity, await this.#nativeIdentity(read.handle)))\n          throw this.#fail('FILE_CHANGED', 'The native file changed while this chunk was read. No bytes from that chunk were accepted.');\n        const next = offset + length, result = { readId: read.id, file: read.metadata, offset, bytesRead: length,\n          nextOffset: next < read.size ? next : null, encoding: 'base64', data: chunk.toString('base64') };\n        if (next === read.size) await this.#dispose(read);\n        return result;\n      } catch (error) {\n        if (read.native) {\n          await this.#dispose(read).catch(() => {});\n          if (!String(error.code ?? '').startsWith(this.#prefix + '_'))\n            throw this.#fail('SNAPSHOT_UNAVAILABLE', 'The original native descriptor is unavailable. Reopen its original artifact.');\n        }\n        throw error;\n      }\n    });\n    read.tail = pending.then(() => {}, () => {});\n    return pending;\n  }\n  close() {\n    if (!this.#close) {\n      this.#closing = true;\n      this.#close = (async () => {\n        await this.#readTail;\n        await this.#drainCloses();\n      })().catch(error => { this.#close = null; throw error; });\n    }\n    return this.#close;\n  }\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/support-commercial-receiving.mjs",
      "gitBlob": "19816490ff97531d7652910ddac9faa0985f3fd1",
      "bytes": 1425,
      "sha256": "140632178feaeffed2d73feb085d62a28c255a513e320c642fd6522f43da701e",
      "content": "// MIT. The original commercial receiving controller under the configured Support owner.\nimport {openCommercialReceivingController} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/operator.mjs';\nimport {failure} from './host-files.mjs';\nconst ACTIONS={\n  merchant_case_commercial_receiving_status:'status',\n  merchant_case_commercial_receiving_capture:'capture',\n  merchant_case_commercial_receiving_inspect:'inspect',\n  merchant_case_commercial_receiving_attach:'attach',\n  merchant_case_commercial_receiving_case:'inspect-case',\n  merchant_case_commercial_receiving_restore:'restore',\n};\nexport function merchantCommercialReceiving({cases,casesDirectory,environment=process.env}={}){\n  let opening,closing=false,closed;\n  const original=()=>opening??=Promise.resolve(cases()).then(store=>openCommercialReceivingController({\n    store,casesDirectory:casesDirectory(),environment}));\n  return {\n    handles:name=>Object.hasOwn(ACTIONS,name),\n    async call(name,args){\n      if(closing)throw failure('SUPPORT_CLOSING','The original Support owner is draining its active operations.');\n      if(!Object.hasOwn(ACTIONS,name))throw failure('TOOL_NOT_FOUND','Unknown original quotation receiving operation.');\n      return (await original()).call(ACTIONS[name],args);\n    },\n    close(){\n      return closed??=(async()=>{closing=true;if(opening)await(await opening).close();})();\n    },\n  };\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/support-commercial-tariffs.mjs",
      "gitBlob": "47c3654e4971b8c5a7157af61c9ff48e8f0e1ac3",
      "bytes": 2571,
      "sha256": "c47ca227996ed01584a3fa217f6b3141b92eed5a2452c385889f3f7e888a5742",
      "content": "// MIT. Full tariff quotation receiving under the original configured Support owner.\nimport {openCommercialTariffController} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-controller.mjs';\nimport {failure,exact,privateSupportDirectory} from './host-files.mjs';\nconst UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;\nconst HASH=/^[a-f0-9]{64}$/;\nconst ACTIONS=Object.fromEntries(['status','catalog','selection','capture','inspect','attach','case','restore']\n  .map(action=>['merchant_case_commercial_tariff_'+action,action]));\nexport function merchantCommercialTariffs({cases,casesDirectory,exportsDirectory,reads}={}){\n  let opening,closing=false,closed;\n  const original=()=>opening??=Promise.resolve(cases()).then(store=>openCommercialTariffController({store,casesDirectory:casesDirectory()}));\n  return {\n    handles:name=>Object.hasOwn(ACTIONS,name)||name==='merchant_case_commercial_tariff_file',\n    async call(name,args){\n      if(closing)throw failure('SUPPORT_CLOSING','The original Support owner is draining current tariff work.');\n      if(name==='merchant_case_commercial_tariff_file'){\n        exact(args,['id','revision','sourceId','kind','readId','expectedSha256','offset','limit'],['id','revision','sourceId','kind']);\n        if(!UUID.test(args.id??'')||!HASH.test(args.revision??'')||!HASH.test(args.sourceId??'')||\n            !['SOURCE','PORTFOLIO'].includes(args.kind)||args.readId!==undefined&&!UUID.test(args.readId))\n          throw failure('INVALID_PARAMS','Select the exact original case revision, tariff source and complete file.');\n        const choice={id:args.id,revision:args.revision,sourceId:args.sourceId,kind:args.kind};\n        return {...choice,...await reads.read({scope:'commercial:'+args.id,key:JSON.stringify(choice),kind:'merchant-commercial-tariff',\n          directory:await privateSupportDirectory(exportsDirectory()),readId:args.readId,expectedSha256:args.expectedSha256,\n          offset:args.offset,limit:args.limit,load:async()=>{\n            const received=await(await original()).call('download',choice),result=received.result;\n            return {bytes:result.body,name:result.descriptor.filename,type:result.descriptor.mediaType};\n          }})};\n      }\n      if(!Object.hasOwn(ACTIONS,name))throw failure('TOOL_NOT_FOUND','Unknown original tariff quotation operation.');\n      return (await original()).call(ACTIONS[name],args);\n    },\n    close(){return closed??=(async()=>{closing=true;if(opening)await(await opening).close();})();},\n  };\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/support-commercial.mjs",
      "gitBlob": "c474e273ec451e8a3a06794a6bbca47811d42546",
      "bytes": 5296,
      "sha256": "f62e70588fd36d4ae5b3d1def656304d165a63648fa5095638e1e6227d5c0826",
      "content": "import {merchantCommercialReceiving} from './support-commercial-receiving.mjs';\nimport {merchantCommercialTariffs} from './support-commercial-tariffs.mjs';\n// MIT. Original saved merchant quotation through the configured support owner.\nimport {openCaseCommercial,commercialWorkspaceId} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-commercial.mjs';\nimport {failure,exact,privateSupportDirectory} from './host-files.mjs';\nconst UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;\nconst HASH=/^[a-f0-9]{64}$/;\nexport function merchantCommercial({cases,casesDirectory,exportsDirectory,reads,environment=process.env}) {\n  const receiving=merchantCommercialReceiving({cases,casesDirectory,environment});\n  const tariffs=merchantCommercialTariffs({cases,casesDirectory,exportsDirectory,reads});\n  let model;\n  const original=async()=>model??=openCaseCommercial({store:await cases(),workspaceId:commercialWorkspaceId(casesDirectory())});\n  const selected=args=>{if(!UUID.test(args.id??''))throw failure('INVALID_CASE_ID','Choose the original saved case UUID.');return 'commercial:'+args.id;};\n  return {\n    handles:name=>name.startsWith('merchant_case_commercial'),\n    async call(name,args) {\n      if(tariffs.handles(name))return tariffs.call(name,args);\n      if(receiving.handles(name))return receiving.call(name,args);\n      const scope=selected(args);\n      if(name==='merchant_case_commercial_file_reads') {\n        exact(args,['id'],['id']);return {id:args.id,...reads.status(scope)};\n      }\n      if(name==='merchant_case_commercial_file_release') {\n        exact(args,['id','readId'],['id','readId']);\n        if(!UUID.test(args.readId??''))throw failure('INVALID_PARAMS','Keep the original file read UUID.');\n        await reads.release(scope,args.readId);return {id:args.id,readId:args.readId,released:true};\n      }\n      if(name==='merchant_case_commercial_performance_file') {\n        exact(args,['id','revision','sourceId','kind','expectedSha256','readId','offset','limit'],['id','revision','sourceId','kind']);\n        if(!HASH.test(args.revision??'')||!HASH.test(args.sourceId??'')||\n            !['SOURCE','ATTACHMENT','REPORT'].includes(args.kind)||args.readId!==undefined&&!UUID.test(args.readId))\n          throw failure('INVALID_PARAMS','Select the saved case revision, recorded performance source and full file kind.');\n        const choice={id:args.id,revision:args.revision,sourceId:args.sourceId,kind:args.kind};\n        return {...choice,...await reads.read({scope,key:JSON.stringify(choice),kind:'merchant-commercial-performance',\n          directory:await privateSupportDirectory(exportsDirectory()),readId:args.readId,offset:args.offset,\n          limit:args.limit,expectedSha256:args.expectedSha256,load:async()=>{\n            const result=await (await original()).downloadPerformance(choice);\n            return {bytes:result.body,name:result.descriptor.filename,type:result.descriptor.mediaType};\n          }})};\n      }\n      if(name==='merchant_case_commercial_file') {\n        exact(args,['id','revision','quoteId','quoteSha256','kind','expectedSha256','readId','offset','limit'],\n          ['id','revision','quoteId','quoteSha256','kind']);\n        if(!HASH.test(args.revision??'')||!UUID.test(args.quoteId??'')||!HASH.test(args.quoteSha256??'')||\n            !['QUOTE','QUOTE_JSON'].includes(args.kind)||args.readId!==undefined&&!UUID.test(args.readId))\n          throw failure('INVALID_PARAMS','Choose the exact saved case revision, quote edition and document kind.');\n        const choice={id:args.id,revision:args.revision,quoteId:args.quoteId,quoteSha256:args.quoteSha256,kind:args.kind};\n        return {...choice,...await reads.read({scope,key:JSON.stringify(choice),kind:'merchant-commercial',\n          directory:await privateSupportDirectory(exportsDirectory()),readId:args.readId,offset:args.offset,\n          limit:args.limit,expectedSha256:args.expectedSha256,load:async()=>{\n            const result=await (await original()).download(choice);\n            return {bytes:result.body,name:result.descriptor.filename,type:result.descriptor.mediaType};\n          }})};\n      }\n      const method={\n        merchant_case_commercial:'read',merchant_case_commercial_preview:'preview',\n        merchant_case_commercial_save_draft:'saveDraft',merchant_case_commercial_publish:'publish',\n        merchant_case_commercial_receive_pricing:'receivePricing',merchant_case_commercial_receive:'receive',\n        merchant_case_commercial_compare:'compare',\n        merchant_case_commercial_performance_preview:'previewPerformance',\n        merchant_case_commercial_performance_receive:'receivePerformance',\n        merchant_case_commercial_performance_revision:'preparePerformanceRevision',\n        merchant_case_commercial_preview_implementation:'previewImplementation',\n        merchant_case_commercial_adopt_implementation:'adoptImplementation',\n      }[name];\n      if(!method)throw failure('TOOL_NOT_FOUND','Unknown original merchant quotation operation.');\n      return (await original())[method](args);\n    },\n    close:async()=>{const results=await Promise.allSettled([receiving.close(),tariffs.close()]);const failed=results.find(row=>row.status==='rejected');if(failed)throw failed.reason;},\n  };\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/support-download.mjs",
      "gitBlob": "802f8b924d85c515ec850f88314c80d112deec5c",
      "bytes": 6137,
      "sha256": "a02860a7e4a05f64887bc35665266c427b3d9407991609717fa69d4f1f9b0ce4",
      "content": "// MIT. Original support transfer adapter and native saved-case reopening.\nimport { createHash, randomUUID } from 'node:crypto';\nimport { join, resolve } from 'node:path';\nimport { realpath } from 'node:fs/promises';\nimport { createRetainedDownload } from './retained-download.mjs';\nimport { parseSupportExportManifest } from './support.mjs';\nimport { failure, privateSupportDirectory } from './host-files.mjs';\nimport { importRuntimeHandoff, MAX_HANDOFF_BYTES } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/runtime-support.mjs';\nimport { openCaseStore, caseMetadata } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-store.mjs';\nexport { openMerchantFileClient } from './retained-download.mjs';\n\nconst sha = bytes => createHash('sha256').update(bytes).digest('hex');\nconst decode = bytes => new TextDecoder('utf-8', { fatal: true }).decode(bytes);\nconst validReadId = value => typeof value === 'string' && /^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(value);\nconst transfer = createRetainedDownload({ manifestName: 'support-export.json', parseManifest: parseSupportExportManifest,\n  maximumBytes: MAX_HANDOFF_BYTES, stateSchema: 'stellar-forge.merchant-support-download.v1',\n  resultSchema: 'stellar-forge.merchant-support-download-result.v1', toolPrefix: 'merchant_support_export',\n  errorPrefix: 'SUPPORT', clientName: 'starforge-support-download', describe: manifest => ({ case: manifest.case }) });\nconst { lockedDownload, loadContext, bytesAt, verifiedFile, checkpoint } = transfer;\nexport const downloadSupportExport = transfer.download;\nexport const inspectSupportExport = transfer.inspect;\n\n/** Offline continuation through the original SF74 importer and its versioned store. */\nexport async function reopenDownloadedSupportExport({ directory, casesDirectory } = {}) {\n  if (typeof casesDirectory !== 'string' || !casesDirectory || casesDirectory.includes('\\0'))\n    throw failure('SUPPORT_DOWNLOAD_CONFIGURATION', 'Supply the original private case directory.');\n  const cases = await realpath(await privateSupportDirectory(resolve(casesDirectory)));\n  return lockedDownload(directory, async context => {\n    const bytes = await bytesAt(join(context.root, 'support-export.json'), 65000);\n    let exportId; try { exportId = JSON.parse(decode(bytes)).exportId; } catch { throw failure('SUPPORT_EXPORT_INVALID', 'Open a completed original support export.'); }\n    await loadContext(context, bytes, exportId);\n    for (const file of context.manifest.files) await verifiedFile(join(context.root, file.name), file);\n    const source = JSON.parse(decode(await bytesAt(join(context.root, 'case.json'), MAX_HANDOFF_BYTES)));\n    let original = { workspaceText: decode(await bytesAt(join(context.root, 'merchant-workspace.json'), MAX_HANDOFF_BYTES)), supportText: null, metadata: caseMetadata(source.metadata) };\n    if (context.manifest.case.supportSha256 !== null)\n      original = await importRuntimeHandoff(decode(await bytesAt(join(context.root, 'merchant-support.json'), MAX_HANDOFF_BYTES)));\n    if (sha(original.workspaceText) !== context.manifest.case.workspaceSha256 ||\n        (original.supportText === null ? null : sha(original.supportText)) !== context.manifest.case.supportSha256)\n      throw failure('SUPPORT_DOWNLOAD_EXPORT_CHANGED', 'The original case inputs disagree with the downloaded completion manifest.');\n    const bound = context.state.localCase;\n    if (bound && (bound.directory !== cases || !validReadId(bound.id)))\n      throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'This download already reopens in a different local case directory. Use its retained original case.');\n    if (!bound) { context.state.localCase = { directory: cases, id: randomUUID(), revision: null }; await checkpoint(context); }\n    const local = context.state.localCase, store = await openCaseStore(cases);\n    if (!local.revision) {\n      let existing;\n      try { existing = await store.read(local.id); } catch (error) { if (error.code !== 'CASE_NOT_FOUND') throw error; }\n      if (existing) {\n        // A save may have completed before its download checkpoint, followed by\n        // a legitimate local edit. Recover the original first revision without\n        // replaying the save over the current head or discarding the edit.\n        let before = null, initial = null; const seen = new Set();\n        do {\n          const page = await store.history(local.id, { before, limit: 100 });\n          for (const row of page.revisions) {\n            if (seen.has(row.revision)) throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'The retained local case history contains a cycle.');\n            seen.add(row.revision);\n            if (row.previousRevision === null) initial = row;\n          }\n          before = page.nextBefore;\n        } while (before);\n        if (!initial) throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'The original imported case revision is absent from local history.');\n        const first = await store.read(local.id, initial.revision);\n        if (sha(first.workspaceText) !== context.manifest.case.workspaceSha256 ||\n            (first.supportText === null ? null : sha(first.supportText)) !== context.manifest.case.supportSha256 ||\n            JSON.stringify(caseMetadata(first.metadata)) !== JSON.stringify(caseMetadata(original.metadata)))\n          throw failure('SUPPORT_DOWNLOAD_CASE_CONFLICT', 'The first local case revision differs from this downloaded original handoff.');\n        local.revision = initial.revision;\n      } else {\n        const saved = await store.save({ id: local.id, expectedRevision: null, ...original, metadata: caseMetadata(original.metadata) });\n        local.revision = saved.case.revision;\n      }\n      await checkpoint(context);\n    }\n    const reopened = await store.read(local.id);\n    return { schema: 'stellar-forge.merchant-support-reopened.v1', exportId, sourceCase: context.manifest.case,\n      case: { id: reopened.id, revision: reopened.revision, importedRevision: local.revision, directory: cases },\n      manifestSha256: context.manifestSha256, state: 'REOPENED' };\n  });\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/support-incidents.mjs",
      "gitBlob": "c8d7e050ed084f6c45dff12e0ebac4b3125095df",
      "bytes": 17958,
      "sha256": "1f6114c0f1b9bf7a034671503b584a36fbf415f23e1be1e6bbc3b41729ab73b8",
      "content": "// MIT. Host-declared incident sources over the original SF74/SF93 lifecycle.\nimport { openIncidentSources, incidentProblem } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/incident-sources.mjs';\nimport { importRuntimeHandoff, inspectRuntimeFiles } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/runtime-support.mjs';\nimport { openIncidentStore, statusView } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/incident-store.mjs';\nimport { incidentStatus } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/incident-operator.mjs';\nimport { resolveDestination } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/notifications.mjs';\nimport { inspectSlackDestination } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/notifications-slack.mjs';\nimport { failure } from './host-files.mjs';\nimport {readServiceIncidentSnapshot} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/service-source.mjs';\n\nconst SCHEMA='stellar-forge.merchant-support-incident-sources.v1';\nconst sourceNames=new Set(['merchant_support_profiles','merchant_support_configure','merchant_support_watch_status',\n  'merchant_support_watch_start','merchant_support_watch_stop','merchant_notifications','merchant_incident_notify',\n  'merchant_notification_update','merchant_incidents','merchant_incident_ack','merchant_incident_case']);\nconst addedNames=new Set(['merchant_support_incident_sources','merchant_support_destination','merchant_incident_view','merchant_support_service_snapshot']);\nconst UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;\nconst statuses=['OPEN','ACKNOWLEDGED','RECOVERED','RETIRED'];\nconst notificationStates=['PENDING','RETRY','IN_FLIGHT','PAUSED','EXHAUSTED','DELIVERED','CANCELLED'];\nconst fail=(code,message,status=400)=>Object.assign(failure(code,message),{status});\nconst uuid=value=>{if(typeof value!=='string'||!UUID.test(value))throw fail('INVALID_CASE_ID','Use an original incident, notification, case or watcher UUID.');return value;};\nconst integer=(value,label,min=0)=>{if(!Number.isSafeInteger(value)||value<min)throw fail('INVALID_PARAMS','Use the current original '+label+'.');return value;};\nconst digest=value=>{if(typeof value!=='string'||!/^[a-f0-9]{64}$/.test(value))throw fail('INVALID_PARAMS','Use the exact inspected original SHA-256.');return value;};\nconst projection=value=>({schema:value.schema,sha256:value.sha256,\n  sources:value.sources.map(({id,label,directory})=>({id,label,directory}))});\nconst publicSource=value=>value?{id:value.id,label:value.label}:null;\nfunction pagination(args){\n  const offset=integer(args.offset??0,'page offset'),limit=integer(args.limit??50,'page limit',1);\n  if(limit>100)throw fail('INVALID_PARAMS','Use a page limit from 1 to 100.');\n  return {offset,limit};\n}\nfunction pageRows(rows,{offset,limit}){\n  return {total:rows.length,offset,limit,nextOffset:offset+limit<rows.length?offset+limit:null};\n}\nfunction latestNotifications(state){\n  const values=new Map();for(const event of state.notifications)values.set(event.incidentId,event.id);return values;\n}\nasync function originalView(directory,id){\n  uuid(id);\n  return (await openIncidentStore(directory)).transaction(async(state,io)=>{\n    const incident=state.incidents.find(value=>value.id===id);\n    if(!incident)throw fail('SF93_INCIDENT_NOT_FOUND','The incident was not found in this original store.',404);\n    const routes=new Map(),captureProblems={};\n    for(const side of ['before','after']){\n      const ref=incident[side+'Capture'];if(!ref)continue;\n      try{\n        const files=await io.readCapture(ref);\n        const encoded=Object.fromEntries(Object.entries(files).map(([name,bytes])=>[name,bytes.toString('base64')]));\n        for(const route of inspectRuntimeFiles({files:encoded}).routes){\n          const value={id:route.id,method:route.method,...(route.path===undefined?{}:{path:route.path})};\n          const key=JSON.stringify(value),retained=routes.get(key)??{...value,sides:[]};\n          retained.sides.push(side);routes.set(key,retained);\n        }\n      }catch(error){const problem=incidentProblem(error);captureProblems[side]={error:problem.error,detail:problem.detail};}\n    }\n    return {revision:state.revision,configRevision:state.configRevision,configHash:state.configHash,\n      incident:structuredClone(incident),latestNotificationId:latestNotifications(state).get(id)??null,\n      notifications:statusView(state).notifications.filter(value=>value.incidentId===id),\n      routes:[...routes.values()],captureProblems};\n  },{readonly:true});\n}\n\nexport class MerchantSupportIncidentSources {\n  #config;#callbacks;#environment;#opening;#manager;#closing=false;#close;\n  #lifecycle=new Set();#started=new Map();#exits=new Map();\n  constructor(config,callbacks,{environment=process.env}={}){\n    this.#config=config;this.#callbacks=callbacks;this.#environment=environment;\n  }\n  get configured(){return Boolean(this.#config?.incidentSourcesFile);}\n  handles(name){return addedNames.has(name)||this.configured&&sourceNames.has(name);}\n  get summary(){\n    return {mode:this.configured?'sources':'legacy',configured:Boolean(this.configured||this.#config?.incidentsDirectory),\n      sourceConfigurationSha256:this.#config?.incidentSources?.sha256??null,\n      defaultIncidentSource:this.#config?.defaultIncidentSource??(this.#config?.incidentSources?.sources.length===1?this.#config.incidentSources.sources[0].id:null),\n      sources:(this.#config?.incidentSources?.sources??[]).map(publicSource),closing:this.#closing};\n  }\n  async #open(){\n    if(this.#closing)throw fail('OPERATOR_CLOSING','Merchant support is closing.',503);\n    if(!this.configured)return null;\n    if(!this.#opening){\n      const opening=(async()=>{\n        const manager=await openIncidentSources({configPath:this.#config.incidentSourcesFile,environment:this.#environment});\n        try{\n          if(JSON.stringify(projection(manager.configuration()))!==JSON.stringify(this.#config.incidentSources))\n            throw fail('SUPPORT_INCIDENT_SOURCES_CHANGED','The host incident source selection changed. Review and restart the original merchant configuration.',409);\n          if(this.#closing)throw fail('OPERATOR_CLOSING','Merchant support is closing.',503);\n          this.#manager=manager;return manager;\n        }catch(error){await manager.close();throw error;}\n      })();\n      this.#opening=opening;\n      // A transient original-store failure may recover. Every new opening still\n      // checks the same host-selected bytes and canonical store identities.\n      opening.catch(()=>{if(this.#opening===opening)this.#opening=null;});\n    }\n    return this.#opening;\n  }\n  #source(args){\n    if(!this.configured){\n      if(args.incidentSource!==undefined)\n        throw fail('SUPPORT_INCIDENT_SOURCE_NOT_FOUND','This connection uses its original single incident store; omit incidentSource or select a host source file.',404);\n      if(!this.#config?.incidentsDirectory)throw fail('INCIDENTS_NOT_CONFIGURED','Register an existing original incident store or source file on the host.');\n      return null;\n    }\n    const entries=this.#config.incidentSources.sources;\n    const id=args.incidentSource??this.#config.defaultIncidentSource??(entries.length===1?entries[0].id:undefined);\n    const selected=entries.find(value=>value.id===id);\n    if(!selected)throw fail('SUPPORT_INCIDENT_SOURCE_NOT_FOUND','Choose incidentSource from merchant_support_incident_sources.',404);\n    return selected;\n  }\n  #directory(source){return source?.directory??this.#config.incidentsDirectory;}\n  async #status(source,manager){\n    const state=await manager.list(source.id,{limit:1}),worker=state.worker,started=this.#started.get(source.id);\n    const owned=worker.ownership==='console'?{\n      instanceId:worker.recorded?.instanceId??started?.instanceId??null,state:worker.status,\n      startedConfiguration:started?.configuration??null}:null;\n    return {schema:'stellar-forge.merchant-support-watch.v1',incidentSource:publicSource(source),\n      configRevision:state.configRevision,configHash:state.configHash,worker:worker.recorded,\n      owned,lastOwnedExit:this.#exits.get(source.id)??null,watcher:worker};\n  }\n  async #withLifecycle(source,action){\n    if(this.#lifecycle.has(source.id))throw fail('INCIDENT_WATCH_BUSY','The original source watcher is starting or stopping. Read its current status.',409);\n    this.#lifecycle.add(source.id);try{return await action();}finally{this.#lifecycle.delete(source.id);}\n  }\n  async #start(source,manager,args){\n    integer(args.expectedConfigRevision,'configuration revision',1);digest(args.expectedConfigHash);\n    return this.#withLifecycle(source,async()=>{\n      const result=await manager.start(source.id,{expectedConfigRevision:args.expectedConfigRevision,expectedConfigHash:args.expectedConfigHash});\n      const instanceId=result.worker.recorded?.instanceId;\n      if(!instanceId){\n        await manager.stop(source.id);\n        throw fail('INCIDENT_WATCH_NOT_STARTED','The original watcher did not retain its started instance.',409);\n      }\n      this.#started.set(source.id,{instanceId,configuration:{configRevision:args.expectedConfigRevision,configHash:args.expectedConfigHash}});\n      this.#exits.delete(source.id);\n      return this.#status(source,manager);\n    });\n  }\n  async #stop(source,manager,args){\n    uuid(args.instanceId);\n    return this.#withLifecycle(source,async()=>{\n      const started=this.#started.get(source.id),prior=this.#exits.get(source.id);\n      if(!started||started.instanceId!==args.instanceId){\n        if(prior?.instanceId===args.instanceId&&prior.state==='STOPPED')return {...await this.#status(source,manager),unchanged:true};\n        throw fail('INCIDENT_WATCH_INSTANCE_CONFLICT','This MCP operator does not own that source watcher instance. Read its current status.',409);\n      }\n      const result=await manager.stop(source.id);\n      const stopped={instanceId:args.instanceId,state:result.worker.error?'FAILED':'STOPPED',\n        completedAt:new Date().toISOString(),code:result.worker.error??null};\n      this.#exits.set(source.id,stopped);this.#started.delete(source.id);\n      return this.#status(source,manager);\n    });\n  }\n  async #destination(source,manager,args){\n    integer(args.expectedConfigRevision,'configuration revision',1);\n    if(manager)return manager.inspectDestination(source.id,{expectedConfigRevision:args.expectedConfigRevision});\n    const state=await (await openIncidentStore(this.#directory(source))).read();\n    if(state.configRevision!==args.expectedConfigRevision)throw fail('SF93_CONFIGURATION_REVISION_CONFLICT','The original configuration changed. Inspect it again before checking the destination.',409);\n    const selected=resolveDestination(state.config,this.#environment);\n    const result=selected.reason?{accepted:false,reason:selected.reason}:selected.transport==='slack'\n      ?await inspectSlackDestination(selected,state.config.notification)\n      :{accepted:true,reason:'WEBHOOK_CONFIGURATION_RESOLVED',destinationId:selected.binding.id};\n    return {configRevision:state.configRevision,configHash:state.configHash,...result};\n  }\n  async serviceSnapshot(args){\n    const manager=await this.#open(),source=this.#source(args);\n    return manager?manager.serviceSnapshot(source.id,{merchantId:args.merchantId}):\n      readServiceIncidentSnapshot({directory:this.#directory(source),source:{id:'legacy',label:'Original incident store'},merchantId:args.merchantId});\n  }\n  async call(name,args={}){\n    if(name==='merchant_support_service_snapshot')return {snapshot:await this.serviceSnapshot(args)};\n    const manager=await this.#open();\n    if(name==='merchant_support_incident_sources')return {schema:SCHEMA,...this.summary};\n    const source=this.#source(args),selected=publicSource(source);\n    try{\n      if(name==='merchant_support_destination')return {...await this.#destination(source,manager,args),incidentSource:selected};\n      if(name==='merchant_incident_view'){\n        const result=manager?await manager.view(source.id,uuid(args.id)):await originalView(this.#directory(source),args.id);\n        return {...result,incidentSource:selected};\n      }\n      if(!manager)throw fail('SUPPORT_INCIDENT_SOURCES_REQUIRED','Select the original incident source file in the host support connection.');\n      switch(name){\n        case 'merchant_support_profiles':{\n          const current=await manager.list(source.id,{limit:1});\n          const state={configRevision:current.configRevision,configHash:current.configHash,configuration:current.config};\n          if(args.profile===undefined)return {incidentSource:selected,profiles:this.#callbacks.profiles(),current:state};\n          const profile=await this.#callbacks.profile(args.profile);\n          return {...profile,incidentSource:selected,current:state,matchesCurrent:profile.configHash===current.configHash,\n            changes:this.#callbacks.configurationChanges(current.config,profile.configuration)};\n        }\n        case 'merchant_support_configure':{\n          const profile=await this.#callbacks.profile(args.profile,args.expectedSourceSha256);\n          digest(args.expectedSourceSha256);\n          const result=await manager.configure(source.id,{config:profile.configuration,expectedConfigRevision:args.expectedConfigRevision});\n          return {...result,incidentSource:selected,profile:profile.profile,sourceSha256:profile.sourceSha256,\n            unchanged:result.configRevision===args.expectedConfigRevision};\n        }\n        case 'merchant_support_watch_status':return this.#status(source,manager);\n        case 'merchant_support_watch_start':return this.#start(source,manager,args);\n        case 'merchant_support_watch_stop':return this.#stop(source,manager,args);\n        case 'merchant_notifications':{\n          const state=await incidentStatus({directory:source.directory}),page=pagination(args);\n          if(args.id!==undefined)uuid(args.id);if(args.incidentId!==undefined)uuid(args.incidentId);\n          if(args.status!==undefined&&!notificationStates.includes(args.status))throw fail('INVALID_PARAMS','Choose an original notification status.');\n          const found=state.notifications.filter(row=>(args.id===undefined||row.id===args.id)&&\n            (args.incidentId===undefined||row.incidentId===args.incidentId)&&(args.status===undefined||row.status===args.status));\n          return {incidentSource:selected,directoryRevision:state.directoryRevision,...pageRows(found,page),\n            notifications:found.slice(page.offset,page.offset+page.limit),notificationCapacityEvents:state.notificationCapacityEvents};\n        }\n        case 'merchant_incident_notify':\n          return {...await manager.notify(source.id,uuid(args.id),{\n            expectedRevision:args.expectedRevision,...(Object.hasOwn(args,'expectedNotificationId')?{expectedNotificationId:args.expectedNotificationId}:{})}),incidentSource:selected};\n        case 'merchant_notification_update':\n          return {...await manager.notification(source.id,uuid(args.id),{\n            expectedAttempts:args.expectedAttempts,action:args.action,by:args.by}),incidentSource:selected};\n        case 'merchant_incidents':{\n          const state=await incidentStatus({directory:source.directory,details:true}),page=pagination(args);\n          if(args.id!==undefined)uuid(args.id);\n          if(args.status!==undefined&&!statuses.includes(args.status))throw fail('INVALID_PARAMS','Choose an original incident status.');\n          const latest=latestNotifications(state);\n          const found=state.incidents.filter(row=>(args.id===undefined||row.id===args.id)&&(args.status===undefined||row.status===args.status));\n          const incidents=found.slice(page.offset,page.offset+page.limit).map(row=>({...row,latestNotificationId:latest.get(row.id)??null}));\n          const ids=new Set(incidents.map(row=>row.id));\n          return {schema:state.schema,incidentSource:selected,directoryRevision:state.directoryRevision,\n            configRevision:state.configRevision,configHash:state.configHash,worker:state.worker,active:state.active,\n            incidents,...pageRows(found,page),notifications:state.notifications.filter(row=>ids.has(row.incidentId)),captureStorage:state.captureStorage};\n        }\n        case 'merchant_incident_ack':\n          return {...await manager.acknowledge(source.id,uuid(args.id),{expectedRevision:args.expectedRevision,by:args.by,notes:args.notes??''}),incidentSource:selected};\n        case 'merchant_incident_case':{\n          uuid(args.id);uuid(args.incidentId);digest(args.expectedTemplateSha256);\n          const template=await this.#callbacks.template(args.template,args.expectedTemplateSha256);\n          const prepared=await manager.prepareCase(source.id,args.incidentId,{\n            expectedRevision:args.expectedIncidentRevision,workspaceText:template.workspaceText,routeId:args.routeId});\n          const handoff=await importRuntimeHandoff(prepared.handoff);\n          const result=await (await this.#callbacks.cases()).save({id:args.id,expectedRevision:null,...handoff});\n          return {...result,incidentSource:selected,incident:{id:args.incidentId,revision:args.expectedIncidentRevision},\n            templateSha256:template.sourceSha256};\n        }\n        default:throw fail('TOOL_NOT_FOUND','Unknown original support incident operation.');\n      }\n    }catch(error){\n      if(/^(SF93|FLEET)_/.test(String(error.message??''))){\n        const problem=incidentProblem(error);throw fail(problem.error,problem.detail,problem.status);\n      }\n      throw error;\n    }\n  }\n  close(){\n    if(this.#close)return this.#close;\n    this.#closing=true;\n    this.#close=(async()=>{\n      if(!this.#opening)return;\n      let manager;try{manager=await this.#opening;}catch{return;}\n      await manager.close();\n    })();\n    return this.#close;\n  }\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/support-service-adjustments.mjs",
      "gitBlob": "944ea853dd40802899d34e08f0a586825873da62",
      "bytes": 3760,
      "sha256": "5efe513125dd5db54cb75ad81f7b7db347504587a3fa7fb8396465f8af37b926",
      "content": "// MIT. Borrow configured native owners; preserve the original saved Support case.\nimport {join} from 'node:path';\nimport {openCaseServiceAdjustments} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-service-adjustments.mjs';\nimport {exact,failure,privateSupportDirectory} from './host-files.mjs';\nconst UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;\nexport function merchantServiceAdjustments({cases,casesDirectory,exportsDirectory,reads,accounting,buyer}){\n  let model;\n  const original=()=>model??=(async()=>openCaseServiceAdjustments({store:await cases(),accounting,buyer,\n    directory:join(casesDirectory(),'service-adjustments')}))();\n  const scope=args=>{if(!UUID.test(args.id??''))throw failure('INVALID_CASE_ID','Choose the original saved case UUID.');return 'service-adjustments:'+args.id;};\n  return {\n    handles:name=>name.startsWith('merchant_service_adjustment_')||name.startsWith('merchant_service_buyer_'),\n    async call(name,args){\n      if(name==='merchant_service_adjustment_file_reads'){exact(args,['id'],['id']);return {id:args.id,...reads.status(scope(args))};}\n      if(name==='merchant_service_adjustment_file_release'){\n        exact(args,['id','readId'],['id','readId']);if(!UUID.test(args.readId??''))throw failure('INVALID_PARAMS','Retain the original file-read UUID.');\n        await reads.release(scope(args),args.readId);return {id:args.id,readId:args.readId,released:true};\n      }\n      if(name==='merchant_service_adjustment_file'||name==='merchant_service_buyer_file'){\n        const buyerFile=name==='merchant_service_buyer_file',fields=buyerFile?['outcomeId','name']:['proposalId','proposalSha256','outcomeId','kind'];\n        exact(args,['id','revision',...fields,'readId','offset','limit','expectedSha256'],['id','revision',...(buyerFile?['outcomeId','name']:['proposalId','proposalSha256','kind'])]);\n        const {readId,offset,limit,expectedSha256,...choice}=args;\n        return {...choice,...await reads.read({scope:scope(args),key:JSON.stringify({buyerFile,...choice}),kind:buyerFile?'service-buyer':'service-adjustment',\n          directory:await privateSupportDirectory(exportsDirectory()),readId,offset,limit,expectedSha256,load:async()=>{\n            const value=await (await original())[buyerFile?'downloadBuyer':'download'](choice);\n            return {bytes:value.body,name:value.descriptor.filename,type:value.descriptor.mediaType};\n          }})};\n      }\n      if(name==='merchant_service_adjustment_accounting'||name==='merchant_service_buyer_workspace'){\n        const {action,...input}=args;\n        return (await original())[name==='merchant_service_adjustment_accounting'?'accountingOperation':'buyerOperation'](action,input);\n      }\n      const method={\n        merchant_service_adjustment_read:'read',merchant_service_adjustment_sources:'sources',\n        merchant_service_adjustment_preview:'preview',merchant_service_adjustment_prepare:'prepareIntent',\n        merchant_service_adjustment_retain:'retain',merchant_service_adjustment_execute:'execute',\n        merchant_service_buyer_read:'buyerRead',merchant_service_buyer_sources:'buyerSources',\n        merchant_service_buyer_inspect:'inspectBuyer',merchant_service_buyer_accountant_preview:'previewBuyerAccountantReturn',merchant_service_buyer_prepare:'prepareBuyerIntent',\n        merchant_service_buyer_retain:'retainBuyer',merchant_service_buyer_execute:'executeBuyer'\n      }[name];\n      if(!method)throw failure('TOOL_NOT_FOUND','Choose an original Service adjustment operation.');\n      if(method==='sources'||method==='buyerSources')exact(args,[],[]);\n      return (await original())[method](args);\n    },\n    async close(){if(model)await (await model).close();}\n  };\n}\n"
    },
    {
      "path": "stellar-forge/mcp-merchant-operator/support.mjs",
      "gitBlob": "feb89aee7872dfad1d6daaf1519398ff4bea646d",
      "bytes": 44839,
      "sha256": "8677b6e2d3a7c3239a226baa8680c519e6b9146982c3805fc1f8cb21761dd7fa",
      "content": "import {merchantCommercial} from './support-commercial.mjs';\nimport {merchantServiceAdjustments} from './support-service-adjustments.mjs';\nimport { supportTools, alias, digest, uuid, notificationStatuses, page, text, selected, metadataSchema, termsSchema, exportNames, object } from './catalog/support.mjs';\nimport { MerchantSupportIncidentSources } from './support-incidents.mjs';\nimport {readServiceCase,changeServiceCase,previewServiceCase,readServiceCaseReport} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/service-cases.mjs';\nimport {renderServiceReport,serviceReportCsv,serviceSummary} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/service-commitments.mjs';\nexport { supportTools } from './catalog/support.mjs';\n// MIT. Configured MCP access to the original incident, case and workorder lifecycle.\nimport { createHash } from 'node:crypto';\nimport { join } from 'node:path';\nimport { mkdir, mkdtemp, rm } from 'node:fs/promises';\nimport { incidentStatus, acknowledgeIncident, exportIncident, configureIncidents, remindIncident,\n  operateNotification } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/incident-operator.mjs';\nimport { readPrivateFile, openIncidentStore } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/incident-store.mjs';\nimport { compileConfig as compileWatchConfig, configHash as watchConfigHash } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/incident-config.mjs';\nimport { runIncidentWatch } from '../../stellar/scf-starforge-20261009/sf93-seller-support-bundle/watch.mjs';\nimport { openCaseStore, retainCaseArtifact, caseMetadata, CASE_STATUSES } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-store.mjs';\nimport { parseWorkspace, serializeWorkspace, workspaceDraft, MAX_WORKSPACE_BYTES } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/workspace-file.mjs';\nimport { importRuntimeHandoff, exportRuntimeHandoff, reviewRuntime, MAX_HANDOFF_BYTES } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/runtime-support.mjs';\nimport { termsDraftFromDocument, termsDocumentFromDraft } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/terms-editor.mjs';\nimport { workorderFromSources } from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/workorder-source.mjs';\nimport {inspectCaseCommissioning,prepareCaseCommissioning,operateCaseCommissioning} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/case-commissioning.mjs';\nimport {commissioningSummary,commissioningReport,commissioningTasksCsv} from '../../stellar/scf-starforge-20261009/sf74-merchant-support-console/commissioning.mjs';\nimport { failure, exact, identifier, writePrivate, privateSupportDirectory } from './host-files.mjs';\nimport { RetainedFileReads, MAX_RETAINED_CHUNK_BYTES } from './retained-file-reads.mjs';\n\nconst sha = bytes => createHash('sha256').update(bytes).digest('hex');\nconst decode = bytes => new TextDecoder('utf-8', { fatal: true }).decode(bytes);\nconst json = value => JSON.stringify(value, null, 2) + '\\n';\nconst DRAFT_SCHEMA = 'stellar-forge.merchant-terms-draft.v1';\nconst EXPORT_SCHEMA = 'stellar-forge.merchant-support-export.v1';\n\n\n\n\n\n\n\n\n\n\n\nfunction expected(value) {\n  if (typeof value !== 'string' || !/^[a-f0-9]{64}$/.test(value)) throw failure('INVALID_PARAMS', 'Use the exact inspected SHA-256 or case revision.');\n  return value;\n}\nfunction caseId(value) {\n  if (typeof value !== 'string' || !new RegExp(uuid.pattern).test(value)) throw failure('INVALID_CASE_ID', 'Use an original case UUID.');\n  return value;\n}\nfunction configurationRevision(value) {\n  if (!Number.isSafeInteger(value) || value < 1) throw failure('INVALID_PARAMS', 'Use the exact current original configuration revision.');\n  return value;\n}\nfunction originalWatchError(error) {\n  if (/^[A-Z][A-Z0-9_]+$/.test(error.code ?? '')) return error.code;\n  if (/^(SF93|FLEET)_[A-Z0-9_]+$/.test(error.message ?? '')) return error.message;\n  return 'INCIDENT_WATCH_FAILED';\n}\nfunction configurationChanges(before, after) {\n  const prior = new Map(before.merchants.map(row => [row.id, row])), next = new Map(after.merchants.map(row => [row.id, row]));\n  return { addedMerchants: [...next.keys()].filter(id => !prior.has(id)),\n    removedMerchants: [...prior.keys()].filter(id => !next.has(id)),\n    changedMerchants: [...next.keys()].filter(id => prior.has(id) && JSON.stringify(prior.get(id)) !== JSON.stringify(next.get(id))),\n    merchantOrderChanged: JSON.stringify([...prior.keys()]) !== JSON.stringify([...next.keys()]),\n    settings: Object.keys(after).filter(key => !['schema', 'merchants'].includes(key) && JSON.stringify(before[key]) !== JSON.stringify(after[key])) };\n}\nfunction draftTerms(workspace) {\n  if (!workspace.termsText) throw failure('CASE_TERMS_REQUIRED', 'Record the owner terms in this case before creating its workorder.');\n  const value = JSON.parse(workspace.termsText);\n  exact(value, ['schema', 'values'], ['schema', 'values']);\n  if (value.schema !== DRAFT_SCHEMA) throw failure('CASE_TERMS_INVALID', 'Open this case in the original support console and review its terms.');\n  return termsDocumentFromDraft(value.values);\n}\nfunction ownerDraft(terms) {\n  exact(terms, Object.keys(termsSchema.properties), termsSchema.required);\n  exact(terms.merchantConsent, Object.keys(termsSchema.properties.merchantConsent.properties), ['status']);\n  exact(terms.commercial, Object.keys(termsSchema.properties.commercial.properties), ['priceApproval']);\n  const values = termsDraftFromDocument(terms);\n  for (const [key, value] of Object.entries(values)) {\n    if (value.length > 8192 || /[\\u0000-\\u0008\\u000b\\u000c\\u000e-\\u001f\\u007f]/.test(value) ||\n        !['deliveryScope', 'deliverables', 'acceptanceCriteria'].includes(key) && /[\\r\\n\\t]/.test(value))\n      throw failure('INVALID_PARAMS', 'Owner terms must reopen in their original form fields. Use delivery fields for multiline text.');\n  }\n  return JSON.stringify({ schema: DRAFT_SCHEMA, values });\n}\nfunction sourcePacket(record, workspace, options = {}) {\n  const terms = draftTerms(workspace), inputs = { terms: Buffer.from(json(terms)).toString('base64') };\n  if (workspace.workorderSource === 'runtime') {\n    if (!record.supportText) throw failure('CASE_RUNTIME_REQUIRED', 'This case has no retained runtime capture.');\n    inputs.supportText = record.supportText; inputs.inputs = workspace.inputs;\n  } else {\n    inputs.before = workspace.sources.before;\n    if (!workspace.baselineOnly && workspace.sources.after) {\n      inputs.after = workspace.sources.after;\n      if (Boolean(workspace.sources.postBefore) !== Boolean(workspace.sources.postAfter))\n        throw failure('CASE_SOURCE_PAIR_REQUIRED', 'Keep both original browser checks or clear the unpaired check in the support console.');\n      if (workspace.sources.postBefore) { inputs.postBefore = workspace.sources.postBefore; inputs.postAfter = workspace.sources.postAfter; }\n    }\n  }\n  const result = workorderFromSources(inputs,options);\n  result.packet.caseSource = { id: record.id, revision: record.revision, workspaceSha256: sha(record.workspaceText),\n    supportSha256: record.supportText === null ? null : sha(record.supportText) };\n  return { ...result, terms };\n}\nasync function caseView(record) {\n  const { workspaceText, supportText, ...summary } = record, workspace = await parseWorkspace(workspaceText);\n  let terms = null, termsIssue = null;\n  try { terms = draftTerms(workspace); } catch (error) { termsIssue = error.code ?? 'CASE_TERMS_DRAFT_INCOMPLETE'; }\n  return { ...summary, workorderSource: workspace.workorderSource ?? 'diagnostic', baselineOnly: workspace.baselineOnly,\n    workspaceSha256: sha(workspaceText), supportSha256: supportText === null ? null : sha(supportText),\n    terms, termsIssue, termsText: workspace.termsText,\n    ...(workspace.commissioning?{implementation:commissioningSummary(workspace.commissioning)}:{}),\n    ...(workspace.service?{service:serviceSummary(workspace.service)}:{}),\n    runtimeReview: supportText === null ? null : reviewRuntime(supportText, workspace.inputs) };\n}\n\n\n/** Same original completion format for host verification and client persistence. */\nexport function parseSupportExportManifest(bytes, exportId) {\n  identifier(exportId, 'Export ID');\n  if (bytes.length > 65000) throw failure('SUPPORT_EXPORT_INVALID', 'The original support export manifest is oversized.');\n  let manifest;\n  try { manifest = JSON.parse(decode(bytes)); }\n  catch { throw failure('SUPPORT_EXPORT_INVALID', 'The original support export manifest is not valid UTF-8 JSON.'); }\n  const invalid = () => { throw failure('SUPPORT_EXPORT_INVALID', 'The original support export manifest is inconsistent.'); };\n  if (manifest?.schema !== EXPORT_SCHEMA || manifest.exportId !== exportId || !Array.isArray(manifest.files) ||\n      manifest.files.length < 2 || manifest.files.length > exportNames.length || typeof manifest.workorderIncluded !== 'boolean' ||\n      !manifest.case || !new RegExp(uuid.pattern).test(manifest.case.id) || !new RegExp(digest.pattern).test(manifest.case.revision) ||\n      !new RegExp(digest.pattern).test(manifest.case.workspaceSha256) ||\n      manifest.case.supportSha256 !== null && !new RegExp(digest.pattern).test(manifest.case.supportSha256)) invalid();\n  const names = new Set();\n  for (const file of manifest.files) {\n    if (!file || !exportNames.includes(file.name) || names.has(file.name) ||\n        !Number.isSafeInteger(file.bytes) || file.bytes < 1 || file.bytes > MAX_HANDOFF_BYTES ||\n        typeof file.sha256 !== 'string' || !new RegExp(digest.pattern).test(file.sha256)) invalid();\n    names.add(file.name);\n  }\n  if (!names.has('case.json') || !names.has('merchant-workspace.json') ||\n      manifest.files.find(file => file.name === 'merchant-workspace.json').sha256 !== manifest.case.workspaceSha256 ||\n      ['merchant-support.json', 'support.html'].some(name => names.has(name) !== (manifest.case.supportSha256 !== null)) ||\n      ['owner-terms.json', 'packet.json', 'seller-packet.html', 'acceptance-checklist.md'].some(name => names.has(name) !== manifest.workorderIncluded)) invalid();\n  const implementationFiles=['merchant-commissioning.json','merchant-implementation.html','merchant-implementation-tasks.csv'];\n  if(implementationFiles.some(name=>names.has(name))&&!implementationFiles.every(name=>names.has(name)))invalid();\n  const serviceReportFiles=['merchant-service-report.json','merchant-service-report.csv','merchant-service-report.html'];\n  if(serviceReportFiles.some(name=>names.has(name))&&(!names.has('merchant-service.json')||!serviceReportFiles.every(name=>names.has(name))))invalid();\n  return manifest;\n}\nfunction exportFileType(name) {\n  return name.endsWith('.json') ? 'application/json' : name.endsWith('.html') ? 'text/html; charset=utf-8' : name.endsWith('.csv') ? 'text/csv; charset=utf-8' : 'text/markdown; charset=utf-8';\n}\n\nexport class MerchantSupport {\n  #config; #store; #commercial; #casePackages; #serviceAdjustments; #watch = null; #lastWatchExit = null; #closing = false; #close; #incidentSources; #environment;\n  #reads = new RetainedFileReads({ errorPrefix: 'SUPPORT' });\n  constructor(config, { environment = process.env, accounting = null, buyer = null } = {}) {\n    this.#config = config; this.#environment = environment;\n    this.#serviceAdjustments=merchantServiceAdjustments({cases:()=>this.#cases(),casesDirectory:()=>this.#configured().casesDirectory,\n      exportsDirectory:()=>this.#config.exportsDirectory,reads:this.#reads,accounting,buyer});\n    this.#commercial=merchantCommercial({cases:()=>this.#cases(),casesDirectory:()=>this.#configured().casesDirectory,\n      exportsDirectory:()=>this.#config.exportsDirectory,reads:this.#reads,environment});\n    this.#incidentSources = new MerchantSupportIncidentSources(config.support, {\n      profiles: () => this.summary.profiles,\n      profile: (alias, sourceDigest) => this.#profile(alias, sourceDigest),\n      configurationChanges,\n      template: (alias, sourceDigest) => this.#input('workspace', alias, sourceDigest),\n      cases: () => this.#cases()\n    }, { environment });\n  }\n  get summary() {\n    const value = this.#config.support;\n    return { configured: Boolean(value), incidentsConfigured: Boolean(value?.incidentsDirectory || value?.incidentSourcesFile),\n      incidentSources: this.#incidentSources.summary,\n      fileReads: this.#reads.summary,\n      watcher: { ownedInstanceId: this.#watch?.instanceId ?? null, state: this.#watch?.state ?? 'NOT_OWNED', lastExit: this.#lastWatchExit },\n      profiles: Object.entries(value?.profiles ?? {}).map(([profile, entry]) => ({ profile, label: entry.label })),\n      sources: value ? ['handoffs', 'workspaces'].flatMap(kind => Object.entries(value[kind]).map(([source, entry]) =>\n        ({ kind: kind === 'handoffs' ? 'handoff' : 'workspace', source, label: entry.label }))) : [] };\n  }\n  #configured() {\n    if (!this.#config.support) throw failure('SUPPORT_NOT_CONFIGURED', 'Add supportConnection to the host merchant configuration, then restart this MCP operator.');\n    return this.#config.support;\n  }\n  async #cases() { return this.#store ??= openCaseStore(this.#configured().casesDirectory); }\n  async #packages() {\n    if(this.#closing)throw failure('OPERATOR_CLOSING','Merchant support is closing.');\n    return this.#casePackages??=(async()=>{\n      const module=await import('./support-case-packages.mjs');\n      return module.openMerchantCasePackages({config:this.#config,store:await this.#cases(),environment:this.#environment});\n    })();\n  }\n  #incidents() {\n    const directory = this.#configured().incidentsDirectory;\n    if (!directory) throw failure('INCIDENTS_NOT_CONFIGURED', 'Register the existing SF93 incident directory in the host support connection.');\n    return directory;\n  }\n  async #profile(profile, sourceDigest) {\n    const entry = (this.#configured().profiles ?? {})[identifier(profile, 'Support profile alias')];\n    if (!entry) throw failure('SUPPORT_PROFILE_NOT_FOUND', 'Choose a host profile returned by merchant_support_profiles.');\n    const bytes = await readPrivateFile(entry.file, 65536), sourceSha256 = sha(bytes);\n    if (sourceDigest !== undefined && sourceSha256 !== expected(sourceDigest))\n      throw failure('SUPPORT_SOURCE_CHANGED', 'The configured profile changed. Inspect its actual original configuration before applying it.');\n    const configuration = compileWatchConfig(JSON.parse(decode(bytes)));\n    return { profile, label: entry.label, sourceSha256, configHash: watchConfigHash(configuration), configuration };\n  }\n  async #profiles(profile) {\n    const state = await (await openIncidentStore(this.#incidents())).read();\n    const current = { configRevision: state.configRevision, configHash: state.configHash, configuration: state.config };\n    if (profile === undefined) return { profiles: this.summary.profiles, current };\n    const selected = await this.#profile(profile);\n    return { ...selected, current, matchesCurrent: selected.configHash === state.configHash,\n      changes: configurationChanges(state.config, selected.configuration) };\n  }\n  async #watchStatus() {\n    const state = await incidentStatus({ directory: this.#incidents() });\n    return { schema: 'stellar-forge.merchant-support-watch.v1', configRevision: state.configRevision,\n      configHash: state.configHash, worker: state.worker,\n      owned: this.#watch ? { instanceId: this.#watch.instanceId, state: this.#watch.state,\n        startedConfiguration: this.#watch.startedConfiguration } : null,\n      lastOwnedExit: this.#lastWatchExit };\n  }\n  #watchExited(handle, error) {\n    handle.state = error ? 'FAILED' : 'STOPPED';\n    this.#lastWatchExit = { instanceId: handle.instanceId, state: handle.state,\n      completedAt: new Date().toISOString(), code: error ? originalWatchError(error) : null };\n    if (this.#watch === handle) this.#watch = null;\n  }\n  async #startWatch(args) {\n    const directory = this.#incidents();\n    configurationRevision(args.expectedConfigRevision); expected(args.expectedConfigHash);\n    if (this.#closing) throw failure('OPERATOR_CLOSING', 'Merchant support is closing.');\n    if (this.#watch) throw failure('INCIDENT_WATCH_ALREADY_OWNED', 'This operator already owns a watcher. Read merchant_support_watch_status.');\n    let resolveReady, rejectReady;\n    const ready = new Promise((resolve, reject) => { resolveReady = resolve; rejectReady = reject; });\n    const handle = { controller: new AbortController(), instanceId: null, state: 'STARTING', startedConfiguration: null, done: null };\n    this.#watch = handle;\n    handle.done = runIncidentWatch({ directory, signal: handle.controller.signal, environment: this.#environment,\n      expectedConfigRevision: args.expectedConfigRevision, expectedConfigHash: args.expectedConfigHash,\n      onReady: value => {\n        handle.instanceId = value.instanceId; handle.state = 'RUNNING';\n        handle.startedConfiguration = { configRevision: value.configRevision, configHash: value.configHash };\n        resolveReady();\n      } }).then(result => {\n        this.#watchExited(handle);\n        if (!handle.instanceId) rejectReady(failure('INCIDENT_WATCH_NOT_STARTED', 'The original watcher ended before it became ready.'));\n        return result;\n      }, error => { this.#watchExited(handle, error); rejectReady(error); throw error; });\n    // Keep a background failure visible in status without an unhandled rejection.\n    handle.done.catch(() => {});\n    await ready;\n    return this.#watchStatus();\n  }\n  async #stopWatch(instanceId) {\n    caseId(instanceId);\n    const handle = this.#watch;\n    if (!handle && this.#lastWatchExit?.instanceId === instanceId && this.#lastWatchExit.state === 'STOPPED')\n      return { ...await this.#watchStatus(), unchanged: true };\n    if (!handle || handle.instanceId !== instanceId)\n      throw failure('INCIDENT_WATCH_INSTANCE_CONFLICT', 'This MCP operator does not own that watcher instance. Read merchant_support_watch_status.');\n    handle.state = 'STOPPING'; handle.controller.abort(); await handle.done;\n    return this.#watchStatus();\n  }\n  async #notifications(args) {\n    const state = await incidentStatus({ directory: this.#incidents() }), offset = args.offset ?? 0, limit = args.limit ?? 50;\n    if (!Number.isSafeInteger(offset) || offset < 0 || !Number.isSafeInteger(limit) || limit < 1 || limit > 100 ||\n        args.status !== undefined && !notificationStatuses.includes(args.status)) throw failure('INVALID_PARAMS', 'Use a valid notification state and page.');\n    if (args.id !== undefined) caseId(args.id);\n    if (args.incidentId !== undefined) caseId(args.incidentId);\n    const found = state.notifications.filter(row => (args.id === undefined || row.id === args.id) &&\n      (args.incidentId === undefined || row.incidentId === args.incidentId) && (args.status === undefined || row.status === args.status));\n    return { directoryRevision: state.directoryRevision, notifications: found.slice(offset, offset + limit),\n      total: found.length, offset, limit, nextOffset: offset + limit < found.length ? offset + limit : null,\n      notificationCapacityEvents: state.notificationCapacityEvents };\n  }\n  async #input(kind, source, digest) {\n    if (!['handoff', 'workspace'].includes(kind)) throw failure('INVALID_PARAMS', 'Choose handoff or workspace.');\n    const entry = this.#configured()[kind === 'handoff' ? 'handoffs' : 'workspaces'][identifier(source, 'Support source alias')];\n    if (!entry) throw failure('SUPPORT_SOURCE_NOT_FOUND', 'Choose an alias returned by merchant_support_sources.');\n    const bytes = await readPrivateFile(entry.file, kind === 'handoff' ? MAX_HANDOFF_BYTES : MAX_WORKSPACE_BYTES);\n    const sourceSha256 = sha(bytes);\n    if (digest !== undefined && sourceSha256 !== expected(digest)) throw failure('SUPPORT_SOURCE_CHANGED', 'The configured input changed. Inspect its actual digest and mapping before importing it.');\n    const value = kind === 'handoff' ? await importRuntimeHandoff(decode(bytes)) : { workspaceText: decode(bytes), supportText: null, metadata: {} };\n    await parseWorkspace(value.workspaceText);\n    return { ...value, kind, source, label: entry.label, sourceSha256, bytes: bytes.length, file: entry.file };\n  }\n  async #selected(args) {\n    expected(args.expectedRevision);\n    const record = await (await this.#cases()).read(caseId(args.id));\n    if (record.currentRevision !== args.expectedRevision) throw failure('CASE_CONFLICT', 'A newer original case revision exists. Reopen the case before this operation.');\n    return record;\n  }\n  async #update(args) {\n    const record = await (await this.#cases()).read(caseId(args.id), expected(args.expectedRevision)), workspace = await parseWorkspace(record.workspaceText);\n    if (!['metadata', 'terms', 'workorderSource', 'baselineOnly'].some(key => Object.hasOwn(args, key)))\n      throw failure('INVALID_PARAMS', 'Provide a case metadata, terms or source-choice change.');\n    if (args.workorderSource !== undefined && !['runtime', 'diagnostic'].includes(args.workorderSource) ||\n        args.baselineOnly !== undefined && typeof args.baselineOnly !== 'boolean') throw failure('INVALID_PARAMS', 'Invalid saved workorder choice.');\n    const metadata = args.metadata === undefined ? record.metadata : caseMetadata({ ...record.metadata, ...args.metadata });\n    if (args.metadata !== undefined) exact(args.metadata, Object.keys(metadataSchema.properties));\n    const next = workspaceDraft(workspace,{baselineOnly:args.baselineOnly??workspace.baselineOnly,\n      workorderSource:args.workorderSource??workspace.workorderSource??'diagnostic'});\n    if (args.terms !== undefined) next.termsText = ownerDraft(args.terms);\n    // Keep the original save timestamp: metadata/terms updates do not change source observations,\n    // and an identical request can use the original case writer's lost-response retry handling.\n    const workspaceText = ['terms', 'workorderSource', 'baselineOnly'].some(key => Object.hasOwn(args, key))\n      ? await serializeWorkspace(next, { now: workspace.savedAt }) : record.workspaceText;\n    return (await this.#cases()).save({ id: args.id, expectedRevision: args.expectedRevision,\n      workspaceText, supportText: record.supportText, metadata });\n  }\n  async #exportRequest(exportId) {\n    const root=await privateSupportDirectory(this.#config.exportsDirectory),folder=join(root,identifier(exportId,'Export ID'));\n    let bytes;\n    try{bytes=await readPrivateFile(join(root,'.support-export-request-'+exportId+'.json'),65000);}\n    catch(error){if(error.code!=='ENOENT')throw error;await privateSupportDirectory(folder);\n      bytes=await readPrivateFile(join(folder,'support-export-request.json'),65000);}\n    let intent;try{intent=JSON.parse(decode(bytes));}catch{throw failure('SUPPORT_EXPORT_INVALID','The original export request is unreadable.');}\n    exact(intent,['schema','exportId','request','manifest'],['schema','exportId','request','manifest']);\n    if(intent.schema!=='stellar-forge.merchant-support-export-request.v1'||intent.exportId!==exportId)\n      throw failure('SUPPORT_EXPORT_INVALID','The original export request identity differs.');\n    exact(intent.request,['id','expectedRevision','includeWorkorder'],['id','expectedRevision','includeWorkorder']);\n    caseId(intent.request.id);expected(intent.request.expectedRevision);\n    if(typeof intent.request.includeWorkorder!=='boolean')throw failure('SUPPORT_EXPORT_INVALID','The original workorder selection differs.');\n    const manifest=parseS