      "content": "/* MIT. Source-delivery panel within the existing SF74 commissioning desk. */\n.sfb-panel{--sfb-ink:#182024;--sfb-muted:#626c72;--sfb-line:#c9ced1;--sfb-bg:#f3f4f4;color:var(--sfb-ink);font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;max-width:100%;min-width:0;border:1px solid var(--sfb-line);background:#fff;padding:24px}\n.sfb-panel *{box-sizing:border-box}.sfb-panel h3,.sfb-panel h4,.sfb-panel p{margin:0 0 10px}.sfb-panel h3{font-size:23px;letter-spacing:-.03em;line-height:1.2}.sfb-panel h4{font-size:15px}.sfb-panel button,.sfb-panel input,.sfb-panel select{font:inherit;max-width:100%;border:1px solid #adb5ba;background:#fff;color:var(--sfb-ink);border-radius:3px;padding:8px 11px}.sfb-panel button{cursor:pointer;font-weight:600;min-height:39px}.sfb-panel button:hover:not(:disabled){border-color:#151c20;background:#f0f2f3}.sfb-panel button:disabled{cursor:default;opacity:.5}.sfb-panel button:focus-visible,.sfb-panel a:focus-visible,.sfb-panel input:focus-visible,.sfb-panel select:focus-visible{outline:3px solid #8c969d;outline-offset:3px}.sfb-panel a{color:#172e3c;text-decoration:underline;text-underline-offset:3px}.sfb-panel code{font:12px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere;word-break:break-word}.sfb-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;border-bottom:1px solid var(--sfb-line);padding-bottom:18px}.sfb-heading>div{max-width:780px}.sfb-heading button{flex-shrink:0}.sfb-heading p:last-child{color:var(--sfb-muted);margin-bottom:0}.sfb-kicker{font-size:10px;font-weight:800;letter-spacing:.17em;color:var(--sfb-muted)}.sfb-message:empty{display:none}.sfb-message{padding:12px 0;color:#38464e;overflow-wrap:anywhere}.sfb-error{background:#f7eeed;border-left:3px solid #825952;padding:12px;margin:14px 0!important;white-space:pre-wrap;overflow-wrap:anywhere}.sfb-note{font-size:12px;color:var(--sfb-muted);max-width:900px}.sfb-pending{padding:16px;background:#eef0f1;border:1px solid var(--sfb-line);margin:16px 0}.sfb-pending p{font-size:13px}.sfb-progress{padding:14px 0}.sfb-progress[hidden]{display:none}.sfb-progress span{display:block;font-size:12px;margin-bottom:6px}.sfb-progress progress{width:100%;height:8px;accent-color:#43535e}.sfb-intake{padding:18px 0 22px;border-bottom:1px solid var(--sfb-line)}.sfb-case{display:flex;flex-wrap:wrap;gap:8px 24px;margin-bottom:16px;color:var(--sfb-muted);font-size:12px}.sfb-form-row{display:grid;grid-template-columns:minmax(220px,1fr) minmax(220px,2fr);gap:16px;margin:12px 0}.sfb-panel label{display:flex;flex-direction:column;gap:5px;font-size:12px;font-weight:600}.sfb-panel input,.sfb-panel select{font-size:14px;font-weight:400;width:100%}.sfb-file-input{margin:12px 0}.sfb-file-input input{padding:12px;background:#f7f8f8;border-style:dashed}.sfb-chosen{border:1px solid var(--sfb-line);margin:14px 0}.sfb-chosen label{display:grid;grid-template-columns:minmax(180px,1fr) 210px;align-items:center;gap:16px;padding:9px 12px;border-bottom:1px solid #e4e7e9}.sfb-chosen label:last-child{border-bottom:0}.sfb-chosen span{overflow-wrap:anywhere}.sfb-chosen small{display:block;color:var(--sfb-muted);font-weight:400}.sfb-primary{background:#202c34!important;color:#fff!important;border-color:#202c34!important}.sfb-workspace{display:grid;grid-template-columns:minmax(210px,260px) minmax(0,1fr);gap:24px;padding-top:22px}.sfb-workspace aside{min-width:0;border-right:1px solid var(--sfb-line);padding-right:20px}.sfb-workspace aside h4{display:flex;justify-content:space-between;gap:10px}.sfb-workspace aside h4 span{font-weight:400;color:var(--sfb-muted)}.sfb-transfer-list{display:flex;flex-direction:column;gap:7px}.sfb-transfer-list button{display:flex;flex-direction:column;text-align:left;padding:12px;gap:3px;overflow-wrap:anywhere}.sfb-transfer-list button[aria-current=true]{border-color:#26333c;background:#e9edef;box-shadow:inset 3px 0 #26333c}.sfb-transfer-list strong{font-size:13px}.sfb-transfer-list span{font-size:11px;color:#44515a}.sfb-transfer-list small{font-size:10px;font-weight:400;color:var(--sfb-muted)}.sfb-pages{display:flex;justify-content:space-between;gap:8px;margin-top:15px}.sfb-pages button{font-size:11px;padding:6px 9px}.sfb-detail{min-width:0}.sfb-detail>header{border-bottom:1px solid var(--sfb-line);margin-bottom:14px;padding-bottom:8px}.sfb-status{display:flex;flex-wrap:wrap;gap:8px;font-size:11px;font-weight:600;margin:0 0 14px}.sfb-status span{border:1px solid var(--sfb-line);padding:3px 7px;background:#f1f3f4}.sfb-panel details{margin:14px 0;border:1px solid var(--sfb-line);min-width:0}.sfb-panel summary{cursor:pointer;padding:10px 12px;font-weight:600;font-size:13px;background:#f4f5f5}.sfb-panel details>p{padding:10px 12px;margin:0}.sfb-scroll{overflow-x:auto;max-width:100%;border:1px solid var(--sfb-line)}.sfb-panel details>.sfb-scroll{border:0;border-top:1px solid var(--sfb-line)}.sfb-panel table{border-collapse:collapse;width:100%;min-width:690px;table-layout:fixed;font-size:12px}.sfb-panel th,.sfb-panel td{text-align:left;vertical-align:top;padding:10px 11px;border-bottom:1px solid #dfe3e5;overflow-wrap:anywhere}.sfb-panel th{font-size:10px;text-transform:uppercase;letter-spacing:.06em;background:#f0f2f3;font-weight:700}.sfb-panel th:nth-child(1){width:27%}.sfb-panel th:nth-child(2){width:17%}.sfb-panel th:nth-child(3){width:13%}.sfb-panel th:nth-child(4){width:32%}.sfb-panel th:nth-child(5){width:11%}.sfb-panel tr:last-child td{border-bottom:0}.sfb-number{font-variant-numeric:tabular-nums;text-align:right!important}.sfb-file{font-weight:600}.sfb-actions{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.sfb-actions button{font-size:12px}.sfb-complete{margin-top:20px;border-top:1px solid var(--sfb-line);padding-top:18px}.sfb-complete dl{display:grid;grid-template-columns:150px minmax(0,1fr);font-size:12px;gap:7px 16px;margin:15px 0}.sfb-complete dt{color:var(--sfb-muted)}.sfb-complete dd{margin:0;overflow-wrap:anywhere}.sfb-download{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px 15px;padding:14px;background:#eef1f2;font-size:12px}.sfb-download code{grid-column:1/-1}.sfb-empty{padding:20px 0;color:var(--sfb-muted);font-size:13px}\n@media(max-width:850px){.sfb-workspace{grid-template-columns:1fr}.sfb-workspace aside{border-right:0;border-bottom:1px solid var(--sfb-line);padding:0 0 20px}.sfb-transfer-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.sfb-pages{justify-content:flex-start}}\n@media(max-width:520px){.sfb-panel{padding:16px}.sfb-heading{gap:12px;flex-wrap:wrap}.sfb-heading h3{font-size:21px}.sfb-heading button{font-size:12px}.sfb-form-row,.sfb-chosen label{grid-template-columns:1fr}.sfb-form-row{gap:10px}.sfb-transfer-list{grid-template-columns:1fr}.sfb-actions{flex-direction:column}.sfb-actions button{width:100%;text-align:left}.sfb-complete dl{grid-template-columns:1fr;gap:3px}.sfb-complete dd{margin-bottom:8px}.sfb-download{grid-template-columns:1fr}.sfb-download code{grid-column:auto}.sfb-case{gap:5px}.sfb-panel table{min-width:690px}}\n"
