      "content": "{\n  \"schema\": \"stellar-forge.merchant-distribution-contribution.v1\",\n  \"id\": \"merchant-commercial\",\n  \"description\": \"Complete merchant quotation, recorded usage revisions, accepted implementation, selected tariff pricing and customer workspace handover\",\n  \"components\": [\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console\",\n    \"stellar/scf-starforge-20261009/sf97-merchant-revenue-ops\"\n  ],\n  \"supportFiles\": [\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console/case-commercial-implementation.mjs\",\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console/COMMERCIAL_IMPLEMENTATION.md\",\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/TARIFFS.md\",\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-client.d.mts\",\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/PERFORMANCE.md\",\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/performance-client.d.mts\"\n  ],\n  \"commands\": {\n    \"merchant-commercial\": \"stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial-cli.mjs\"\n  },\n  \"commandDescriptions\": {\n    \"merchant-commercial\": \"Prepare quotations, compare recorded usage, revise explicit monthly pricing, adopt accepted implementation and deliver complete editable cases\"\n  },\n  \"exports\": {\n    \"./merchant/commercial\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial-quote.mjs\",\n    \"./merchant/case-commercial\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/case-commercial.mjs\",\n    \"./merchant/commercial-pricing\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial-pricing.mjs\",\n    \"./merchant/commercial-receiving\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/receiving.mjs\",\n    \"./merchant/commercial-receiving-operator\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/operator.mjs\",\n    \"./merchant/commercial-implementation\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/case-commercial-implementation.mjs\",\n    \"./merchant/commercial-tariff-source\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-source.mjs\",\n    \"./merchant/commercial-tariff-receiving\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-receiving.mjs\",\n    \"./merchant/commercial-tariff-operator\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-controller.mjs\",\n    \"./merchant/commercial-tariff-client\": {\n      \"types\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-client.d.mts\",\n      \"import\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-client.mjs\",\n      \"default\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-client.mjs\"\n    },\n    \"./merchant/commercial-tariff-desk\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-desk.mjs\",\n    \"./merchant/commercial-performance-source\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/tariff-performance.mjs\",\n    \"./merchant/commercial-performance-client\": {\n      \"types\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/performance-client.d.mts\",\n      \"import\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/performance-client.mjs\",\n      \"default\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/performance-client.mjs\"\n    },\n    \"./merchant/commercial-performance-desk\": \"./source/stellar/scf-starforge-20261009/sf74-merchant-support-console/commercial/performance-desk.mjs\"\n  }\n}\n"
