      "content": "{\n  \"schema\": \"stellar-forge.merchant-distribution-contribution.v1\",\n  \"id\": \"merchant-performance\",\n  \"description\": \"Recorded usage and service periods against original tariff selections, complete portable performance source and native pricing proposals\",\n  \"components\": [\n    \"stellar/scf-starforge-20261009/sf97-merchant-revenue-ops\"\n  ],\n  \"supportFiles\": [\n    \"stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/README.md\",\n    \"stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/client.d.mts\"\n  ],\n  \"commands\": {\n    \"merchant-performance\": \"stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/cli.mjs\"\n  },\n  \"commandDescriptions\": {\n    \"merchant-performance\": \"Review original saved usage against tariff selections, retain service periods and complete performance source, and prepare native pricing proposals\"\n  },\n  \"exports\": {\n    \"./merchant/performance\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/model.mjs\",\n    \"./merchant/performance-source\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/source.mjs\",\n    \"./merchant/performance-workspace\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/workspace.mjs\",\n    \"./merchant/performance-client\": {\n      \"types\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/client.d.mts\",\n      \"import\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/client.mjs\",\n      \"default\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/client.mjs\"\n    },\n    \"./merchant/performance-server\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/server.mjs\",\n    \"./merchant/performance-cli\": \"./source/stellar/scf-starforge-20261009/sf97-merchant-revenue-ops/performance/cli.mjs\"\n  }\n}\n"
