      "content": "{\n  \"schema\": \"stellar-forge.distribution-source-selection.v1\",\n  \"id\": \"merchant-support\",\n  \"title\": \"Merchant Support\",\n  \"description\": \"Original merchant cases, tariff and usage-informed quotations, accepted work, invoices, recurring service calendars, customer payments, Service adjustments, buyer/accountant handover and complete customer receiving.\",\n  \"base\": {\n    \"commands\": [\n      \"installation\",\n      \"runtime-profile\",\n      \"runtime-install\",\n      \"runtime-workspace\",\n      \"runtime-transfer\",\n      \"support-console\",\n      \"support-watch\",\n      \"support\",\n      \"merchant-mcp\",\n      \"merchant-mcp-stdio\",\n      \"merchant-mcp-client-config\",\n      \"revenue-workspace\",\n      \"revenue-report\",\n      \"merchant-accounting\",\n      \"merchant-accounting-workspace\",\n      \"merchant-accounting-adjustments\",\n      \"buyer-expenses\",\n      \"merchant-accounting-pricing\",\n      \"merchant-accounting-recovery\"\n    ],\n    \"exports\": [\n      \"./runtime-profile\",\n      \"./installation\",\n      \"./installation/cli\",\n      \"./installation/product\",\n      \"./installation/runtime\",\n      \"./runtime-install\",\n      \"./runtime-transfer\",\n      \"./runtime-workspace\",\n      \"./runtime-workspace/server\",\n      \"./support\",\n      \"./merchant/incidents\",\n      \"./merchant/incidents/store\",\n      \"./merchant/incidents/operator\",\n      \"./merchant/support-console\",\n      \"./merchant/mcp\",\n      \"./merchant/mcp/catalog\",\n      \"./merchant/mcp/server\",\n      \"./merchant/mcp/stdio\",\n      \"./merchant/mcp/client-config\",\n      \"./merchant/revenue-workspace\",\n      \"./merchant/revenue-model\",\n      \"./merchant/revenue-report\",\n      \"./package.json\",\n      \"./manifest.json\",\n      \"./merchant/accounting\",\n      \"./merchant/accounting-workspace\",\n      \"./merchant/accountant\",\n      \"./merchant/accounting-adjustments\",\n      \"./merchant/accounting-adjustments/operations\",\n      \"./merchant/scenario-planning\",\n      \"./merchant/scenario-workspace\",\n      \"./merchant/repricing\",\n      \"./merchant/quote-prices\",\n      \"./merchant/repricing-source\",\n      \"./merchant/accounting-pricing\"\n    ],\n    \"features\": [\n      \"schema\",\n      \"openapi\",\n      \"mcp\"\n    ],\n    \"applicationProviders\": [],\n    \"merchantProviders\": [],\n    \"browserAssets\": []\n  },\n  \"contributions\": [\n    \"merchant-support\",\n    \"merchant-provider-support\",\n    \"merchant-console\",\n    \"merchant-implementation\",\n    \"merchant-service-operations\",\n    \"merchant-commercial\",\n    \"merchant-support-product\",\n    \"merchant-provider-accounting\",\n    \"merchant-provider-buyer-expenses\",\n    \"accounting-connections\",\n    \"buyer-expenses\",\n    \"merchant-service-adjustments\",\n    \"merchant-pricing\",\n    \"merchant-provider-pricing\",\n    \"merchant-tariffs\",\n    \"merchant-performance\",\n    \"merchant-economics-product\",\n    \"merchant-receivables\",\n    \"merchant-payment-plans\",\n    \"receivables-agent\",\n    \"customer-closing\",\n    \"merchant-service-agreements\"\n  ],\n  \"components\": [\n    \"stellar/scf-starforge-20261009/distribution\",\n    \"stellar/scf-starforge-20261009/sf46-release\",\n    \"stellar/scf-starforge-20261009/sf74-merchant-support-console\",\n    \"stellar/scf_2026/sf49_data_commissioning\",\n    \"stellar/scf-starforge-20261009/sf93-seller-support-bundle\",\n    \"stellar/scf-starforge-20261009/sf97-merchant-revenue-ops\",\n    \"stellar/scf-starforge-20261009/sf77-merchant-workorder\",\n    \"stellar/scf-starforge-20261009/sf70-merchant-intake\",\n    \"stellar-forge/mcp-merchant-operator\",\n    \"products/merchant-support\",\n    \"stellar/scf-starforge-20261009/merchant-settlement-accounting\",\n    \"stellar/scf-starforge-20261009/sf36-spend-governor\",\n    \"stellar/scf-starfo