      "sha256": "c1a95b6d703a1bf3f222d27f7c62c6038841f8dfbb4b06e0f56e93b03ace3a0d",
      "content": "// MIT. Project the installed original SF101 API-pass export into customer usage.\nconst SCHEMA='stellar-forge.sf101.api-pass-export.v1';\nconst HEX=/^[a-f0-9]{64}$/;\nconst need=(ok,code,message)=>{if(!ok)throw Object.assign(new Error(message),{code,status:400});};\nconst object=value=>value&&typeof value==='object'&&!Array.isArray(value);\nconst count=(value,name,positive=false)=>{\n  need(Number.isSafeInteger(value)&&value>=0&&(!positive||value>0),'INVALID_NATIVE_USAGE_INTEGER','Check the original '+name+'.');return value;\n};\nconst digest=(value,name)=>{need(typeof value==='string'&&HEX.test(value),'INVALID_NATIVE_USAGE_DIGEST','Check the original '+name+'.');return value;};\nconst text=(value,name,max=2048)=>{\n  need(typeof value==='string'&&value.length>0&&value.length<=max&&!/[\\u0000-\\u0008\\u000b\\u000c\\u000e-\\u001f\\u007f]/.test(value),\n    'INVALID_NATIVE_USAGE_FIELD','Check the original '+name+'.');return value;\n};\nconst time=(value,name)=>{text(value,name,80);need(Number.isFinite(Date.parse(value)),'INVALID_NATIVE_USAGE_TIME','Check the original '+name+'.');return value;};\nconst statuses=new Set(['IN_FLIGHT','RECOVERY_REQUIRED','COMPLETED','CONSUMED','RELEASED']);\nexport function projectApiPassExport(value){\n  need(object(value)&&value.schema===SCHEMA&&object(value.pass)&&Array.isArray(value.calls)&&value.calls.length<=20000,\n    'INVALID_NATIVE_PASS_EXPORT','Import the original complete API-pass export with up to 20,000 calls.');\n  const pass=value.pass,native=pass.native,plan=pass.plan,usage=pass.usage;\n  need(object(native)&&object(plan)&&plan.schema==='stellar-forge.sf101.api-pass.v1'&&object(usage),\n    'INVALID_NATIVE_PASS_EXPORT','The original export must include its pass, native order, purchased plan and durable usage.');\n  need(pass.orderRef===native.orderRef,'NATIVE_PASS_ORDER_CHANGED','The exported pass differs from its original native order.');\n  const planSha256=digest(pass.planSha256,'plan digest'),manifestSha256=digest(pass.manifestSha256,'purchased manifest digest');\n  need(manifestSha256===native.fileSha256,'NATIVE_PASS_MANIFEST_CHANGED','The API pass differs from the original purchased manifest.');\n  need(object(value.snapshot)&&Array.isArray(value.actions),'NATIVE_CAPTURE_REQUIRED','Import the original complete API-pass snapshot.');\n  const createdAt=value.snapshot.capturedAt,revision=digest(value.snapshot.stateSha256,'durable snapshot identity');\n  need(count(value.snapshot.callCount,'snapshot call count')===value.calls.length&&count(value.snapshot.actionCount,'snapshot action count')===value.actions.length,\n    'INCOMPLETE_NATIVE_PASS_EXPORT','The captured call and operation counts must match the complete original export.');\n  need(typeof createdAt==='string','NATIVE_CAPTURE_TIME_REQUIRED','Export the original API pass with its actual capture timestamp.');\n  time(createdAt,'capture timestamp');\n  need((typeof revision==='string'&&revision.length>0&&revision.length<=160)||(Number.isSafeInteger(revision)&&revision>=0),\n    'NATIVE_CAPTURE_REVISION_REQUIRED','Export the original API pass with its immutable snapshot revision.');\n  \n  need(Array.isArray(plan.routes)&&plan.routes.length>0,'NATIVE_PASS_ROUTES_REQUIRED','The purchased plan must retain its original routes.');\n  const routes=new Map();\n  for(const route of plan.routes){\n    need(object(route),'INVALID_NATIVE_PASS_ROUTE','Check the original purchased route.');\n    const id=text(route.id,'route ID',160);\n    need(!routes.has(id),'DUPLICATE_NATIVE_PASS_ROUTE','The purchased plan repeats a route ID.');\n    routes.set(id,{id,method:text(route.method,'route method',10),path:text(route.path,'route path'),units:count(route.units,'route units',true)});\n  }\n  const seen=new Set(),totals={consumedUnits:0n,reservedUnits:0n,completedCalls:0,consumedCallsWithoutResult:0,reservedCalls:0,releasedCalls:0};\n  const calls=value.calls.map(call=>{\n    need(object(call)&&call.orderRef===pass.orderRef,'NATIVE_CALL_ORDER_CHANGED','A call is bound to a different original order.');\n    const requestId=text(call.requestId,'request ID',160);need(!seen.has(requestId),'DUPLICATE_NATIVE_CALL','The original call export repeats a request ID.');seen.add(requestId);\n    const route=routes.get(call.routeId),units=count(call.units,'call units',true);\n    need(route&&call.method===route.method&&call.path===route.path&&units===route.units,\n      'NATIVE_CALL_PLAN_CHANGED','An original call differs from its immutable purchased route or unit price.');\n    need(statuses.has(call.storedStatus)&&statuses.has(call.status),'INVALID_NATIVE_CALL_STATUS','Check the original durable call status.');\n    need(call.status===call.storedStatus||(call.storedStatus==='IN_FLIGHT'&&call.status==='RECOVERY_REQUIRED'),\n      'NATIVE_CALL_STATUS_CHANGED','The displayed call outcome differs from its durable status.');\n    if(['IN_FLIGHT','RECOVERY_REQUIRED'].includes(call.storedStatus)){totals.reservedUnits+=BigInt(units);totals.reservedCalls++;}\n    else if(call.storedStatus==='COMPLETED'){totals.consumedUnits+=BigInt(units);totals.completedCalls++;}\n    else if(call.storedStatus==='CONSUMED'){totals.consumedUnits+=BigInt(units);totals.consumedCallsWithoutResult++;}\n    else totals.releasedCalls++;\n    let result=null;\n    if(call.result!==null&&call.result!==undefined){\n      need(object(call.result)&&Number.isInteger(call.result.status)&&call.result.status>=100&&call.result.status<=599,\n        'INVALID_NATIVE_CALL_RESULT','Check the original retained response metadata.');\n      result={status:call.result.status,contentType:text(call.result.contentType,'response content type',300),\n        sha256:digest(call.result.sha256,'response digest'),bytes:count(call.result.bytes,'response bytes')};\n    }\n    return {requestId,routeId:call.routeId,method:call.method,path:call.path,requestSha256:digest(call.requestSha256,'request digest'),\n      units:String(units),consumedUnits:['COMPLETED','CONSUMED'].includes(call.storedStatus)?String(units):'0',\n      reservedUnits:['IN_FLIGHT','RECOVERY_REQUIRED'].includes(call.storedStatus)?String(units):'0',status:call.status,storedStatus:call.storedStatus,revision:count(call.revision,'call revision'),\n      startedAt:time(call.startedAt,'call start'),deadlineAt:time(call.deadlineAt,'call deadline'),updatedAt:time(call.updatedAt,'call update'),\n      errorCode:call.errorCode===null||call.errorCode===undefined?null:text(call.errorCode,'call outcome code',200),result};\n  }).sort((a,b)=>a.startedAt.localeCompare(b.startedAt)||a.requestId.localeCompare(b.requestId));\n  const allowance=count(usage.allowanceUnits,'allowance units',true),consumed=count(usage.consumedUnits,'consumed units'),\n    reserved=count(usage.reservedUnits,'reserved units'),available=count(usage.availableUnits,'available units');\n  need(allowance===count(plan.allowanceUnits,'purchased plan allowance',true),'NATIVE_ALLOWANCE_CHANGED','The durable allowance differs from its purchased plan.');\n  need(totals.consumedUnits===BigInt(consumed)&&totals.reservedUnits===BigInt(reserved)&&BigInt(consumed)+BigInt(reserved)+BigInt(available)===BigInt(allowance),\n    'INCOMPLETE_NATIVE_CALL_EXPORT','The complete original call history must account for every consumed and reserved unit.');\n  for(const name of ['completedCalls','consumedCallsWithoutResult','reservedCalls','releasedCalls']){\n    need(totals[name]===count(usage[name],name),'INCOMPLETE_NATIVE_CALL_EXPORT','The complete original call history must match its durable call counts.');\n  }\n  need(value.nextAfter===undefined||value.nextAfter===null,'INCOMPLETE_NATIVE_CALL_EXPORT','Export all remaining native call pages before importing customer usage.');\n  return {usage:{schema:'stellar-forge.sf101.service-usage-export.v1',createdAt,revision,orders:[{\n    orderRef:native.orderRef,eventId:native.eventId??null,routeId:native.routeId,method:native.method,network:native.network,\n    amountAtomic:native.amountAtomic,assetDigest:native.assetDigest,recipientDigest:native.recipientDigest??null,entitledAt:native.entitledAt??null,\n    planId:planSha256,planLabel:plan.title,planRevision:manifestSha256,\n    unitsPurchased:String(allowance),unitsUsed:String(consumed),unitsReserved:String(reserved),unitsRemaining:String(available)\n  }]},extras:{planSha256,manifestSha256,callsComplete:true,calls}};\n}\n"
    },
    {
      "path": "stellar/scf-starforge-20261009/merchant-settlement-accounting/customer-statements/period-usage.mjs",
      "gitBlob": "dd43d0095ca63d8eb72921333b7a86affa53cf3e",
      "bytes": 13887,
      "sha256": "e8e570c253d25547cd549fb7e630d1733e2aa70aa5b645f758574c3e4a3c6bdf",
      "content": "// MIT. Compare complete original API-pass snapshots without changing their allowance.\nexport const SERVICE_PERIOD_SCHEMA='stellar-forge.merchant-service-period.v1';\nconst NATIVE='stellar-forge.sf101.api-pass-export.v1';\nconst RESERVED=new Set(['IN_FLIGHT','RECOVERY_REQUIRED']);\nconst USED=new Set(['COMPLETED','CONSUMED']);\nconst TRANSITIONS={\n  IN_FLIGHT:new Set(['IN_FLIGHT','RECOVERY_REQUIRED','COMPLETED','CONSUMED','RELEASED']),\n  RECOVERY_REQUIRED:new Set(['RECOVERY_REQUIRED','COMPLETED','CONSUMED','RELEASED']),\n  CONSUMED:new Set(['CONSUMED','COMPLETED']),\n  COMPLETED:new Set(['COMPLETED']),\n  RELEASED:new Set(['RELEASED'])\n};\nconst need=(ok,code,message)=>{if(!ok)throw Object.assign(new Error(message),{code,status:409});};\nconst equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);\nconst copy=value=>JSON.parse(JSON.stringify(value));\nconst balance=order=>Object.fromEntries(['unitsPurchased','unitsUsed','unitsReserved','unitsRemaining'].map(key=>[key,order[key]]));\nconst durable=call=>Object.fromEntries(['requestId','routeId','method','path','requestSha256','units','storedStatus','revision','startedAt','deadlineAt','updatedAt','errorCode','result'].map(key=>[key,call[key]]));\nconst source=(usage,record)=>({\n  id:record?.id??null,sha256:record?.sha256??null,sourceSchema:usage.sourceSchema,\n  createdAt:usage.createdAt,revision:usage.revision\n});\nconst amount=(call,kind)=>call&&(kind==='used'?USED:RESERVED).has(call.storedStatus)?BigInt(call.units):0n;\nfunction completeNative(usage,name){\n  need(usage?.sourceSchema===NATIVE&&Array.isArray(usage.orders)&&usage.orders.length===1&&\n    usage.orders[0].callsComplete===true&&Array.isArray(usage.orders[0].calls),\n    'COMPLETE_NATIVE_PERIOD_SOURCE_REQUIRED','Choose the complete original API-pass export for the '+name+' snapshot.');\n  return usage.orders[0];\n}\nfunction callIndex(order){\n  const result=new Map();\n  for(const call of order.calls){\n    need(!result.has(call.requestId),'DUPLICATE_PERIOD_CALL','The original period source repeats a request ID.');\n    result.set(call.requestId,call);\n  }\n  return result;\n}\nfunction routeCounters(call){\n  return {routeId:call.routeId,method:call.method,path:call.path,routeUnits:call.units,\n    openingCalls:0,closingCalls:0,newCalls:0,changedCalls:0,resultRecoveries:0,\n    openingUsedUnits:0n,closingUsedUnits:0n,openingReservedUnits:0n,closingReservedUnits:0n,\n    admittedUnits:0n,consumedUnits:0n,releasedUnits:0n};\n}\nexport function compileServicePeriod({opening,closing,openingSource=null,closingSource=null}){\n  const first=completeNative(opening,'opening'),last=completeNative(closing,'closing');\n  const from=Date.parse(opening.createdAt),until=Date.parse(closing.createdAt);\n  need(Number.isFinite(from)&&Number.isFinite(until)&&until>from,'SERVICE_PERIOD_ORDER',\n    'Choose a closing snapshot captured after the opening snapshot.');\n  const identity=['orderRef','eventId','routeId','method','network','amountAtomic','assetDigest','recipientDigest',\n    'entitledAt','planId','planRevision','planSha256','manifestSha256','unitsPurchased'];\n  need(identity.every(key=>first[key]===last[key]),'SERVICE_PERIOD_IDENTITY_CHANGED',\n    'Both snapshots must describe the same original order, entitlement, purchased plan and allowance.');\n  need(typeof first.eventId==='string'&&typeof first.entitledAt==='string','SERVICE_PERIOD_ENTITLEMENT_REQUIRED',\n    'Choose snapshots of the original entitled API pass.');\n  const before=callIndex(first),after=callIndex(last),routes=new Map(),calls=[];\n  const counters={openingCalls:before.size,closingCalls:after.size,newCalls:0,changedCalls:0,unchangedCalls:0,\n    carriedReservations:0,resultRecoveries:0,admittedUnits:0n,consumedUnits:0n,releasedUnits:0n};\n  for(const id of before.keys())need(after.has(id),'SERVICE_PERIOD_CALL_MISSING',\n    'The closing snapshot is missing an original opening call. Choose the complete continuation of that pass.');\n  for(const [id,next] of after){\n    const prior=before.get(id)??null;\n    let changed=!prior;\n    if(prior){\n      for(const key of ['requestId','routeId','method','path','requestSha256','units','startedAt','deadlineAt']){\n        need(prior[key]===next[key],'SERVICE_PERIOD_CALL_IDENTITY_CHANGED',\n          'An original request changed its purchased route, unit price, request bytes or admission identity.');\n      }\n      need(TRANSITIONS[prior.storedStatus]?.has(next.storedStatus),'SERVICE_PERIOD_STATUS_REVERSED',\n        'The closing call state does not continue the original native state.');\n      need(next.revision>=prior.revision,'SERVICE_PERIOD_REVISION_REVERSED',\n        'The closing source contains an earlier call revision.');\n      changed=!equal(durable(prior),durable(next));\n      need(!changed||next.revision>prior.revision,'SERVICE_PERIOD_REVISION_CHANGED',\n        'A durable call changed without its original revision advancing.');\n      if(['COMPLETED','RELEASED'].includes(prior.storedStatus)){\n        need(!changed,'SERVICE_PERIOD_TERMINAL_CHANGED','A completed or released original call was rewritten.');\n      }\n    }\n    const admitted=prior?0n:BigInt(next.units);\n    const consumed=amount(next,'used')-amount(prior,'used');\n    const released=next.storedStatus==='RELEASED'&&prior?.storedStatus!=='RELEASED'?BigInt(next.units):0n;\n    const recovered=prior?.storedStatus==='CONSUMED'&&next.storedStatus==='COMPLETED';\n    need(consumed>=0n,'SERVICE_PERIOD_CONSUMPTION_REVERSED','Consumed native allowance cannot disappear from a later snapshot.');\n    if(recovered)need(next.result!==null,'SERVICE_PERIOD_RESULT_REQUIRED','The recovered native response metadata is missing.');\n    const route=routes.get(next.routeId)??routeCounters(next);\n    need(route.method===next.method&&route.path===next.path&&route.routeUnits===next.units,'SERVICE_PERIOD_ROUTE_CHANGED',\n      'The period source differs from its immutable purchased route.');\n    route.openingCalls+=prior?1:0;route.closingCalls++;\n    for(const [key,value] of Object.entries({admittedUnits:admitted,consumedUnits:consumed,releasedUnits:released})){\n      counters[key]+=value;route[key]+=value;\n    }\n    route.openingUsedUnits+=amount(prior,'used');route.closingUsedUnits+=amount(next,'used');\n    route.openingReservedUnits+=amount(prior,'reserved');route.closingReservedUnits+=amount(next,'reserved');\n    if(!prior){counters.newCalls++;route.newCalls++;}\n    else if(changed){counters.changedCalls++;route.changedCalls++;}\n    else counters.unchangedCalls++;\n    if(recovered){counters.resultRecoveries++;route.resultRecoveries++;}\n    if(prior&&RESERVED.has(prior.storedStatus)&&RESERVED.has(next.storedStatus))counters.carriedReservations++;\n    routes.set(next.routeId,route);\n    if(changed||RESERVED.has(next.storedStatus)){\n      calls.push({requestId:id,routeId:next.routeId,method:next.method,path:next.path,units:next.units,\n        kind:!prior?'NEW_CALL':recovered?'RESULT_RECOVERED':changed?'DURABLE_CHANGE':'CARRIED_RESERVATION',\n        opening:prior?copy(prior):null,closing:copy(next),admittedUnits:admitted.toString(),\n        consumedUnits:consumed.toString(),releasedUnits:released.toString(),\n        reservedDeltaUnits:(amount(next,'reserved')-amount(prior,'reserved')).toString(),\n        availableDeltaUnits:(released-admitted).toString(),resultRecovered:recovered});\n    }\n  }\n  need(opening.revision!==closing.revision||(counters.newCalls===0&&counters.changedCalls===0),\n    'SERVICE_PERIOD_SNAPSHOT_CHANGED','Different durable calls cannot share the same original snapshot identity.');\n  const usedDelta=BigInt(last.unitsUsed)-BigInt(first.unitsUsed);\n  const reservedDelta=BigInt(last.unitsReserved)-BigInt(first.unitsReserved);\n  const availableDelta=BigInt(last.unitsRemaining)-BigInt(first.unitsRemaining);\n  need(counters.consumedUnits===usedDelta&&counters.admittedUnits-counters.consumedUnits-counters.releasedUnits===reservedDelta&&\n    counters.releasedUnits-counters.admittedUnits===availableDelta,'SERVICE_PERIOD_BALANCE_CHANGED',\n    'The complete original call changes do not conserve the opening and closing allowance.');\n  const stringify=row=>Object.fromEntries(Object.entries(row).map(([key,value])=>[key,typeof value==='bigint'?value.toString():value]));\n  calls.sort((a,b)=>a.closing.updatedAt.localeCompare(b.closing.updatedAt)||a.requestId.localeCompare(b.requestId));\n  return {schema:SERVICE_PERIOD_SCHEMA,orderRef:last.orderRef,eventId:last.eventId,planId:last.planId,\n    planSha256:last.planSha256,manifestSha256:last.manifestSha256,planLabel:last.planLabel,\n    from:opening.createdAt,until:closing.createdAt,timeBasis:'COMPLETE_NATIVE_SNAPSHOT_COMPARISON',\n    openingSource:source(opening,openingSource),closingSource:source(closing,closingSource),\n    opening:balance(first),closing:balance(last),\n    totals:{...stringify(counters),reservedDeltaUnits:reservedDelta.toString(),availableDeltaUnits:availableDelta.toString()},\n    routes:[...routes.values()].map(stringify).sort((a,b)=>a.routeId.localeCompare(b.routeId)),calls};\n}\nconst csvCell=value=>{\n  let text=value===null||value===undefined?'':String(value);\n  if((/^\\s*[=+\\-@]/.test(text)&&!/^-[0-9]+$/.test(text))||/^[\\t\\r\\n]/.test(text))text=\"'\"+text;\n  return '\"'+text.replaceAll('\"','\"\"')+'\"';\n};\nconst csv=rows=>rows.map(row=>row.map(csvCell).join(',')).join('\\r\\n')+'\\r\\n';\nexport function renderServicePeriodCsv(statement){\n  const p=statement.servicePeriod;\n  const headers=['statementNumber','customerReference','orderRef','periodFrom','periodUntil','openingSourceSha256','closingSourceSha256',\n    'requestId','routeId','method','path','kind','routeUnits','openingStatus','closingStatus','openingRevision','closingRevision',\n    'admittedUnits','consumedUnits','releasedUnits','reservedDeltaUnits','availableDeltaUnits','resultRecovered',\n    'startedAt','openingUpdatedAt','closingUpdatedAt','requestSha256','responseStatus','responseSha256','responseBytes'];\n  return csv([headers,...(p?.calls??[]).map(c=>[\n    statement.number??'',statement.customer.reference,p.orderRef,p.from,p.until,p.openingSource.sha256,p.closingSource.sha256,\n    c.requestId,c.routeId,c.method,c.path,c.kind,c.units,c.opening?.storedStatus,c.closing.storedStatus,c.opening?.revision,c.closing.revision,\n    c.admittedUnits,c.consumedUnits,c.releasedUnits,c.reservedDeltaUnits,c.availableDeltaUnits,c.resultRecovered,\n    c.closing.startedAt,c.opening?.updatedAt,c.closing.updatedAt,c.closing.requestSha256,c.closing.result?.status,c.closing.result?.sha256,c.closing.result?.bytes\n  ])]);\n}\nexport function renderServicePeriodSummaryCsv(statement){\n  const p=statement.servicePeriod;\n  const headers=['statementNumber','customerReference','orderRef','periodFrom','periodUntil','routeId','method','path','routeUnits',\n    'openingCalls','closingCalls','newCalls','changedCalls','resultRecoveries','openingUsedUnits','closingUsedUnits',\n    'openingReservedUnits','closingReservedUnits','admittedUnits','consumedUnits','releasedUnits'];\n  return csv([headers,...(p?.routes??[]).map(r=>[\n    statement.number??'',statement.customer.reference,p.orderRef,p.from,p.until,\n    ...headers.slice(5).map(key=>r[key])\n  ])]);\n}\nconst escape=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('\"','&quot;').replaceAll(\"'\",\"&#39;\");\nexport function renderServicePeriodHtml(period){\n  if(!period)return '';\n  const e=escape;\n  const balanceRows=[['Purchased allowance','unitsPurchased'],['Consumed allowance','unitsUsed'],['Reserved allowance','unitsReserved'],['Available allowance','unitsRemaining']]\n    .map(([title,key])=>'<tr><th>'+title+'</th><td>'+e(period.opening[key])+'</td><td>'+e(period.closing[key])+'</td></tr>').join('');\n  const routeRows=period.routes.map(r=>'<tr><td>'+e(r.routeId)+'<small>'+e(r.method)+' '+e(r.path)+'</small></td><td>'+r.newCalls+'</td><td>'+e(r.admittedUnits)+'</td><td>'+e(r.consumedUnits)+'</td><td>'+e(r.releasedUnits)+'</td><td>'+e(r.closingReservedUnits)+'</td></tr>').join('');\n  const callRows=period.calls.map(c=>'<tr><td><code>'+e(c.requestId)+'</code><small>'+e(c.method)+' '+e(c.path)+'</small></td><td>'+e(c.kind)+'</td><td>'+e(c.opening?.storedStatus??'Not in opening snapshot')+'</td><td>'+e(c.closing.storedStatus)+'</td><td>'+e(c.admittedUnits)+' / '+e(c.consumedUnits)+' / '+e(c.releasedUnits)+'</td><td>'+e(c.closing.updatedAt)+'</td></tr>').join('');\n  return '<section class=\"summary\"><h2>Service activity between snapshots</h2><p>Order <code>'+e(period.orderRef)+'</code>: '+e(period.from)+' to '+e(period.until)+'.</p>'+\n    '<p>The opening and closing values come from complete original snapshots. Call timestamps remain their native timestamps. Activity includes earlier reserved calls resolved during this interval.</p>'+\n    '<table><thead><tr><th>Allowance in service units</th><th>Opening</th><th>Closing</th></tr></thead><tbody>'+balanceRows+'</tbody></table>'+\n    '<p>'+period.totals.newCalls+' new calls; '+e(period.totals.admittedUnits)+' units admitted; '+e(period.totals.consumedUnits)+' units consumed; '+e(period.totals.releasedUnits)+' units released. '+period.totals.resultRecoveries+' original results recovered. '+period.totals.carriedReservations+' opening calls remain reserved.</p>'+\n    '<table><thead><tr><th>Purchased route</th><th>New calls</th><th>Admitted</th><th>Consumed</th><th>Released</th><th>Closing reserved</th></tr></thead><tbody>'+routeRows+'</tbody></table>'+\n    '<h3>Activity and carried reservations</h3><table><thead><tr><th>Request / route</th><th>Change</th><th>Opening outcome</th><th>Closing outcome</th><th>Admitted / consumed / released</th><th>Native update</th></tr></thead><tbody>'+callRows+'</tbody></table>'+\n    '<p>'+period.totals.unchangedCalls+' original calls retain their earlier durable state. Complete source projections and the closing call history accompany the retained document.</p></section>';\n}\n"
    },
    {
      "path": "stellar/scf-starforge-20261009/merchant-settlement-accounting/customer-statements/public/app.mjs",
      "gitBlob": "fd4a6f90ef82343d43ca51478278d6e613fc00c1",
      "bytes": 32981,
      "sha256": "4236d4c64761b568882e44b609bd81f5e52fad191786ec272974f353990a1705",
      "content": "// MIT. Customer statement operator desk. All displayed values are inserted as text.\nconst $=id=>document.getElementById(id);\nconst API='/api/customer-statements';\nlet state=null,working=false,preview=null,currentDocument=null,pendingRetention=null,bindingsOffset=0,bindingsTotal=0,registerOffset=0,registerTotal=0;\nconst knownStatements=new Map();\nconst create=(tag,text,className)=>{\n  const element=document.createElement(tag);if(text!==undefined&&text!==null)element.textContent=String(text);if(className)element.className=className;return element;\n};\nfunction status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}\nfunction actor(){const value=$('operator').value.trim();if(!value)throw new Error('Enter the operator name before saving workspace changes.');try{localStorage.setItem('merchant-customer-statement-operator',value);}catch{}return value;}\nfunction readable(value){return String(value??'Unrecorded').replaceAll('_',' ').toLowerCase();}\nfunction setOptions(element,rows,emptyLabel,selected=element.value){\n  element.replaceChildren();\n  if(emptyLabel!==null){const option=create('option',emptyLabel);option.value='';element.append(option);}\n  for(const row of rows){const option=create('option',row.label);option.value=row.value;element.append(option);}\n  if([...element.options].some(option=>option.value===selected))element.value=selected;\n}\nfunction availability(){\n  document.querySelectorAll('button').forEach(button=>button.disabled=working||button.dataset.rangeDisabled==='true');\n  $('assign-button').disabled=working||!$('customer-picker').value;\n  $('retain').disabled=working||(!preview&&!pendingRetention);\n  $('bindings-prev').disabled=working||bindingsOffset===0;\n  $('bindings-next').disabled=working||bindingsOffset+50>=bindingsTotal;\n  $('register-prev').disabled=working||registerOffset===0;\n  $('register-next').disabled=working||registerOffset+50>=registerTotal;\n  $('correct-document').disabled=working||currentDocument?.statement.status!=='RETAINED';\n  document.body.classList.toggle('working',working);\n  document.body.setAttribute('aria-busy',String(working));\n}\nasync function run(action){\n  if(working)return;working=true;availability();\n  try{await action();}\n  catch(error){status(error.message||'The operation failed.',true);}\n  finally{working=false;availability();}\n}\nasync function request(path='',value){\n  const response=await fetch(API+path,{method:value===undefined?'GET':'POST',cache:'no-store',\n    headers:value===undefined?{}:{'Content-Type':'application/json','X-Workspace-Request':'1'},...(value===undefined?{}:{body:JSON.stringify(value)})});\n  let result;\n  try{result=await response.json();}catch{throw Object.assign(new Error('The workspace response could not be read. Refresh the register to recover the current document state.'),{uncertain:true});}\n  if(!response.ok)throw Object.assign(new Error(result.error?.message??result.message??'The workspace operation failed.'),{code:typeof result.error==='string'?result.error:result.error?.code,status:response.status});\n  return result;\n}\nfunction clearPreview(){\n  preview=null;$('preview-panel').hidden=true;\n  if(!pendingRetention){$('retain').textContent='Retain statement';$('retention-note').textContent='Review the original purchases, usage and adjustments before retaining this document.';}\n}\nfunction takeState(value){\n  state=value;$('revision').textContent='Workspace revision '+state.revision;\n  for(const row of state.statements)knownStatements.set(row.id,row);\n  const chosen=$('customer-picker').value;\n  const customers=state.customers.map(row=>({value:row.id,label:row.reference+' · '+row.name}));\n  setOptions($('customer-picker'),customers,'New customer',chosen);\n  setOptions($('statement-customer'),customers,'Choose customer');\n  setOptions($('register-customer'),customers,'All customers');\n  setOptions($('statement-run'),state.runs.map(row=>({value:row.id,label:(row.name??row.id)+' · '+(row.completedAt??row.createdAt??'')})),'Choose completed run');\n  setOptions($('statement-usage'),state.usageImports.map(row=>({value:row.id,label:row.name+' · '+row.sourceCreatedAt})),'Purchases only');\n  setOptions($('statement-usage-opening'),state.usageImports.filter(row=>row.sourceSchema==='stellar-forge.sf101.api-pass-export.v1')\n    .map(row=>({value:row.id,label:row.name+' · '+row.sourceCreatedAt})),'Choose opening snapshot');\n  updatePeriodMode();updateCorrections();\n  $('metrics').replaceChildren();\n  for(const [name,value] of [['Customers',state.customers.length],['Assigned orders',state.bindingCount],['Retained documents',state.statementCount],['Completed accounting runs',state.runs.length]]){\n    const card=create('div',null,'metric');card.append(create('span',name),create('strong',value));$('metrics').append(card);\n  }\n  const latest=state.usageImports[0];$('usage-summary').replaceChildren();\n  if(latest){$('usage-summary').append(create('p',latest.name),create('small',latest.orderCount+' original orders · Captured '+latest.sourceCreatedAt),\n    create('small','Service revision '+latest.sourceRevision+' · '+state.usageImportCount+' retained captures'));}\n  else $('usage-summary').append(create('p','No service usage captures imported.'));\n  if(preview&&preview.revision!==state.revision&&!pendingRetention)clearPreview();\n}\nfunction fillCustomer(id){\n  const row=state.customers.find(row=>row.id===id),form=$('customer-form');\n  for(const key of ['reference','name','email','address','note'])form.elements[key].value=row?.[key]??'';\n  form.dataset.id=row?.id??'';form.dataset.version=row?.version??'';\n  if(row)$('statement-customer').value=row.id;\n  updateCorrections();availability();\n}\nfunction updateCorrections(){\n  const customerId=$('statement-customer').value;\n  setOptions($('statement-replaces'),[...knownStatements.values()].filter(row=>row.status==='RETAINED'&&row.customerId===customerId)\n    .sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(row=>({value:row.id,label:row.number+' · '+row.createdAt})),'New statement');\n}\nasync function loadBindings(){\n  const customerId=$('customer-picker').value;\n  const body=$('binding-rows');body.replaceChildren();\n  if(!customerId){bindingsOffset=0;bindingsTotal=0;$('binding-count').textContent='';$('bindings-page').textContent='Choose customer';return;}\n  const page=await request('/bindings?'+new URLSearchParams({customerId,offset:bindingsOffset,limit:50}));\n  bindingsTotal=page.total;\n  for(const row of page.items){const tr=create('tr');tr.append(create('td',row.orderRef,'mono'),create('td',row.label||'—'),create('td',row.version));body.append(tr);}\n  if(!page.items.length){const td=create('td','No original orders assigned.','empty');td.colSpan=3;const tr=create('tr');tr.append(td);body.append(tr);}\n  $('binding-count').textContent=page.total+' orders';\n  $('bindings-page').textContent=page.total?String(bindingsOffset+1)+'–'+Math.min(bindingsOffset+50,page.total)+' of '+page.total:'0 orders';\n}\nasync function loadRegister(){\n  const query={offset:registerOffset,limit:50};\n  if($('register-customer').value)query.customerId=$('register-customer').value;\n  if($('register-status').value)query.status=$('register-status').value;\n  const page=await request('/statements?'+new URLSearchParams(query));registerTotal=page.total;\n  const body=$('register-rows');body.replaceChildren();\n  for(const row of page.items){\n    knownStatements.set(row.id,row);const tr=create('tr'),number=create('td',row.number),person=create('td',row.customerName);\n    if(row.servicePeriod)number.append(create('small','Service '+row.servicePeriod.from+' to '+row.servicePeriod.until));\n    person.append(create('small',row.customerReference));const stateCell=create('td');stateCell.append(create('span',row.status,'badge'));\n    const open=create('button','Open');open.type='button';open.addEventListener('click',()=>run(()=>openDocument(row.id)));const action=create('td');action.append(open);\n    tr.append(number,person,create('td',row.createdAt),create('td',row.orderCount,'numeric'),stateCell,action);body.append(tr);\n  }\n  if(!page.items.length){const td=create('td','No retained statements match this selection.','empty');td.colSpan=6;const tr=create('tr');tr.append(td);body.append(tr);}\n  $('register-page').textContent=page.total?String(registerOffset+1)+'–'+Math.min(registerOffset+50,page.total)+' of '+page.total:'0 documents';\n  updateCorrections();\n}\nasync function refresh(){\n  takeState(await request());await loadBindings();await loadRegister();\n  status('Workspace revision '+state.revision+' loaded.');\n}\nfunction addDefinition(dl,name,value,mono=false){dl.append(create('dt',name),create('dd',value,mono?'mono':null));}\nfunction assetsTable(documentValue){\n  const table=create('table'),head=create('thead'),tr=create('tr');\n  for(const title of ['Network / asset / recipient','Orders','Original atomic amount','Officially matched','Verified refunds','Pending refunds'])tr.append(create('th',title));\n  head.append(tr);table.append(head);const body=create('tbody');\n  for(const row of documentValue.totals.byAsset){\n    const tr=create('tr'),asset=create('td',row.network);\n    asset.append(create('small','Asset '+row.assetDigest,'mono'),create('small','Recipient '+(row.recipientDigest??'unrecorded'),'mono'));tr.append(asset);\n    for(const key of ['orders','reportedAmountAtomic','officialMatchedAmountAtomic','refundedAmountAtomic','pendingRefundAmountAtomic'])tr.append(create('td',row[key],'numeric'));\n    body.append(tr);\n  }\n  table.append(body);const wrap=create('div',null,'table-wrap');wrap.append(table);return wrap;\n}\nconst exclusionNames={\n  ORDER_NOT_IN_SELECTED_REPORT:'Assigned order absent from the selected report or recorded date range.',\n  AMBIGUOUS_ORDER_EVENTS:'Several original events use this assigned order reference.',\n  SERVICE_PAYMENT_IDENTITY_MISMATCH:'The service usage snapshot differs from the original order, event or payment terms.',\n  ORIGINAL_NATIVE_ORDER_REQUIRED:'The original native checkout capture is required for this order.'\n};\nfunction updatePeriodMode(){\n  const active=$('statement-usage-mode').value==='period';\n  $('service-period-fields').hidden=!active;\n  $('statement-usage-opening').disabled=!active;\n  $('statement-usage-opening').required=active;\n  $('statement-usage').required=active;\n  if(!active)$('service-period-preview').hidden=true;\n}\nfunction renderServicePeriod(period,target){\n  const section=create('section',null,'subsection');\n  section.append(create('h3','Service activity between snapshots'),\n    create('p','Order '+period.orderRef+' · '+period.from+' to '+period.until,'mono'),\n    create('p','Complete opening and closing snapshots define this interval. Earlier reserved calls and their later outcomes remain connected.','muted'));\n  const balances=create('table'),balanceHead=create('thead'),bh=create('tr');\n  for(const name of ['Service allowance','Opening','Closing'])bh.append(create('th',name));\n  balanceHead.append(bh);balances.append(balanceHead);const balanceBody=create('tbody');\n  for(const [name,key] of [['Purchased units','unitsPurchased'],['Consumed units','unitsUsed'],['Reserved units','unitsReserved'],['Available units','unitsRemaining']]){\n    const row=create('tr');row.append(create('th',name),create('td',period.opening[key],'numeric'),create('td',period.closing[key],'numeric'));balanceBody.append(row);\n  }\n  balances.append(balanceBody);section.append(balances);\n  const totals=period.totals;\n  section.append(create('p',totals.newCalls+' new calls · '+totals.admittedUnits+' units admitted · '+totals.consumedUnits+' consumed · '+totals.releasedUnits+' released.'),\n    create('p',totals.resultRecoveries+' original results recovered · '+totals.carriedReservations+' opening calls remain reserved.','muted'));\n  const routeTable=create('table'),routeHead=create('thead'),rh=create('tr');\n  for(const name of ['Purchased route','New calls','Admitted','Consumed','Released','Closing reserved'])rh.append(create('th',name));\n  routeHead.append(rh);routeTable.append(routeHead);const routeBody=create('tbody');\n  for(const route of period.routes){\n    const row=create('tr'),name=create('td',route.routeId,'mono');name.append(create('small',route.method+' '+route.path));row.append(name);\n    for(const key of ['newCalls','admittedUnits','consumedUnits','releasedUnits','closingReservedUnits'])row.append(create('td',route[key],'numeric'));\n    routeBody.append(row);\n  }\n  routeTable.append(routeBody);const routes=create('div',null,'table-wrap');routes.append(routeTable);section.append(routes);\n  const activity=create('details');activity.append(create('summary','Activity and carried reservations · '+period.calls.length+' calls'));\n  const table=create('table'),head=create('thead'),tr=create('tr');\n  for(const name of ['Request / route','Change','Opening outcome','Closing outcome','Admitted / consumed / released','Native update'])tr.append(create('th',name));\n  head.append(tr);table.append(head);const body=create('tbody');table.append(body);\n  const wrap=create('div',null,'table-wrap');wrap.append(table);activity.append(wrap);\n  const controls=create('div',null,'pager'),previous=create('button','Previous'),position=create('span'),next=create('button','Next');\n  previous.type=next.type='button';controls.append(previous,position,next);activity.append(controls);\n  let offset=0;\n  const page=()=>{\n    body.replaceChildren();\n    for(const call of period.calls.slice(offset,offset+50)){\n      const row=create('tr'),identity=create('td',call.requestId,'mono');identity.append(create('small',call.method+' '+call.path));\n      row.append(identity,create('td',readable(call.kind)),create('td',call.opening?readable(call.opening.storedStatus):'Not in opening snapshot'),\n        create('td',readable(call.closing.storedStatus)),create('td',call.admittedUnits+' / '+call.consumedUnits+' / '+call.releasedUnits,'numeric'),\n        create('td',call.closing.updatedAt));body.append(row);\n    }\n    position.textContent=period.calls.length?String(offset+1)+'–'+Math.min(offset+50,period.calls.length)+' of '+period.calls.length:'No activity or carried reservations';\n    previous.dataset.rangeDisabled=String(offset===0);next.dataset.rangeDisabled=String(offset+50>=period.calls.length);\n    previous.disabled=working||offset===0;next.disabled=working||offset+50>=period.calls.length;\n  };\n  previous.addEventListener('click',()=>{offset=Math.max(0,offset-50);page();});\n  next.addEventListener('click',()=>{offset+=50;page();});\n  page();section.append(activity,create('p',totals.unchangedCalls+' original calls retain their earlier durable state. Full activity and source projections are included in retained downloads.','muted'));\n  target.append(section);\n}\n\nfunction renderDocument(value,target){\n  target.replaceChildren();\n  const scope=create('p',value.selection.from?'Recorded purchases: '+value.selection.from+' through '+value.selection.until+' (end exclusive).':'All recorded purchases in the selected report.','document-scope');\n  target.append(scope);\n  const counts=create('div',null,'summary-grid');\n  for(const [title,count] of [['Original orders',value.totals.orders],['Orders with usage',value.totals.serviceOrders],['Transfer reconciliation',value.totals.requiringReconciliation],['Assigned orders excluded',value.excluded.length]]){\n    const card=create('div');card.append(create('span',title),create('strong',count));counts.append(card);\n  }\n  target.append(counts,assetsTable(value));\n  const quotes=value.totals.merchantQuotedUsd;\n  target.append(create('p','Known merchant USD quotes: '+quotes.knownTotal+' across '+quotes.knownOrders+' orders. '+quotes.unknownOrders+' orders have no recorded quote.','muted'));\n  if(value.source.usage)target.append(create('p','Closing service allowance balances as of '+value.source.usage.createdAt+' · Service revision '+value.source.usage.revision+'.','inset'));\n  if(value.servicePeriod)renderServicePeriod(value.servicePeriod,target);\n  for(const row of value.items){\n    const article=create('article',null,'purchase'),heading=create('div',null,'purchase-head'),left=create('div');\n    left.append(create('h3',row.label),create('p','Order '+row.orderRef+' · '+row.recordedAt,'mono'));\n    heading.append(left,create('strong',row.amountAtomic+' atomic units'));article.append(heading);\n    const terms=create('dl',null,'key-values');\n    addDefinition(terms,'Network',row.network);addDefinition(terms,'Asset',row.assetDigest,true);\n    addDefinition(terms,row.recipientDigest?'Recorded recipient':row.termsRecipientDigest?'Recipient from selected terms':'Recipient',row.recipientDigest??row.termsRecipientDigest??'Unrecorded',true);\n    addDefinition(terms,'Transfer',readable(row.transfer)+' · '+readable(row.verificationScope));\n    addDefinition(terms,'Delivery',readable(row.delivery));\n    addDefinition(terms,'Merchant USD quote',row.merchantQuoteUsd===null?'Unrecorded':row.merchantQuoteUsd+(row.merchantPriceBasis?' · '+row.merchantPriceBasis:''));\n    addDefinition(terms,'Verified refunds',row.adjustmentSummary.refundedAmountAtomic+' atomic units');\n    addDefinition(terms,'Pending refunds',row.adjustmentSummary.pendingRefundAmountAtomic+' atomic units');\n    addDefinition(terms,'Recorded cancellations',row.adjustmentSummary.cancelledAmountAtomic+' atomic units');\n    if(row.exception)addDefinition(terms,'Reconciliation',readable(row.exception));article.append(terms);\n    if(row.service){\n      const service=row.service;article.append(create('h3',service.planLabel));\n      const units=create('div',null,'usage-units');\n      for(const [title,key] of [['Purchased','unitsPurchased'],['Used','unitsUsed'],['Reserved','unitsReserved'],['Remaining','unitsRemaining']]){\n        const item=create('div');item.append(create('span',title),create('b',service[key]));units.append(item);\n      }\n      article.append(units,create('p','Entitled '+service.entitledAt+' · Plan '+service.planId,'muted'));\n    }else article.append(create('p',row.usageStatus==='NO_USAGE_SNAPSHOT'?'Purchase statement without a selected usage capture.':'This order is absent from the selected service usage capture.','muted'));\n    if(row.service?.callsComplete){\n      const calls=create('details');calls.append(create('summary','Original service call history · '+row.service.calls.length+' calls'));\n      const table=create('table'),head=create('thead'),tr=create('tr');for(const name of ['Request / route','Unit price / consumed / reserved','Durable outcome','Updated at'])tr.append(create('th',name));head.append(tr);table.append(head);\n      const body=create('tbody');\n      for(const call of row.service.calls){const tr=create('tr'),identity=create('td',call.requestId,'mono');identity.append(create('small',call.method+' '+call.path));\n        const outcome=create('td',readable(call.storedStatus));if(call.status!==call.storedStatus)outcome.append(create('small',readable(call.status)));\n        tr.append(identity,create('td',call.units+' / '+call.consumedUnits+' / '+call.reservedUnits,'numeric'),outcome,create('td',call.updatedAt));body.append(tr);}\n      table.append(body);const wrap=create('div',null,'table-wrap');wrap.append(table);calls.append(wrap);article.append(calls);\n    }\n    if(row.adjustments.length){\n      const table=create('table'),head=create('thead'),tr=create('tr');for(const name of ['Adjustment','Status','Atomic amount','Effective at'])tr.append(create('th',name));head.append(tr);table.append(head);\n      const body=create('tbody');\n      for(const adjustment of row.adjustments){const item=create('tr');item.append(create('td',readable(adjustment.kind)),create('td',readable(adjustment.status)),create('td',adjustment.amountAtomic,'numeric'),create('td',adjustment.effectiveAt));body.append(item);}\n      table.append(body);article.append(table);\n    }\n    const details=create('details');details.append(create('summary','Original order and payment identifiers'));const identifiers=create('dl',null,'key-values');\n    addDefinition(identifiers,'Original event',row.eventId,true);addDefinition(identifiers,'Order digest',row.orderReferenceDigest,true);\n    addDefinition(identifiers,'Receipt fingerprint',row.receiptFingerprint,true);addDefinition(identifiers,'Transaction fingerprint',row.transactionFingerprint??'Unrecorded',true);\n    if(row.service)addDefinition(identifiers,'Purchased plan revision',row.service.planRevision,true);\n    details.append(identifiers);article.append(details);target.append(article);\n  }\n  if(value.excluded.length){\n    const section=create('section',null,'subsection');section.append(create('h3','Assigned orders outside this statement'));\n    const table=create('table'),head=create('thead'),tr=create('tr');tr.append(create('th','Original order'),create('th','Reason'));head.append(tr);table.append(head);const body=create('tbody');\n    for(const row of value.excluded){const tr=create('tr'),reason=create('td',exclusionNames[row.code]??row.code);reason.title=row.code;tr.append(create('td',row.orderRef,'mono'),reason);body.append(tr);}\n    table.append(body);section.append(table);target.append(section);\n  }\n  const source=create('details');source.append(create('summary','Statement source records'));\n  const fields=create('dl',null,'key-values');addDefinition(fields,'Original run',value.source.runId,true);addDefinition(fields,'Report SHA-256',value.source.reportSha256,true);\n  if(value.source.usage)addDefinition(fields,'Closing usage SHA-256',value.source.usage.sha256,true);\n  if(value.source.usageOpening)addDefinition(fields,'Opening usage SHA-256',value.source.usageOpening.sha256,true);\n  source.append(fields);target.append(source);\n}\nfunction renderRetained(result){\n  currentDocument=result;knownStatements.set(result.statement.id,result.statement);\n  $('document-panel').hidden=false;$('document-title').textContent=result.statement.number+' · '+result.document.customer.name;\n  const statusBlock=$('document-status');statusBlock.replaceChildren(create('span',result.statement.status,'badge'));\n  if(result.statement.supersededBy)statusBlock.append(create('p','Superseded by retained document '+(knownStatements.get(result.statement.supersededBy)?.number??result.statement.supersededBy)+'.'));\n  if(result.statement.replacesId)statusBlock.append(create('p','Correction of '+(knownStatements.get(result.statement.replacesId)?.number??result.statement.replacesId)+'.'));\n  const links=$('document-downloads');links.replaceChildren();\n  for(const [name,title] of [['statement.html','Print document'],['statement.csv','Purchase CSV'],['usage.csv','Complete closing call CSV'],['period.csv','Period activity CSV'],['period-summary.csv','Period route totals CSV'],['usage-opening.json','Opening usage projection'],['usage-closing.json','Closing usage projection'],['statement.json','Statement JSON'],['manifest.json','File manifest'],['status.json','Current document status']]){\n    if(name!=='status.json'&&!Object.hasOwn(result.statement.files,name))continue;\n    const link=create('a',title);link.href=API+'/statements/'+result.statement.id+'/download/'+name;link.download='';links.append(link);\n  }\n  renderDocument(result.document,$('document-content'));\n  const list=$('document-history').querySelector('ol');list.replaceChildren();\n  for(const event of result.statement.history)list.append(create('li',event.at+' · '+event.actor+' · '+event.action+(event.reason?' · '+event.reason:'')));\n  $('withdraw-form').hidden=result.statement.status!=='RETAINED';\n}\nasync function openDocument(id){\n  const detail=await request('/statements/'+id);renderRetained(detail);$('document-panel').scrollIntoView({block:'start',behavior:'smooth'});status('Opened '+detail.statement.number+'.');\n}\nfunction utc(value){\n  if(!value)return undefined;\n  const normalized=new Date(value+'Z');if(!Number.isFinite(normalized.getTime()))throw new Error('Check the UTC recorded purchase period.');return normalized.toISOString();\n}\nfunction periodInput(value){return value?value.replace(/Z$/,'').replace(/\\.\\d+$/,''):'';}\n$('refresh').addEventListener('click',()=>run(refresh));\n$('new-customer').addEventListener('click',()=>run(async()=>{$('customer-picker').value='';fillCustomer('');bindingsOffset=0;await loadBindings();$('customer-form').elements.reference.focus();status('Enter the new customer profile.');}));\n$('customer-picker').addEventListener('change',()=>run(async()=>{fillCustomer($('customer-picker').value);bindingsOffset=0;await loadBindings();}));\n$('statement-customer').addEventListener('change',updateCorrections);\n$('statement-usage-mode').addEventListener('change',updatePeriodMode);\n$('preview-form').addEventListener('change',()=>{\n  if(!pendingRetention)clearPreview();\n  $('service-period-preview').hidden=true;\n});\n$('inspect-period').addEventListener('click',()=>run(async()=>{\n  const usageOpeningId=$('statement-usage-opening').value,usageId=$('statement-usage').value;\n  if(!usageOpeningId||!usageId)throw new Error('Choose the complete original opening and closing API-pass captures.');\n  const result=await request('/usage-period',{usageOpeningId,usageId});\n  const target=$('service-period-preview');target.replaceChildren();target.hidden=false;\n  renderServicePeriod(result.period,target);status('Original service period opened at workspace revision '+result.revision+'.');\n}));\n$('customer-form').addEventListener('submit',event=>{\n  event.preventDefault();run(async()=>{\n    const form=event.currentTarget,value=Object.fromEntries(new FormData(form));value.revision=state.revision;value.actor=actor();\n    if(form.dataset.id){value.id=form.dataset.id;value.expectedVersion=Number(form.dataset.version);}\n    const result=await request('/customers',value);takeState(result.state);$('customer-picker').value=result.customer.id;fillCustomer(result.customer.id);\n    bindingsOffset=0;await loadBindings();status('Saved customer '+result.customer.reference+'.');\n  });\n});\n$('assignment-form').addEventListener('submit',event=>{\n  event.preventDefault();run(async()=>{\n    const form=event.currentTarget,values=new FormData(form),customerId=$('customer-picker').value;\n    if(!customerId)throw new Error('Save or select the customer before assigning orders.');\n    const orders=String(values.get('orders')).split(/\\r?\\n/).filter(line=>line.trim()).map(line=>{\n      const split=line.indexOf('\\t');return {orderRef:(split<0?line:line.slice(0,split)).trim(),label:split<0?'':line.slice(split+1).trim()};\n    });\n    const result=await request('/bindings',{revision:state.revision,actor:actor(),customerId,orders,reassign:values.get('reassign')==='on',reason:values.get('reason')});\n    takeState(result.state);form.reset();bindingsOffset=0;await loadBindings();status(result.changed+' order assignments saved.');\n  });\n});\n$('usage-form').addEventListener('submit',event=>{\n  event.preventDefault();run(async()=>{\n    const form=event.currentTarget,file=form.elements.file.files[0];if(!file)throw new Error('Choose the original service usage JSON.');\n    if(file.size>24000000)throw new Error('Choose a service usage export up to 24 MB.');\n    const result=await request('/usage',{revision:state.revision,actor:actor(),name:form.elements.name.value.trim()||file.name,content:await file.text()});\n    takeState(result.state);$('statement-usage').value=result.import.id;form.reset();\n    status((result.reused?'Opened retained capture ':'Retained usage capture ')+result.import.name+' with '+result.import.orderCount+' original orders.');\n  });\n});\n$('preview-form').addEventListener('submit',event=>{\n  event.preventDefault();run(async()=>{\n    if(pendingRetention)throw new Error('Retry the pending retention request first so the document register can return its saved result.');\n    const values=Object.fromEntries(new FormData(event.currentTarget)),selection={customerId:values.customerId,runId:values.runId,usageId:values.usageId||null,replacesId:values.replacesId||null};\n    if(values.usageMode==='period'){\n      if(!values.usageOpeningId||!values.usageId)throw new Error('Choose both original snapshots for this service period.');\n      selection.usageOpeningId=values.usageOpeningId;\n    }\n    if(values.from||values.until){if(!values.from||!values.until)throw new Error('Enter both UTC period bounds.');selection.from=utc(values.from);selection.until=utc(values.until);}\n    preview=await request('/preview',selection);\n    $('preview-panel').hidden=false;$('preview-title').textContent=preview.draft.customer.name+' · '+preview.draft.items.length+' original purchases';\n    renderDocument(preview.draft,$('preview-content'));$('retain').textContent='Retain statement';\n    $('retention-note').textContent='Review the original purchases, usage and adjustments before retaining this document.';\n    $('preview-panel').scrollIntoView({block:'start',behavior:'smooth'});status('Statement prepared at workspace revision '+preview.revision+'.');\n  });\n});\n$('retain').addEventListener('click',()=>run(async()=>{\n  if(!pendingRetention){\n    if(!preview)throw new Error('Prepare a statement first.');\n    pendingRetention={...preview.intent,revision:preview.revision,actor:actor(),requestId:crypto.randomUUID(),previewSha256:preview.previewSha256};\n    try{sessionStorage.setItem('merchant-customer-statement-pending',JSON.stringify(pendingRetention));}catch{}\n  }\n  let result;\n  try{result=await request('/retain',pendingRetention);}\n  catch(error){\n    if(error.status&&error.status<500){\n      pendingRetention=null;try{sessionStorage.removeItem('merchant-customer-statement-pending');}catch{}clearPreview();\n      takeState(await request());throw error;\n    }\n    $('preview-panel').hidden=false;$('retain').textContent='Retry same retention';\n    $('retention-note').textContent='The retention reply did not complete. Retry this same request to recover its saved document.';\n    throw error;\n  }\n  pendingRetention=null;try{sessionStorage.removeItem('merchant-customer-statement-pending');}catch{}\n  takeState(result.state);clearPreview();renderRetained(result);registerOffset=0;\n  $('document-panel').scrollIntoView({block:'start',behavior:'smooth'});\n  status((result.reused?'Recovered retained document ':'Retained ')+result.statement.number+'.');\n  await loadRegister();\n}));\n$('correct-document').addEventListener('click',()=>run(async()=>{\n  if(!currentDocument||currentDocument.statement.status!=='RETAINED')throw new Error('Open a current retained statement to prepare its correction.');\n  const {statement,document}=currentDocument;\n  $('statement-customer').value=statement.customerId;updateCorrections();$('statement-replaces').value=statement.id;\n  $('statement-run').value=statement.runId;$('statement-usage').value=statement.usageId??'';\n  $('statement-usage-mode').value=document.servicePeriod?'period':'snapshot';\n  $('statement-usage-opening').value=statement.usageOpeningId??'';updatePeriodMode();\n  $('preview-form').elements.from.value=periodInput(document.selection.from);$('preview-form').elements.until.value=periodInput(document.selection.until);\n  $('prepare').scrollIntoView({block:'start',behavior:'smooth'});status('Review source records and prepare the correction of '+statement.number+'.');\n}));\n$('withdraw-form').addEventListener('submit',event=>{\n  event.preventDefault();run(async()=>{\n    const form=event.currentTarget,reason=form.elements.reason.value.trim();if(!reason)throw new Error('Enter the reason for withdrawing this document.');\n    const result=await request('/statements/'+currentDocument.statement.id+'/withdraw',{revision:state.revision,actor:actor(),reason});\n    takeState(result.state);renderRetained(result);form.reset();await loadRegister();status('Document '+result.statement.number+' withdrawn from the current register.');\n  });\n});\nfor(const [id,change] of [['bindings-prev',-50],['bindings-next',50]])$(id).addEventListener('click',()=>run(async()=>{bindingsOffset=Math.max(0,bindingsOffset+change);await loadBindings();}));\nfor(const [id,change] of [['register-prev',-50],['register-next',50]])$(id).addEventListener('click',()=>run(async()=>{registerOffset=Math.max(0,registerOffset+change);await loadRegister();}));\nfor(const id of ['register-customer','register-status'])$(id).addEventListener('change',()=>run(async()=>{registerOffset=0;await loadRegister();}));\ntry{$('operator').value=localStorage.getItem('merchant-customer-statement-operator')??'';}catch{}\nrun(async()=>{\n  await refresh();\n  try{pendingRetention=JSON.parse(sessionStorage.getItem('merchant-customer-statement-pending')??'null');}catch{pendingRetention=null;}\n  if(pendingRetention){\n    $('preview-panel').hidden=false;$('preview-title').textContent='Recover pending statement retention';\n    $('retain').textContent='Retry same retention';$('retention-note').textContent='A retention request was prepared in this browser session. Retry it to recover its original saved document.';\n    status('A pending retention request is available for recovery.');\n  }\n});\n"
