      "sha256": "9b4f481327504da93c96f4f01ac412c690b9bfafd2fbf3360d3991203be39a5c",
      "content": "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Customer statements · Merchant operations</title>\n<link rel=\"stylesheet\" href=\"/customer-statements/style.css\">\n<script type=\"module\" src=\"/customer-statements/app.mjs\"></script>\n</head>\n<body>\n<header class=\"topbar\">\n  <div><p class=\"eyebrow\">Merchant operations</p><h1>Customer statements</h1></div>\n  <div class=\"operator\"><label for=\"operator\">Operator</label><input id=\"operator\" maxlength=\"1000\" autocomplete=\"name\" placeholder=\"Name or team reference\"><button id=\"refresh\" type=\"button\">Refresh workspace</button></div>\n</header>\n<main>\n  <section class=\"intro\"><p>Prepare purchase and service usage statements from original merchant records. Assign customers, choose a completed accounting run, review the statement, and retain the files for delivery.</p><p id=\"revision\" class=\"muted\">Opening original workspace…</p></section>\n  <div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\"></div>\n  <div id=\"metrics\" class=\"metrics\" aria-label=\"Workspace totals\"></div>\n  <nav class=\"section-nav\" aria-label=\"Statement workflow\"><a href=\"#customers\">Customers and orders</a><a href=\"#usage\">Service usage</a><a href=\"#prepare\">Prepare statement</a><a href=\"#register\">Document register</a></nav>\n  <div class=\"workspace-grid\">\n    <section id=\"customers\" class=\"panel\">\n      <div class=\"panel-heading\"><div><p class=\"eyebrow\">01 · Customer records</p><h2>Customers and original orders</h2></div><button id=\"new-customer\" type=\"button\">New customer</button></div>\n      <label for=\"customer-picker\">Customer account</label><select id=\"customer-picker\"><option value=\"\">New customer</option></select>\n      <form id=\"customer-form\">\n        <div class=\"form-grid\"><label>Customer reference<input name=\"reference\" maxlength=\"80\" required placeholder=\"acme-ops\"></label><label>Customer name<input name=\"name\" maxlength=\"200\" required autocomplete=\"organization\"></label></div>\n        <label>Email<input name=\"email\" type=\"email\" maxlength=\"320\" autocomplete=\"email\"></label>\n        <label>Address<textarea name=\"address\" rows=\"2\" maxlength=\"2000\" autocomplete=\"street-address\"></textarea></label>\n        <label>Internal account note<textarea name=\"note\" rows=\"2\" maxlength=\"2000\"></textarea></label>\n        <div class=\"form-footer\"><small>Names, email and address appear on customer documents.</small><button type=\"submit\">Save customer</button></div>\n      </form>\n      <div class=\"subsection\">\n        <h3>Assign purchased orders</h3><p class=\"muted\">Use each original checkout order reference. Add a tab followed by a customer-facing description when useful.</p>\n        <form id=\"assignment-form\">\n          <label>Original orders<textarea name=\"orders\" rows=\"5\" required spellcheck=\"false\" placeholder=\"order-reference&#9;API service plan\"></textarea></label>\n          <label class=\"check\"><input name=\"reassign\" type=\"checkbox\">Correct orders currently assigned to another customer</label>\n          <label>Assignment or correction reason<input name=\"reason\" maxlength=\"2000\"></label>\n          <button type=\"submit\" id=\"assign-button\">Assign to selected customer</button>\n        </form>\n      </div>\n      <div class=\"subsection\"><div class=\"panel-heading\"><h3>Assigned orders</h3><span id=\"binding-count\" class=\"muted\"></span></div>\n        <div class=\"table-wrap\"><table><thead><tr><th>Original order</th><th>Description</th><th>Version</th></tr></thead><tbody id=\"binding-rows\"></tbody></table></div>\n        <div class=\"pager\"><button id=\"bindings-prev\" type=\"button\">Previous</button><span id=\"bindings-page\"></span><button id=\"bindings-next\" type=\"button\">Next</button></div>\n      </div>\n    </section>\n    <div class=\"right-column\">\n      <section id=\"usage\" class=\"panel\">\n        <p class=\"eyebrow\">02 · Original service records</p><h2>Import service usage</h2>\n        <p>Import the service usage export from the merchant receiver. A capture preserves purchased, used, reserved and remaining units at its recorded time.</p>\n        <form id=\"usage-form\">\n          <label>Capture name<input name=\"name\" maxlength=\"200\" placeholder=\"Merchant service usage\"></label>\n          <label>Original usage JSON<input name=\"file\" type=\"file\" accept=\".json,application/json\" required></label>\n          <button type=\"submit\">Retain usage capture</button>\n        </form>\n        <div id=\"usage-summary\" class=\"inset\"></div>\n      </section>\n      <section id=\"prepare\" class=\"panel\">\n        <p class=\"eyebrow\">03 · Statement preparation</p><h2>Choose original records</h2>\n        <form id=\"preview-form\">\n          <label>Customer<select name=\"customerId\" id=\"statement-customer\" required></select></label>\n          <label>Completed accounting run<select name=\"runId\" id=\"statement-run\" required></select></label>\n          <label>Service reporting<select name=\"usageMode\" id=\"statement-usage-mode\"><option value=\"snapshot\">Cumulative usage snapshot</option><option value=\"period\">Activity between two native snapshots</option></select></label>\n          <label>Service usage capture / closing snapshot<select name=\"usageId\" id=\"statement-usage\"><option value=\"\">Purchases only</option></select></label>\n          <div id=\"service-period-fields\" class=\"inset\" hidden>\n            <label>Opening native snapshot<select name=\"usageOpeningId\" id=\"statement-usage-opening\"><option value=\"\">Choose opening snapshot</option></select></label>\n            <p class=\"muted\">Choose two complete exports of the same original API pass. Their saved capture times define the observed interval. Earlier reserved work and recovered results remain in the comparison.</p>\n            <button id=\"inspect-period\" type=\"button\">Inspect service period</button>\n          </div>\n          <div id=\"service-period-preview\" hidden></div>\n          <div class=\"form-grid\"><label>Recorded purchases from (UTC)<input name=\"from\" type=\"datetime-local\" step=\"1\"></label><label>Until, exclusive (UTC)<input name=\"until\" type=\"datetime-local\" step=\"1\"></label></div>\n          <small>Leave both purchase dates empty to include an older prepaid order. Service dates come from its selected snapshots; the original purchase is recorded once.</small>\n          <label>Correction of retained statement<select name=\"replacesId\" id=\"statement-replaces\"><option value=\"\">New statement</option></select></label>\n          <button type=\"submit\">Prepare statement</button>\n        </form>\n      </section>\n    </div>\n  </div>\n  <section id=\"preview-panel\" class=\"panel\" hidden>\n    <div class=\"panel-heading\"><div><p class=\"eyebrow\">Prepared statement</p><h2 id=\"preview-title\"></h2></div><button id=\"retain\" type=\"button\">Retain statement</button></div>\n    <div id=\"preview-content\"></div>\n    <p id=\"retention-note\" class=\"muted\">Review the original purchases, usage and adjustments before retaining this document.</p>\n  </section>\n  <section id=\"register\" class=\"panel\">\n    <div class=\"panel-heading\"><div><p class=\"eyebrow\">04 · Document register</p><h2>Retained customer statements</h2></div><div class=\"filter-row\"><label>Customer<select id=\"register-customer\"><option value=\"\">All customers</option></select></label><label>Status<select id=\"register-status\"><option value=\"\">All statuses</option><option value=\"RETAINED\">Retained</option><option value=\"SUPERSEDED\">Superseded</option><option value=\"WITHDRAWN\">Withdrawn</option></select></label></div></div>\n    <div class=\"table-wrap\"><table><thead><tr><th>Statement</th><th>Customer</th><th>Created</th><th>Orders</th><th>Status</th><th>Open</th></tr></thead><tbody id=\"register-rows\"></tbody></table></div>\n    <div class=\"pager\"><button id=\"register-prev\" type=\"button\">Previous</button><span id=\"register-page\"></span><button id=\"register-next\" type=\"button\">Next</button></div>\n  </section>\n  <section id=\"document-panel\" class=\"panel\" hidden>\n    <div class=\"panel-heading\"><div><p class=\"eyebrow\">Retained original document</p><h2 id=\"document-title\"></h2></div><button id=\"correct-document\" type=\"button\">Prepare correction</button></div>\n    <div id=\"document-status\"></div><div id=\"document-downloads\" class=\"download-row\"></div><div id=\"document-content\"></div>\n    <details id=\"document-history\"><summary>Document history</summary><ol></ol></details>\n    <form id=\"withdraw-form\" class=\"withdrawal\"><label>Withdrawal reason<input name=\"reason\" maxlength=\"2000\" required></label><button type=\"submit\">Withdraw document from current register</button></form>\n  </section>\n</main>\n<footer class=\"page-footer\">Merchant customer records · Original accounting workspace</footer>\n</body>\n</html>\n"
    },
