      "path": "stellar/scf-starforge-20261009/merchant-settlement-accounting/receivables/browser-assets.json",
      "gitBlob": "58c588d358a3c137165c0e28bca6022185660572",
      "bytes": 1192,
      "sha256": "07d3f23907e52cee40252255cccf3bba52ee3ad8c9c08494cc9e060458fa5bef",
      "content": "{\n  \"schema\": \"stellar-forge.browser-assets.v1\",\n  \"root\": \"./public/\",\n  \"routes\": [\n    [\n      \"/receivables\",\n      [\n        \"index.html\",\n        \"text/html; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/\",\n      [\n        \"index.html\",\n        \"text/html; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/index.html\",\n      [\n        \"index.html\",\n        \"text/html; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/app.mjs\",\n      [\n        \"app.mjs\",\n        \"text/javascript; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/styles.css\",\n      [\n        \"styles.css\",\n        \"text/css; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/client.mjs\",\n      [\n        \"../client.mjs\",\n        \"text/javascript; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/config.json\",\n      [\n        \"config.json\",\n        \"application/json; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/payment-requests.mjs\",\n      [\n        \"payment-requests.mjs\",\n        \"text/javascript; charset=utf-8\"\n      ]\n    ],\n    [\n      \"/receivables/refunds.mjs\",\n      [\n        \"refunds.mjs\",\n        \"text/javascript; charset=utf-8\"\n      ]\n    ]\n  ]\n}\n"
