      "content": "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>Payment plans · Merchant workspace</title>\n  <link rel=\"stylesheet\" href=\"./styles.css\">\n</head>\n<body>\n  <a class=\"skip\" href=\"#workspace\">Skip to payment plans</a>\n  <header class=\"topbar\">\n    <div><p class=\"eyebrow\">Merchant workspace / Receivables</p><h1>Payment plans</h1></div>\n    <div class=\"actions\">\n      <label class=\"operator\">Operator<input id=\"operator\" value=\"merchant-operator\" maxlength=\"160\" autocomplete=\"off\"></label>\n      <a class=\"button\" href=\"/receivables/\">Invoices and payments</a>\n      <a class=\"button\" href=\"/customer-statements/\">Customers</a>\n      <button type=\"button\" data-action=\"refresh\">Refresh</button>\n      <button class=\"primary\" type=\"button\" data-action=\"new\">New payment plan</button>\n    </div>\n  </header>\n  <div id=\"message\" class=\"message\" role=\"status\" aria-live=\"polite\"></div>\n  <div id=\"pending\" class=\"pending\" aria-live=\"polite\"></div>\n  <main id=\"workspace\" tabindex=\"-1\">\n    <section class=\"filterbar\" aria-label=\"Payment-plan filters\">\n      <label>Customer<select id=\"customer-filter\"><option value=\"\">All customers</option></select></label>\n      <label class=\"grow\">Search<input id=\"search\" type=\"search\" placeholder=\"Customer, invoice or plan reference\"></label>\n      <label>Balance date<input id=\"as-of\" type=\"date\"></label>\n      <label>Planning through<input id=\"through\" type=\"date\"></label>\n      <button type=\"button\" data-action=\"apply\">Apply dates</button>\n    </section>\n    <section id=\"summary\" aria-label=\"Collections by currency\"></section>\n    <div class=\"sectionbar\">\n      <nav class=\"tabs\" aria-label=\"Payment-plan views\">\n        <button type=\"button\" data-action=\"tab\" data-tab=\"plans\" aria-current=\"page\">Plans</button>\n        <button type=\"button\" data-action=\"tab\" data-tab=\"collections\">Due schedule</button>\n        <button type=\"button\" data-action=\"tab\" data-tab=\"unplanned\">Unscheduled balances</button>\n      </nav>\n      <span id=\"revision\" class=\"meta\">Opening workspace…</span>\n      <div class=\"actions exports\"><button type=\"button\" data-action=\"collections-file\" data-name=\"collections.csv\">Export CSV</button><button type=\"button\" data-action=\"collections-file\" data-name=\"collections.json\">Export JSON</button></div>\n    </div>\n    <section id=\"content\" aria-live=\"polite\"><div class=\"empty\"><h2>Opening payment plans</h2><p>Loading invoices, schedules and recorded payments.</p></div></section>\n    <p class=\"footnote\">Balances follow the payments and credits recorded in Receivables. Each currency is shown separately.</p>\n  </main>\n  <dialog id=\"dialog\" aria-labelledby=\"dialog-title\">\n    <div class=\"dialog-head\"><h2 id=\"dialog-title\"></h2><button type=\"button\" data-action=\"close\" aria-label=\"Close payment-plan detail\">Close</button></div>\n    <div id=\"dialog-message\" class=\"message\" role=\"status\" aria-live=\"polite\"></div>\n    <div id=\"dialog-content\"></div>\n  </dialog>\n  <noscript>The local payment-plan desk requires JavaScript.</noscript>\n  <script type=\"module\" src=\"./app.mjs\"></script>\n</body>\n</html>\n"
