      "content": "// MIT. Routes and browser assets composed into the original receivables process.\nimport {readFile} from 'node:fs/promises';\nimport {readBrowserAssets} from '../../../distribution/browser-assets.mjs';\nimport {RECEIVABLE_REQUEST_BYTES} from '../store.mjs';\n\nconst STATIC = await readBrowserAssets(new URL('./browser-assets.json', import.meta.url));\nexport const PAYMENT_PLAN_REQUEST_BYTES = RECEIVABLE_REQUEST_BYTES;\nconst SCHEDULE_FILES = new Set(['schedule.json', 'schedule.csv', 'schedule.html', 'manifest.json']);\nconst COLLECTION_FILES = new Set(['collections.json', 'collections.csv']);\n\nfunction problem(code, message, status = 400) {\n  return Object.assign(new Error(message), {code, status});\n}\nfunction basePath(value, fallback) {\n  const path = String(value || fallback).replace(/\\/+$/, '');\n  if (!path.startsWith('/') || /[?#\\\\\\u0000-\\u0020]/.test(path) || path.includes('//') ||\n      path.split('/').some(part => part === '..' || part === '.')) {\n    throw new TypeError('Use a local absolute workspace route.');\n  }\n  return path;\n}\nfunction identifier(raw) {\n  let value;\n  try { value = decodeURIComponent(raw); } catch { throw problem('INVALID_IDENTIFIER', 'The record identifier is malformed.'); }\n  if (!value || value.length > 240 || value === '.' || value === '..' || /[\\\\/\\u0000-\\u001f]/.test(value)) {\n    throw problem('INVALID_IDENTIFIER', 'The record identifier is malformed.');\n  }\n  return value;\n}\nfunction filters(search) {\n  return {asOf: search.get('asOf') || undefined, through: search.get('through') || undefined,\n    customerId: search.get('customerId') || undefined};\n}\nexport async function paymentPlanAsset(path, {apiPath = '/api/receivables/payment-plans', uiPath = '/payment-plans'} = {}) {\n  apiPath = basePath(apiPath, '/api/receivables/payment-plans');\n  uiPath = basePath(uiPath, '/payment-plans');\n  if (path !== uiPath && !path.startsWith(uiPath + '/')) return null;\n  const name = path === uiPath ? 'index.html' : path.slice(uiPath.length + 1) || 'index.html';\n  if (name === 'config.json') {\n    return {bytes: Buffer.from(JSON.stringify({apiPath, uiPath, requestBytes: PAYMENT_PLAN_REQUEST_BYTES})),\n      type: 'application/json; charset=utf-8'};\n  }\n  const asset = STATIC.get('/payment-plans/' + name);\n  return asset ? {bytes: await readFile(asset.url), type: asset.type} : null;\n}\n\n/** The caller retains the original local request, JSON-size and accounting lease boundaries. */\nexport async function handlePaymentPlansRequest(workspace, {method, path, query = {}, value,\n  apiPath = '/api/receivables/payment-plans'}) {\n  apiPath = basePath(apiPath, '/api/receivables/payment-plans');\n  if (path !== apiPath && !path.startsWith(apiPath + '/')) return null;\n  const parts = path.slice(apiPath.length).split('/').filter(Boolean).map(identifier);\n  const route = parts.join('/');\n  const search = query instanceof URLSearchParams ? query :\n    new URLSearchParams(Object.entries(query).filter(([, item]) => item !== undefined && item !== null));\n  let result;\n  if (method === 'GET') {\n    if (!route || route === 'state') result = await workspace.state(filters(search));\n    else if (parts[0] === 'plans' && parts.length === 2) result = await workspace.detail(parts[1], {asOf: search.get('asOf') || undefined});\n    else if (parts[0] === 'plans' && parts.length === 3 && parts[2] === 'preview') result = await workspace.previewPlan(parts[1]);\n    else if (parts[0] === 'operations' && parts.length === 2) result = await workspace.getOperation(parts[1]);\n    else if (parts[0] === 'plans' && parts.length === 6 && parts[2] === 'editions' && parts[4] === 'files') {\n      if (!SCHEDULE_FILES.has(parts[5])) throw problem('DOCUMENT_NOT_FOUND', 'Choose a saved schedule document.', 404);\n      const file = await workspace.scheduleFile(parts[1], parts[3], parts[5]);\n      return {file, type: file.type};\n    } else if (route === 'collections/export') {\n      const output = await workspace.collectionsFiles(filters(search));\n      const name = search.get('name');\n      if (name) {\n        if (!COLLECTION_FILES.has(name)) throw problem('DOCUMENT_NOT_FOUND', 'Choose a collections export format.', 404);\n        const file = output.files.find(item => item.name === name);\n        if (!file) throw problem('DOCUMENT_NOT_FOUND', 'The selected collections file is unavailable.', 404);\n        return {file, type: file.type};\n      }\n      result = {report: output.report, revision: output.revision,\n        files: output.files.map(file => ({name: file.name, type: file.type, bytes: file.bytes.length}))};\n    } else throw problem('NOT_FOUND', 'This payment-plan route does not exist.', 404);\n  } else if (method === 'POST') {\n    if (!value || Array.isArray(value) || typeof value !== 'object') throw problem('INVALID_JSON', 'Send a JSON operator request.');\n    if (route === 'generate') result = await workspace.generate(value);\n    else if (route === 'plans') result = await workspace.savePlan(value);\n    else if (parts[0] === 'plans' && parts.length === 3 && parts[2] === 'activate') result = await workspace.activate(parts[1], value);\n    else if (parts[0] === 'plans' && parts.length === 3 && parts[2] === 'cancel') result = await workspace.cancelPlan(parts[1], value);\n    else throw problem('NOT_FOUND', 'This payment-plan operation does not exist.', 404);\n  } else throw problem('METHOD_NOT_ALLOWED', 'Use a supported payment-plan operation.', 405);\n  return {value: result};\n}\n\nexport const handlePaymentPlanRequest = handlePaymentPlansRequest;\n"
    },
    {
      "path": "stellar/scf-starforge-20261009/merchant-settlement-accounting/receivables/payment-plans/store.mjs",
      "gitBlob": "e2773d39c24bf9858cf38bf58d4613796076304c",
      "bytes": 16372,
      "sha256": "bcd21d801dc6262d0436fe19c0ed8d2d51a62db486e39023a62c89a8ece45139",
      "content": "// MIT. Payment plans share the accounting lease, revision, recovery and request journal.\nimport {randomUUID} from 'node:crypto';\nimport {constants} from 'node:fs';\nimport {open, mkdir, lstat} from 'node:fs/promises';\nimport {join} from 'node:path';\nimport {ReceivablesWorkspace, RECEIVABLE_REQUEST_BYTES} from '../store.mjs';\nimport {accountingWorkspaceBinding} from '../../workspace/binding.mjs';\nimport {need, plain, identifier, field, dateValue, today, json, sha, invoiceSummary} from '../core.mjs';\nimport {PLAN_SCHEMA, addDays, normalizePlanDraft, generateInstallments, compilePlanReview,\n  scheduleDocument, planProjection, collectionsReport, scheduleFiles, reportFiles} from './core.mjs';\n\nexport const PAYMENT_PLAN_REQUEST_BYTES = RECEIVABLE_REQUEST_BYTES;\nconst at = () => new Date().toISOString();\nconst FILE_NAMES = new Set(['schedule.json','schedule.csv','schedule.html','manifest.json']);\nfunction requestId(value) {\n  const id = field(value, 'request ID', 160);\n  need(/^[A-Za-z0-9][A-Za-z0-9._:-]{0,159}$/.test(id),\n    'INVALID_PAYMENT_PLAN_REQUEST_ID', 'Use the original stable request identifier.');\n  return id;\n}\nasync function syncDirectory(path) {\n  const handle = await open(path, constants.O_RDONLY | (constants.O_DIRECTORY ?? 0) | (constants.O_NOFOLLOW ?? 0));\n  try { await handle.sync(); } finally { await handle.close(); }\n}\nfunction editionSummary(edition) {\n  return {id: edition.id, editionNumber: edition.document.editionNumber, effectiveDate: edition.document.effectiveDate,\n    createdAt: edition.document.createdAt, actor: edition.document.actor, reviewSha256: edition.document.reviewSha256,\n    total: edition.document.schedule.total, currency: edition.document.source.currency,\n    reference: edition.document.schedule.reference, files: structuredClone(edition.files)};\n}\n\nexport class PaymentPlanWorkspace extends ReceivablesWorkspace {\n  binding() { return accountingWorkspaceBinding(this.workspace.directory, this.workspace.state); }\n  async _mutate(action, value, work) {\n    if (value?.workspaceId !== undefined) need(value.workspaceId === this.binding().workspaceId,\n      'PAYMENT_PLAN_WORKSPACE_CHANGED', 'Recover this operation in its original accounting workspace.', 409);\n    return super._mutate(action, value, work);\n  }\n  async init() {\n    await super.init();\n    return this.workspace.serial(async () => {\n      const data = this.data();\n      if (data.paymentPlans === undefined) {\n        data.paymentPlans = {schema: PLAN_SCHEMA, plans: []};\n        await this.workspace.commit('receivables_payment_plans_initialized', 'workspace startup');\n      }\n      const saved = this._planData();\n      need(saved.schema === PLAN_SCHEMA && Array.isArray(saved.plans),\n        'INVALID_PAYMENT_PLAN_WORKSPACE', 'The retained payment-plan workspace is invalid.', 409);\n      for (const plan of saved.plans) need(plain(plan) && Array.isArray(plan.editions) && Array.isArray(plan.history),\n        'INVALID_PAYMENT_PLAN_WORKSPACE', 'The retained payment-plan record is invalid.', 409);\n      return this;\n    });\n  }\n  _planData() {\n    const saved = this.data().paymentPlans;\n    need(saved && saved.schema === PLAN_SCHEMA && Array.isArray(saved.plans),\n      'PAYMENT_PLAN_WORKSPACE_REQUIRED', 'Initialize payment plans in the original accounting workspace.', 409);\n    return saved;\n  }\n  _plan(id) {\n    identifier(id, 'payment plan');\n    const plan = this._planData().plans.find(row => row.id === id);\n    need(plan, 'PAYMENT_PLAN_NOT_FOUND', 'Choose a saved payment plan.', 404);\n    return plan;\n  }\n  _edition(plan, id) {\n    identifier(id, 'schedule edition');\n    const edition = plan.editions.find(row => row.id === id);\n    need(edition, 'PAYMENT_PLAN_EDITION_NOT_FOUND', 'Choose a retained schedule edition.', 404);\n    return edition;\n  }\n  _result(record, asOf = today()) {\n    const result = {...super._result(record, asOf), workspaceId: this.binding().workspaceId};\n    if (!record.planId) return result;\n    const plan = this._plan(record.planId);\n    result.plan = planProjection(plan, this.data(), asOf);\n    result.draft = structuredClone(plan.draft);\n    if (record.editionId) result.edition = editionSummary(this._edition(plan, record.editionId));\n    return result;\n  }\n  _review(plan) {\n    need(plan.status !== 'CANCELLED', 'PAYMENT_PLAN_CANCELLED', 'Create a new schedule after a cancelled plan.', 409);\n    const invoice = this._invoice(plan.invoiceId), review = compilePlanReview(plan, invoice, this.data());\n    const previous = plan.editions.at(-1);\n    need(!previous || review.effectiveDate >= previous.document.effectiveDate,\n      'PAYMENT_PLAN_REVISION_BACKDATED', 'A revised schedule must take effect on or after its previous edition.', 409);\n    return review;\n  }\n  async state(query = {}) {\n    return this.workspace.serial(async () => {\n      const asOf = dateValue(query.asOf ?? today(), 'report date');\n      const through = dateValue(query.through ?? addDays(asOf, 90), 'last collection date');\n      if (query.customerId) this._customer(query.customerId);\n      const data = this.data(), all = this._planData().plans;\n      const selected = query.customerId ? all.filter(row => this._invoice(row.invoiceId).document.customer.id === query.customerId) : all;\n      return structuredClone({schema: PLAN_SCHEMA, revision: this.workspace.state.revision, workspaceId: this.binding().workspaceId, asOf, through,\n        customers: this.workspace.state.customerStatements.customers,\n        invoices: data.invoices.filter(row => !query.customerId || row.draft.customerId === query.customerId)\n          .map(row => invoiceSummary(row, data, asOf)),\n        plans: selected.map(row => planProjection(row, data, asOf)),\n        report: collectionsReport(data, all, {asOf, through, customerId: query.customerId})});\n    });\n  }\n  async detail(id, query = {}) {\n    return this.workspace.serial(async () => {\n      const plan = this._plan(id), data = this.data(), asOf = dateValue(query.asOf ?? today(), 'report date');\n      const invoice = this._invoice(plan.invoiceId), allocations = data.allocations.filter(row => row.invoiceId === invoice.id);\n      const receiptIds = new Set(allocations.map(row => row.receiptId));\n      return structuredClone({plan: planProjection(plan, data, asOf), draft: plan.draft,\n        editions: plan.editions.map(editionSummary), history: plan.history,\n        ledger: {invoice: invoiceSummary(invoice, data, asOf), allocations,\n          credits: data.credits.filter(row => row.invoiceId === invoice.id).map(row => ({\n            id: row.id, number: row.number, date: row.document.creditDate, amount: row.document.totals.total,\n            currency: row.document.currency})),\n          receipts: data.receipts.filter(row => receiptIds.has(row.id)).map(row => ({\n            id: row.id, reference: row.reference, method: row.method, receivedDate: row.receivedDate,\n            currency: row.currency, amount: row.amount, status: row.status, voidDate: row.voidDate ?? null}))},\n        revision: this.workspace.state.revision, workspaceId: this.binding().workspaceId});\n    });\n  }\n  async generate(value) {\n    need(plain(value), 'INVALID_PAYMENT_PLAN', 'Enter installment-generation settings.');\n    return this.workspace.serial(async () => {\n      const invoice = this._invoice(value.invoiceId);\n      need(invoice.document && invoice.status === 'ISSUED', 'PAYMENT_PLAN_INVOICE_REQUIRED', 'Choose a current issued invoice.', 409);\n      return {draft: generateInstallments(value, invoice, this.data()), revision: this.workspace.state.revision, workspaceId: this.binding().workspaceId};\n    });\n  }\n  async savePlan(value) {\n    return this._mutate('payment_plan_saved', value, async (data, actor) => {\n      need(plain(value.plan), 'INVALID_PAYMENT_PLAN', 'Supply the payment-plan draft.');\n      const invoice = this._invoice(value.plan.invoiceId), draft = normalizePlanDraft(value.plan, invoice, data);\n      let plan;\n      if (value.plan.id) {\n        plan = this._plan(value.plan.id);\n        need(plan.status !== 'CANCELLED', 'PAYMENT_PLAN_CANCELLED', 'Create a new plan after cancellation.', 409);\n        need(plan.invoiceId === draft.invoiceId, 'PAYMENT_PLAN_INVOICE_CHANGED', 'Keep the plan attached to its original invoice.', 409);\n        need(value.expectedVersion === plan.version, 'STALE_PAYMENT_PLAN', 'Reload the current plan before saving this edit.', 409);\n        const previous = plan.editions.at(-1);\n        need(!previous || draft.balanceDate >= previous.document.effectiveDate, 'PAYMENT_PLAN_REVISION_BACKDATED',\n          'A revised schedule must take effect on or after its previous edition.', 409);\n        plan.history.push({at: at(), actor, action: 'draft_updated', previousVersion: plan.version,\n          previousDraftSha256: sha(json(plan.draft))});\n        plan.draft = draft; plan.version++; plan.updatedAt = at();\n      } else {\n        plan = {id: randomUUID(), invoiceId: draft.invoiceId, status: 'DRAFT', version: 1, draft,\n          createdAt: at(), updatedAt: at(), cancelledDate: null, editions: [],\n          history: [{at: at(), actor, action: 'draft_created'}]};\n        this._planData().plans.unshift(plan);\n      }\n      return {planId: plan.id};\n    });\n  }\n  async previewPlan(id) {\n    return this.workspace.serial(async () => ({...this._review(this._plan(id)), revision: this.workspace.state.revision, workspaceId: this.binding().workspaceId}));\n  }\n  async _retainSchedule(document) {\n    const root = join(this.workspace.directory, 'exports'), directoryId = randomUUID(), directory = join(root, directoryId);\n    const parent = await lstat(root);\n    need(parent.isDirectory() && !parent.isSymbolicLink(), 'PAYMENT_PLAN_EXPORT_DIRECTORY_CHANGED',\n      'The original accounting export directory changed.', 409);\n    await mkdir(directory, {mode: 0o700});\n    const prepared = scheduleFiles(document), files = {};\n    for (const file of prepared) files[file.name] = {bytes: file.bytes.length, sha256: sha(file.bytes), type: file.type};\n    const manifest = {schema: 'stellar-forge.merchant-payment-schedule-files.v1', planId: document.planId,\n      editionId: document.id, invoiceId: document.source.invoiceId, invoiceSha256: document.source.invoiceSha256, files: structuredClone(files)};\n    prepared.push({name: 'manifest.json', type: 'application/json; charset=utf-8', bytes: Buffer.from(json(manifest))});\n    for (const file of prepared) {\n      const handle = await open(join(directory, file.name),\n        constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0), 0o600);\n      try { await handle.writeFile(file.bytes); await handle.sync(); } finally { await handle.close(); }\n      files[file.name] = {bytes: file.bytes.length, sha256: sha(file.bytes), type: file.type};\n    }\n    await syncDirectory(directory); await syncDirectory(root);\n    return {directoryId, files};\n  }\n  async activate(id, value) {\n    identifier(id, 'payment plan');\n    return this._mutate('payment_plan_activated', {...value, planId: id}, async (data, actor) => {\n      const plan = this._plan(id);\n      need(value.expectedVersion === plan.version, 'STALE_PAYMENT_PLAN', 'Reload and review the current plan before activating it.', 409);\n      const review = this._review(plan);\n      need(typeof value.reviewSha256 === 'string' && value.reviewSha256 === review.reviewSha256,\n        'PAYMENT_PLAN_REVIEW_CHANGED', 'Review the current invoice balance and installment schedule again.', 409);\n      need(!plan.editions.length || sha(json(plan.draft)) !== plan.editions.at(-1).draftSha256,\n        'PAYMENT_PLAN_EDITION_EXISTS', 'This exact schedule is already retained. Open its existing edition.', 409);\n      const other = this._planData().plans.find(row => row.id !== plan.id && row.invoiceId === plan.invoiceId &&\n        row.editions.length && (!row.cancelledDate ||\n          row.cancelledDate > row.editions[0].document.effectiveDate && row.cancelledDate > review.effectiveDate));\n      need(!other, 'PAYMENT_PLAN_ALREADY_ACTIVE',\n        'This invoice already has an overlapping retained schedule. Revise that plan or cancel it before this plan takes effect.', 409);\n      const document = scheduleDocument(review, {editionNumber: plan.editions.length + 1, actor, createdAt: at()});\n      const retained = await this._retainSchedule(document);\n      const edition = {id: document.id, document, draftSha256: sha(json(plan.draft)), ...retained};\n      plan.editions.push(edition); plan.status = 'ACTIVE'; plan.version++; plan.updatedAt = at();\n      plan.history.push({at: at(), actor, action: 'schedule_activated', editionId: edition.id,\n        editionNumber: document.editionNumber, effectiveDate: document.effectiveDate, reviewSha256: review.reviewSha256,\n        invoiceSha256: document.source.invoiceSha256, scheduledTotal: document.schedule.total});\n      return {planId: plan.id, editionId: edition.id};\n    });\n  }\n  async cancelPlan(id, value) {\n    identifier(id, 'payment plan');\n    return this._mutate('payment_plan_cancelled', {...value, planId: id}, async (data, actor) => {\n      const plan = this._plan(id);\n      need(value.expectedVersion === plan.version, 'STALE_PAYMENT_PLAN', 'Reload the current plan before cancellation.', 409);\n      need(plan.status !== 'CANCELLED', 'PAYMENT_PLAN_ALREADY_CANCELLED', 'This plan is already cancelled.', 409);\n      const cancelledDate = dateValue(value.cancelledDate, 'cancellation date'), reason = field(value.reason, 'cancellation reason', 3000);\n      const latestDate = plan.editions.at(-1)?.document.effectiveDate ?? plan.draft.balanceDate;\n      need(cancelledDate >= latestDate, 'PAYMENT_PLAN_CANCEL_BEFORE_EDITION',\n        'Cancel on or after the most recent schedule effective date.');\n      plan.status = 'CANCELLED'; plan.cancelledDate = cancelledDate; plan.version++; plan.updatedAt = at();\n      plan.history.push({at: at(), actor, action: 'schedule_cancelled', cancelledDate, reason});\n      return {planId: plan.id};\n    });\n  }\n  async scheduleFile(planId, editionId, name) {\n    return this.workspace.serial(async () => {\n      need(FILE_NAMES.has(name), 'PAYMENT_PLAN_FILE_NOT_FOUND', 'Choose a retained schedule format.', 404);\n      const plan = this._plan(planId), edition = this._edition(plan, editionId), record = edition.files[name];\n      need(record, 'PAYMENT_PLAN_FILE_NOT_FOUND', 'The selected schedule format is unavailable.', 404);\n      const directory = join(this.workspace.directory, 'exports', identifier(edition.directoryId, 'schedule export'));\n      const stat = await lstat(directory);\n      need(stat.isDirectory() && !stat.isSymbolicLink(), 'PAYMENT_PLAN_EXPORT_DIRECTORY_CHANGED',\n        'The retained schedule directory changed.', 409);\n      const handle = await open(join(directory, name), constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));\n      let bytes;\n      try {\n        const file = await handle.stat();\n        need(file.isFile() && file.size === record.bytes && file.size <= 32_000_000,\n          'PAYMENT_PLAN_FILE_CHANGED', 'The retained schedule file changed.', 409);\n        bytes = await handle.readFile();\n      } finally { await handle.close(); }\n      need(bytes.length === record.bytes && sha(bytes) === record.sha256,\n        'PAYMENT_PLAN_FILE_CHANGED', 'The file differs from the original retained schedule.', 409);\n      return {bytes, name: 'schedule-' + edition.id + '-' + name, type: record.type};\n    });\n  }\n  async collectionsFiles(query = {}) {\n    return this.workspace.serial(async () => {\n      if (query.customerId) this._customer(query.customerId);\n      const report = collectionsReport(this.data(), this._planData().plans, query);\n      return {report, files: reportFiles(report), revision: this.workspace.state.revision, workspaceId: this.binding().workspaceId};\n    });\n  }\n  async getOperation(id) {\n    id = requestId(id);\n    return this.workspace.serial(async () => {\n      const row = this.data().requests.find(item => item.id === id);\n      need(!row || row.action.startsWith('payment_plan_'), 'PAYMENT_PLAN_REQUEST_REUSED',\n        'This request ID belongs to another receivables operation.', 409);\n      if (!row) return {revision: this.workspace.state.revision, workspaceId: this.binding().workspaceId, operation: null};\n      return {...this._result(row.result), operation: {...structuredClone(row), replayed: true}};\n    });\n  }\n}\n"
    },
    {
      "path": "stellar/scf-starforge-20261009/merchant-settlement-accounting/receivables/payment-requests-verifier.mjs",
      "gitBlob": "d6b862f9d0d69f7e2a987c452199f40d269ef234",
      "bytes": 12194,
      "sha256": "290f5245598fe8bfedceba8b2010eae27be8575e506c34d9154ea045072e98a5",
      "content": "// MIT. Direct invoice payments use the original Stellar RPC catalogue and official XDR decoder.\nimport {createRequire} from 'node:module';\nimport {createHash} from 'node:crypto';\nimport {networkProfile, resolveRpcEndpoint, validStrKey} from '../../sf86-rpc-transfer-reconcile/terms.mjs';\nimport {rpc} from '../../sf86-rpc-transfer-reconcile/rpc-transport.mjs';\n\nconst HASH = /^[a-f0-9]{64}$/;\nconst INT64_MAX = (1n << 63n) - 1n;\nconst sha = value => createHash('sha256').update(value).digest('hex');\nconst jsonHash = value => sha(JSON.stringify(value));\nconst plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);\nfunction need(condition, code) {\n  if (!condition) throw Object.assign(new Error(code), {code});\n}\nfunction atomic(value) {\n  need(typeof value === 'string' && /^(0|[1-9][0-9]{0,11})(?:\\.[0-9]{1,7})?$/.test(value), 'CLASSIC_PAYMENT_AMOUNT_INVALID');\n  const [whole, fraction = ''] = value.split('.');\n  const amount = BigInt(whole + fraction.padEnd(7, '0'));\n  need(amount > 0n && amount <= INT64_MAX, 'CLASSIC_PAYMENT_AMOUNT_INVALID');\n  return amount.toString();\n}\nfunction assetValue(asset) {\n  need(asset && typeof asset.isNative === 'function', 'CLASSIC_PAYMENT_ASSET_INVALID');\n  if (asset.isNative()) return {kind: 'native', code: 'XLM', issuer: null};\n  const code = asset.getCode(), issuer = asset.getIssuer();\n  need(typeof code === 'string' && /^[a-zA-Z0-9]{1,12}$/.test(code) && validStrKey(issuer, 'G'), 'CLASSIC_PAYMENT_ASSET_INVALID');\n  return {kind: 'credit', code, issuer};\n}\nfunction sameAsset(a, b) {\n  return a?.kind === b?.kind && a?.code === b?.code && (a?.issuer ?? null) === (b?.issuer ?? null);\n}\nfunction switchName(value) {\n  need(value && typeof value.switch === 'function', 'CLASSIC_PAYMENT_XDR_INVALID');\n  return value.switch().name;\n}\nfunction memoValue(raw) {\n  switch (switchName(raw)) {\n    case 'memoNone': return {type: 'MEMO_NONE', value: ''};\n    case 'memoText': {\n      const bytes = Buffer.from(raw.text());\n      const text = bytes.toString('utf8');\n      need(Buffer.from(text, 'utf8').equals(bytes), 'CLASSIC_PAYMENT_MEMO_ENCODING_INVALID');\n      return {type: 'MEMO_TEXT', value: text};\n    }\n    case 'memoId': return {type: 'MEMO_ID', value: raw.id().toString()};\n    case 'memoHash': return {type: 'MEMO_HASH', value: Buffer.from(raw.hash()).toString('base64')};\n    case 'memoReturn': return {type: 'MEMO_RETURN', value: Buffer.from(raw.retHash()).toString('base64')};\n    default: throw Object.assign(new Error('CLASSIC_PAYMENT_MEMO_UNSUPPORTED'), {code: 'CLASSIC_PAYMENT_MEMO_UNSUPPORTED'});\n  }\n}\n\n/** Resolve the same maintained SDK installation as the original SF43 decoder. */\nexport async function loadInvoiceStellarSdk() {\n  try { return await import('@stellar/stellar-sdk/base'); }\n  catch (error) {\n    if (!['ERR_MODULE_NOT_FOUND', 'ERR_PACKAGE_PATH_NOT_EXPORTED'].includes(error.code)) throw error;\n    try { return await import('@stellar/stellar-sdk'); }\n    catch (rootError) {\n      if (rootError.code !== 'ERR_MODULE_NOT_FOUND') throw rootError;\n      const require = createRequire(new URL('../../sf88-operator-buyer-cli/package.json', import.meta.url));\n      try { return require('@stellar/stellar-sdk/base'); }\n      catch (localError) {\n        if (!['MODULE_NOT_FOUND', 'ERR_PACKAGE_PATH_NOT_EXPORTED'].includes(localError.code)) throw localError;\n        return require('@stellar/stellar-sdk');\n      }\n    }\n  }\n}\n\nfunction operationResults(sdk, rawResult, outer, inner) {\n  const decoded = sdk.xdr.TransactionResult.fromXDR(rawResult, 'base64');\n  let result = decoded.result();\n  const bumped = outer !== inner;\n  if (bumped) {\n    need(switchName(result) === 'txFeeBumpInnerSuccess', 'FEE_BUMP_TRANSACTION_NOT_SUCCESS');\n    const pair = result.innerResultPair();\n    need(Buffer.from(pair.transactionHash()).toString('hex') === inner.hash().toString('hex'), 'FEE_BUMP_INNER_HASH_MISMATCH');\n    result = pair.result().result();\n  }\n  need(switchName(result) === 'txSuccess', 'CLASSIC_TRANSACTION_RESULT_NOT_SUCCESS');\n  const operations = result.results();\n  need(Array.isArray(operations) && operations.length === inner.operations.length, 'CLASSIC_OPERATION_RESULT_COUNT_MISMATCH');\n  return operations;\n}\n\nfunction decodedTransfer(sdk, operation, result, transactionSource, index) {\n  if (!['payment', 'pathPaymentStrictReceive', 'pathPaymentStrictSend'].includes(operation.type)) return null;\n  need(switchName(result) === 'opInner', 'CLASSIC_OPERATION_NOT_SUCCESS');\n  const tr = result.tr();\n  need(switchName(tr) === operation.type, 'CLASSIC_OPERATION_RESULT_TYPE_MISMATCH');\n  const payment = tr.value();\n  const expectedResult = operation.type === 'payment' ? 'paymentSuccess' :\n    operation.type === 'pathPaymentStrictReceive' ? 'pathPaymentStrictReceiveSuccess' : 'pathPaymentStrictSendSuccess';\n  need(switchName(payment) === expectedResult, 'CLASSIC_OPERATION_NOT_SUCCESS');\n  const payer = operation.source || transactionSource;\n  if (operation.type === 'payment') {\n    return {operationIndex: index, operationType: operation.type, payer, recipient: operation.destination,\n      asset: assetValue(operation.asset), amountAtomic: atomic(operation.amount)};\n  }\n  // Both successful path operations contain the actual final destination amount.\n  const last = payment.success().last();\n  const recipient = sdk.StrKey.encodeEd25519PublicKey(last.destination().ed25519());\n  const asset = assetValue(sdk.Asset.fromOperation(last.asset()));\n  const amountAtomic = last.amount().toString();\n  need(/^[1-9][0-9]{0,18}$/.test(amountAtomic) && BigInt(amountAtomic) <= INT64_MAX, 'CLASSIC_PAYMENT_AMOUNT_INVALID');\n  need(recipient === operation.destination && sameAsset(asset, assetValue(operation.destAsset)), 'PATH_PAYMENT_DESTINATION_RESULT_MISMATCH');\n  if (operation.type === 'pathPaymentStrictReceive') {\n    need(amountAtomic === atomic(operation.destAmount), 'PATH_PAYMENT_AMOUNT_RESULT_MISMATCH');\n  } else {\n    need(BigInt(amountAtomic) >= BigInt(atomic(operation.destMin)), 'PATH_PAYMENT_AMOUNT_RESULT_MISMATCH');\n  }\n  return {operationIndex: index, operationType: operation.type, payer, recipient, asset, amountAtomic};\n}\n\n/** Decode the official original envelope/result; this helper never performs a send. */\nexport async function decodeInvoiceStellarTransfer({request, returned, transactionResponse, sdk} = {}) {\n  sdk ??= await loadInvoiceStellarSdk();\n  const outer = sdk.TransactionBuilder.fromXDR(transactionResponse.envelopeXdr, request.networkPassphrase);\n  const inner = outer.innerTransaction || outer;\n  const envelopeHash = outer.hash().toString('hex'), innerTransactionHash = inner.hash().toString('hex');\n  need(transactionResponse.txHash === returned.transaction && [envelopeHash, innerTransactionHash].includes(returned.transaction), 'CLASSIC_TRANSACTION_HASH_MISMATCH');\n  const memo = memoValue(inner.tx.memo());\n  need(memo.type === request.memo.type && memo.value === request.memo.value, 'CLASSIC_PAYMENT_MEMO_MISMATCH');\n  const results = operationResults(sdk, transactionResponse.resultXdr, outer, inner);\n  const transfers = inner.operations.map((operation, index) =>\n    decodedTransfer(sdk, operation, results[index], inner.source, index)).filter(Boolean);\n  const matches = transfers.filter(transfer => (returned.payer == null || transfer.payer === returned.payer) &&\n    transfer.recipient === request.destination && sameAsset(transfer.asset, request.asset) &&\n    transfer.amountAtomic === request.amountAtomic);\n  need(matches.length === 1, matches.length ? 'CLASSIC_PAYMENT_AMBIGUOUS' : 'CLASSIC_PAYMENT_TERMS_MISMATCH');\n  need(validStrKey(matches[0].payer, 'G'), 'CLASSIC_PAYMENT_PAYER_UNSUPPORTED');\n  need(matches[0].payer !== matches[0].recipient, 'CLASSIC_PAYMENT_SELF_TRANSFER');\n  const transactionHashes = [...new Set([envelopeHash, innerTransactionHash])];\n  return {...matches[0], memo, envelopeHash, innerTransactionHash,\n    transactionHashes, transactionFingerprints: transactionHashes.map(sha),\n    envelopeXdrSha256: sha(Buffer.from(transactionResponse.envelopeXdr, 'base64')),\n    resultXdrSha256: sha(Buffer.from(transactionResponse.resultXdr, 'base64'))};\n}\n\n/**\n * Trusted server-side invoice observer. Only catalogue HTTPS endpoints are accepted;\n * caller JSON cannot supply decoded transfer facts or replace the network response.\n */\nexport async function verifyInvoiceStellarTransfer({request, returned, fetchImpl = globalThis.fetch,\n  rpcEndpoint, sdk, signal} = {}) {\n  const observedAt = new Date().toISOString();\n  need(plain(request) && plain(returned) && HASH.test(returned.transaction ?? '') && (returned.payer == null || validStrKey(returned.payer, 'G')), 'INVOICE_TRANSACTION_REFERENCE_INVALID');\n  const profile = networkProfile(request.network);\n  need(request.networkPassphrase === profile.passphrase && validStrKey(request.destination, 'G'), 'INVOICE_PAYMENT_NETWORK_OR_DESTINATION_INVALID');\n  need(plain(request.asset) && (request.asset.kind === 'native' && request.asset.code === 'XLM' && request.asset.issuer == null ||\n    request.asset.kind === 'credit' && /^[a-zA-Z0-9]{1,12}$/.test(request.asset.code ?? '') && validStrKey(request.asset.issuer, 'G')), 'INVOICE_PAYMENT_ASSET_INVALID');\n  need(atomic(request.stellarAmount) === request.amountAtomic && plain(request.memo), 'INVOICE_PAYMENT_TERMS_INVALID');\n  const endpoint = resolveRpcEndpoint(request.network, rpcEndpoint);\n  const base = {schema: 'stellar-forge.invoice-stellar-transfer.v1', observedAt, network: request.network,\n    networkPassphrase: profile.passphrase, transaction: returned.transaction, payer: returned.payer ?? null,\n    transactionFingerprint: sha(returned.transaction),\n    verificationScope: request.network === 'stellar:pubnet' ? 'OFFICIAL_PUBNET_RPC' : 'OFFICIAL_TESTNET_RPC'};\n  const proof = {rpcEndpoint: endpoint, networkResponse: null, transactionResponse: null};\n  try {\n    proof.networkResponse = await rpc('getNetwork', {}, endpoint, fetchImpl, {signal});\n    proof.networkResultSha256 = jsonHash(proof.networkResponse);\n    need(proof.networkResponse.passphrase === profile.passphrase, 'RPC_NETWORK_PASSPHRASE_MISMATCH');\n    proof.transactionResponse = await rpc('getTransaction', {hash: returned.transaction}, endpoint, fetchImpl, {signal});\n    proof.transactionResultSha256 = jsonHash(proof.transactionResponse);\n    const tx = proof.transactionResponse;\n    if (tx.status === 'NOT_FOUND') return {...base, status: 'NOT_FOUND', reason: 'RPC_TRANSACTION_NOT_FOUND', proof};\n    need(tx.status === 'SUCCESS', 'RPC_TRANSACTION_NOT_SUCCESS');\n    need(tx.txHash === returned.transaction && Number.isSafeInteger(tx.ledger) && tx.ledger > 0, 'RPC_TRANSACTION_IDENTITY_INVALID');\n    const seconds = typeof tx.createdAt === 'number' && Number.isSafeInteger(tx.createdAt) ? String(tx.createdAt) : tx.createdAt;\n    need(typeof seconds === 'string' && /^[1-9][0-9]{0,12}$/.test(seconds) && Number.isSafeInteger(Number(seconds)), 'RPC_TRANSACTION_CLOSE_TIME_INVALID');\n    const time = new Date(Number(seconds) * 1000);\n    need(Number.isFinite(time.getTime()), 'RPC_TRANSACTION_CLOSE_TIME_INVALID');\n    need(typeof tx.envelopeXdr === 'string' && tx.envelopeXdr.length > 0 && typeof tx.resultXdr === 'string' && tx.resultXdr.length > 0,\n      'RPC_TRANSACTION_XDR_REQUIRED');\n    const decoded = await decodeInvoiceStellarTransfer({request, returned, transactionResponse: tx, sdk});\n    Object.assign(proof, decoded);\n    return {...base, status: 'VERIFIED', payer: decoded.payer, recipient: decoded.recipient, asset: decoded.asset,\n      amountAtomic: decoded.amountAtomic, memo: decoded.memo, ledger: tx.ledger, closedAt: time.toISOString(),\n      operationIndex: decoded.operationIndex, operationType: decoded.operationType, proof};\n  } catch (error) {\n    if (signal?.aborted) throw error;\n    return {...base, status: 'FAILED', reason: String(error?.code || 'INVOICE_TRANSFER_DECODE_FAILED'),\n      detail: String(error?.message || error), proof};\n  }\n}\n\n/** Bind trusted dependencies once at the application boundary. */\nexport function createInvoiceTransferVerifier(options = {}) {\n  return ({request, returned}) => verifyInvoiceStellarTransfer({...options, request, returned});\n}\n"
    },
    {
      "path": "stellar/scf-starforge-20261009/merchant-settlement-accounting/receivables/payment-requests-workspace.mjs",
      "gitBlob": "c545874d9ba460a9304e1b0f82f3ab5eb351ce37",
      "bytes": 27649,
      "sha256": "963f6cac80acabae291a58d78b1ea065b358d0b6d7a460ab003cf411a7fa5efa",
      "content": "// MIT. Native invoice collection shares the original accounting lease and journal.\nimport {randomUUID} from 'node:crypto';\nimport {constants} from 'node:fs';\nimport {open, mkdir, lstat} from 'node:fs/promises';\nimport {join} from 'node:path';\nimport {json, sha, need, plain, field, identifier, dateValue, currencyKey, minor, money,\n  today, invoiceSummary, receiptSummary} from './core.mjs';\nimport {refundRows, refundTransferFingerprints} from './refunds.mjs';\nimport {PAYMENT_REQUEST_SCHEMA, compilePaymentProposal, paymentDocument, requestRows,\n  paymentRequestSummary, paymentRequestHtml, paymentReturnInput, validatePaymentVerification,\n  requestTransactionFingerprints, timestamp} from './payment-requests.mjs';\n\nconst clone = value => structuredClone(value);\nconst HEX = /^[a-f0-9]{64}$/;\nconst PROOF_NAME = 'transfer-proof.json';\nasync function syncDirectory(path) {\n  const handle = await open(path, constants.O_RDONLY | (constants.O_DIRECTORY ?? 0) | (constants.O_NOFOLLOW ?? 0));\n  try { await handle.sync(); } finally { await handle.close(); }\n}\nfunction retainedVerification(verification, artifact) {\n  const original = verification.proof, proof = {};\n  for (const key of ['rpcEndpoint', 'networkResultSha256', 'transactionResultSha256', 'operationIndex',\n    'operationType', 'payer', 'recipient', 'asset', 'amountAtomic', 'memo', 'envelopeHash',\n    'innerTransactionHash', 'transactionHashes', 'transactionFingerprints', 'envelopeXdrSha256', 'resultXdrSha256'])\n    if (Object.hasOwn(original, key)) proof[key] = clone(original[key]);\n  proof.networkResponse = original.networkResponse == null ? null :\n    {passphrase: original.networkResponse.passphrase ?? null};\n  proof.transactionResponse = original.transactionResponse == null ? null :\n    Object.fromEntries(['status', 'txHash', 'ledger', 'createdAt'].map(key => [key, original.transactionResponse[key] ?? null]));\n  return {...clone(verification), proof, proofArtifact: clone(artifact)};\n}\nfunction page(query = {}) {\n  const offset = Number(query.offset ?? 0), limit = Number(query.limit ?? 100);\n  need(Number.isSafeInteger(offset) && offset >= 0 && Number.isSafeInteger(limit) && limit >= 1 && limit <= 500,\n    'INVALID_PAYMENT_REQUEST_PAGE', 'Use a nonnegative offset and a page size from one to 500.');\n  return {offset, limit};\n}\nfunction sameTransfer(source, network, fingerprints) {\n  return source?.network === network && requestTransactionFingerprints(source).some(item => fingerprints.has(item));\n}\nfunction requireUniqueTransfer(data, request, returned, fingerprints) {\n  need(!data.receipts.some(row => sameTransfer(row.source, request.proposal.network, fingerprints)),\n    'STELLAR_PAYMENT_ALREADY_RECORDED', 'This original Stellar transaction already has a payment receipt. Open that receipt instead of importing it again.', 409);\n  need(!refundRows(data).some(row => row.proposal.payout.network === request.proposal.network &&\n    refundTransferFingerprints(row).some(value => fingerprints.has(value))), 'STELLAR_PAYMENT_ASSIGNED_AS_REFUND',\n  'This original transaction already belongs to a customer refund. Recover that refund record.', 409);\n  for (const row of requestRows(data)) for (const item of row.returns ?? []) {\n    if (row.id === request.id && item.id === returned.id) continue;\n    if (row.proposal.network !== request.proposal.network) continue;\n    // A reported hash is evidence to check, not a reservation of someone else's transfer.\n    // Retain wrong-request and unsuccessful reports while allowing the correct request to receive it.\n    const accepted = (item.observations ?? []).filter(observation =>\n      observation.status === 'RECORDED' || observation.status === 'TESTNET_VERIFIED');\n    if (!item.receiptId && !accepted.length) continue;\n    const aliases = new Set([sha(item.transaction), ...accepted.flatMap(observation =>\n      requestTransactionFingerprints(observation.verification))]);\n    need(![...aliases].some(value => fingerprints.has(value)), 'STELLAR_PAYMENT_REFERENCE_ALREADY_ASSIGNED',\n      'This transaction already has a verified receiving result on another saved reference. Open that original reference.', 409);\n  }\n}\nfunction allocationCapacity(invoice, data, allocatedDate) {\n  if (invoice.status !== 'ISSUED' || invoice.voidDate) return 0n;\n  const dates = new Set([allocatedDate]);\n  for (const row of data.allocations) if (row.invoiceId === invoice.id) {\n    if (row.allocatedDate >= allocatedDate) dates.add(row.allocatedDate);\n    if (row.releasedDate && row.releasedDate >= allocatedDate) dates.add(row.releasedDate);\n  }\n  for (const row of data.credits) if (row.invoiceId === invoice.id && row.document.creditDate >= allocatedDate)\n    dates.add(row.document.creditDate);\n  let available = null;\n  for (const date of dates) {\n    const amount = minor(invoiceSummary(invoice, data, date).amountDue, invoice.document.currency);\n    if (available === null || amount < available) available = amount;\n  }\n  return available ?? 0n;\n}\nfunction receiptPlan(data, invoice, request, returned, verification, input, actor, recordedAt) {\n  const proposal = request.proposal, currency = proposal.invoice.currency;\n  need(invoice.document && invoice.files?.['invoice.json']?.sha256 === proposal.invoice.sha256 &&\n    sha(json(invoice.document)) === proposal.invoice.sha256 &&\n    currencyKey(invoice.document.currency) === currencyKey(currency) &&\n    invoice.document.customer.id === request.customerId,\n  'PAYMENT_REQUEST_INVOICE_CHANGED', 'The receiving request must remain attached to its original issued invoice.', 409);\n  const amountUnits = minor(proposal.invoiceAmount, currency, 'invoice payment valuation', {positive: true});\n  const receivedDate = dateValue(verification.closedAt.slice(0, 10), 'ledger received date');\n  const allocatedDate = dateValue(input.allocatedDate ?? [today(), receivedDate, invoice.document.issueDate].sort().at(-1),\n    'allocation date');\n  need(allocatedDate >= receivedDate && allocatedDate >= invoice.document.issueDate, 'INVALID_ALLOCATION_DATE',\n    'Allocate on or after both the invoice date and the ledger received date.');\n  need(input.allocate === undefined || typeof input.allocate === 'boolean', 'INVALID_PAYMENT_ALLOCATION',\n    'Choose whether to allocate this receipt to the invoice.');\n  need(input.allocate !== false || input.allocationAmount === undefined, 'INVALID_PAYMENT_ALLOCATION',\n    'Choose an allocation amount only when applying the receipt to the invoice.');\n  const capacity = allocationCapacity(invoice, data, allocatedDate);\n  const allocatedUnits = input.allocate === false ? 0n : input.allocationAmount === undefined ?\n    (amountUnits < capacity ? amountUnits : capacity) :\n    minor(input.allocationAmount, currency, 'invoice allocation', {positive: true});\n  need(allocatedUnits <= amountUnits && allocatedUnits <= capacity, 'ALLOCATION_EXCEEDS_BALANCE',\n    'The allocation must fit the received amount and every retained invoice balance from the selected date.', 409);\n  const sourceKey = sha(json({kind: 'ORIGINAL_STELLAR_SETTLEMENT', network: proposal.network,\n    transactionFingerprint: verification.transactionFingerprint}));\n  const receiptId = randomUUID(), allocationId = allocatedUnits > 0n ? randomUUID() : null;\n  const source = {kind: 'ORIGINAL_STELLAR_INVOICE_TRANSFER', paymentRequestId: request.id,\n    paymentReturnId: returned.id, invoiceId: invoice.id, invoiceSha256: proposal.invoice.sha256,\n    paymentRequestSha256: request.documentSha256, network: proposal.network,\n    transaction: returned.transaction, transactionFingerprint: verification.transactionFingerprint,\n    transactionFingerprints: verification.transactionFingerprints, asset: clone(proposal.asset),\n    amountAtomic: proposal.amountAtomic, recipient: proposal.destination, payer: verification.payer,\n    memo: clone(proposal.memo), ledger: verification.ledger, closedAt: verification.closedAt,\n    verificationScope: verification.verificationScope, valuationNote: proposal.valuationNote,\n    invoiceAmount: proposal.invoiceAmount, verificationSha256: sha(json(verification)), proof: clone(verification.proof)};\n  const receipt = {id: receiptId, customerId: request.customerId, customer: clone(invoice.document.customer),\n    currency: clone(currency), amount: money(amountUnits, currency), receivedDate,\n    method: 'Stellar invoice payment', reference: invoice.number + ' / ' + returned.transaction,\n    note: field(input.note ?? returned.note ?? '', 'internal payment note', 4000, true),\n    sourceKey, source, createdAt: recordedAt, actor, status: 'RECORDED',\n    history: [{at: recordedAt, actor, action: 'original_invoice_transfer_imported',\n      paymentRequestId: request.id, paymentReturnId: returned.id}]};\n  const allocation = allocationId ? {id: allocationId, invoiceId: invoice.id, receiptId,\n    customerId: request.customerId, currency: clone(currency), amount: money(allocatedUnits, currency),\n    minorAmount: allocatedUnits.toString(), allocatedDate, releasedDate: null, createdAt: recordedAt, actor,\n    history: [{at: recordedAt, actor, action: 'allocated', allocatedDate}]} : null;\n  if (allocation) receipt.history.push({at: recordedAt, actor, action: 'allocated', invoiceId: invoice.id,\n    allocationId, amount: allocation.amount, allocatedDate});\n  return {receipt, allocation};\n}\nfunction immutableRequest(row) {\n  need(row.schema === PAYMENT_REQUEST_SCHEMA && HEX.test(row.documentSha256 ?? '') &&\n    sha(json(paymentDocument(row))) === row.documentSha256,\n  'PAYMENT_REQUEST_DOCUMENT_CHANGED', 'The saved payment-request document differs from its issued version.', 409);\n}\n\nexport class PaymentRequestsWorkspace {\n  constructor(receivables, {verifyTransfer} = {}) {\n    this.receivables = receivables;\n    this.workspace = receivables.workspace;\n    this.verifyTransfer = verifyTransfer;\n  }\n  data() { return this.receivables.data(); }\n  async _retainProof(verification, observationId) {\n    const directoryId = identifier(observationId, 'transfer observation');\n    const root = join(this.workspace.directory, 'exports'), directory = join(root, directoryId);\n    const parent = await lstat(root);\n    need(parent.isDirectory() && !parent.isSymbolicLink(), 'PAYMENT_PROOF_DIRECTORY_CHANGED',\n      'The original accounting export directory changed.', 409);\n    const bytes = Buffer.from(json(verification));\n    const artifact = {directoryId, name: PROOF_NAME, bytes: bytes.length, sha256: sha(bytes)};\n    await mkdir(directory, {mode: 0o700});\n    const handle = await open(join(directory, PROOF_NAME),\n      constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0), 0o600);\n    try { await handle.writeFile(bytes); await handle.sync(); } finally { await handle.close(); }\n    await syncDirectory(directory); await syncDirectory(root);\n    return artifact;\n  }\n  async _proof(observation) {\n    const metadata = observation.verification.proofArtifact;\n    // Saved records from the first source revision retain their original inline proof.\n    if (!metadata) return clone(observation.verification);\n    identifier(metadata.directoryId, 'transfer observation');\n    need(metadata.name === PROOF_NAME && HEX.test(metadata.sha256 ?? '') &&\n      Number.isSafeInteger(metadata.bytes) && metadata.bytes > 0 && metadata.bytes <= 128_000_000,\n    'INVALID_PAYMENT_PROOF_REFERENCE', 'The saved native transfer proof reference is invalid.', 409);\n    const directory = join(this.workspace.directory, 'exports', metadata.directoryId), stat = await lstat(directory);\n    need(stat.isDirectory() && !stat.isSymbolicLink(), 'PAYMENT_PROOF_DIRECTORY_CHANGED',\n      'The retained native transfer proof directory changed.', 409);\n    const handle = await open(join(directory, PROOF_NAME), constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));\n    let bytes;\n    try {\n      const file = await handle.stat();\n      need(file.isFile() && file.size === metadata.bytes, 'PAYMENT_PROOF_FILE_CHANGED',\n        'The native transfer proof size differs from its original record.', 409);\n      bytes = await handle.readFile();\n    } finally { await handle.close(); }\n    need(bytes.length === metadata.bytes && sha(bytes) === metadata.sha256, 'PAYMENT_PROOF_FILE_CHANGED',\n      'The native transfer proof differs from its original bytes.', 409);\n    let verification;\n    try { verification = JSON.parse(bytes.toString('utf8')); }\n    catch { need(false, 'INVALID_PAYMENT_PROOF_JSON', 'The retained native transfer proof is not valid JSON.', 409); }\n    need(verification.network === observation.verification.network &&\n      verification.transaction === observation.verification.transaction &&\n      verification.status === observation.verification.status, 'PAYMENT_PROOF_IDENTITY_CHANGED',\n    'The native transfer proof belongs to a different saved observation.', 409);\n    return verification;\n  }\n  async _fullReturn(returned) {\n    const result = clone(returned);\n    for (const observation of result.observations) observation.verification = await this._proof(observation);\n    return result;\n  }\n  _request(id) {\n    identifier(id, 'payment request');\n    const row = requestRows(this.data()).find(item => item.id === id);\n    need(row, 'PAYMENT_REQUEST_NOT_FOUND', 'Choose a saved invoice payment request.', 404);\n    immutableRequest(row);\n    return row;\n  }\n  _return(row, id) {\n    identifier(id, 'returned payment');\n    const returned = row.returns.find(item => item.id === id);\n    need(returned, 'PAYMENT_RETURN_NOT_FOUND', 'Choose a transaction reported for this payment request.', 404);\n    return returned;\n  }\n  summaries(data = this.data(), asOf = today()) {\n    return requestRows(data).map(row => paymentRequestSummary(row, data, asOf));\n  }\n  summary(id, data = this.data(), asOf = today()) {\n    const row = requestRows(data).find(item => item.id === id);\n    need(row, 'PAYMENT_REQUEST_NOT_FOUND', 'Choose a saved invoice payment request.', 404);\n    return paymentRequestSummary(row, data, asOf);\n  }\n  async preview(invoiceId, input) {\n    identifier(invoiceId, 'invoice');\n    return this.workspace.serial(async () => {\n      const invoice = this.receivables._invoice(invoiceId), data = this.data();\n      await this.receivables._file(invoiceId, 'invoice.json');\n      const proposal = compilePaymentProposal(invoice, data, input);\n      return {proposal, reviewSha256: sha(json(proposal)), invoice: invoiceSummary(invoice, data),\n        revision: this.workspace.state.revision};\n    });\n  }\n  async create(invoiceId, input) {\n    identifier(invoiceId, 'invoice');\n    return this.receivables._mutate('payment_request_issued', {...input, invoiceId}, async (data, actor) => {\n      need(plain(input.proposal) && input.proposal.invoice?.id === invoiceId &&\n        typeof input.reviewSha256 === 'string' && HEX.test(input.reviewSha256) &&\n        sha(json(input.proposal)) === input.reviewSha256,\n      'PAYMENT_REQUEST_REVIEW_REQUIRED', 'Issue the exact proposal returned by the payment-request preview.', 409);\n      const invoice = this.receivables._invoice(invoiceId), issuedAt = timestamp();\n      const proposal = compilePaymentProposal(invoice, data, input.proposal, {now: issuedAt, id: input.proposal.id});\n      need(sha(json(proposal)) === input.reviewSha256, 'PAYMENT_REQUEST_REVIEW_CHANGED',\n        'The invoice balance or selected payment terms changed. Review the current payment request.', 409);\n      need(!requestRows(data).some(row => row.id === proposal.id), 'PAYMENT_REQUEST_EXISTS',\n        'This payment request already has an issued record. Recover its original operation.', 409);\n      await this.receivables._file(invoiceId, 'invoice.json');\n      const row = {schema: PAYMENT_REQUEST_SCHEMA, id: proposal.id, invoiceId,\n        customerId: proposal.invoice.customer.id, issuedAt, actor, proposal,\n        reviewSha256: input.reviewSha256, returns: [], cancelledAt: null,\n        history: [{at: issuedAt, actor, action: 'issued', invoiceSha256: proposal.invoice.sha256,\n          invoiceAmount: proposal.invoiceAmount}]};\n      row.documentSha256 = sha(json(paymentDocument(row)));\n      data.paymentRequests ??= [];\n      data.paymentRequests.unshift(row);\n      invoice.history.push({at: issuedAt, actor, action: 'payment_request_issued', paymentRequestId: row.id,\n        invoiceAmount: proposal.invoiceAmount, network: proposal.network});\n      invoice.version++; invoice.updatedAt = issuedAt;\n      return {invoiceId, paymentRequestId: row.id};\n    });\n  }\n  async list(query = {}) {\n    return this.workspace.serial(async () => {\n      const data = this.data(), {offset, limit} = page(query);\n      if (query.invoiceId) this.receivables._invoice(query.invoiceId);\n      if (query.customerId) this.receivables._customer(query.customerId);\n      const rows = requestRows(data).filter(row => (!query.invoiceId || row.invoiceId === query.invoiceId) &&\n        (!query.customerId || row.customerId === query.customerId));\n      const summaries = rows.map(row => paymentRequestSummary(row, data, query.asOf ?? today()));\n      const matching = query.status ? summaries.filter(row => row.status === query.status) : summaries;\n      return {items: matching.slice(offset, offset + limit),\n        total: matching.length, offset, limit, revision: this.workspace.state.revision};\n    });\n  }\n  _detail(id, query = {}) {\n    const row = this._request(id), data = this.data(), asOf = query.asOf ?? today();\n    const receiptIds = new Set(row.returns.map(item => item.receiptId).filter(Boolean));\n    return clone({paymentRequest: paymentRequestSummary(row, data, asOf), proposal: row.proposal,\n      issuedAt: row.issuedAt, reviewSha256: row.reviewSha256, documentSha256: row.documentSha256,\n      returns: row.returns, receipts: data.receipts.filter(item => receiptIds.has(item.id))\n        .map(item => receiptSummary(item, data, asOf)),\n      allocations: data.allocations.filter(item => receiptIds.has(item.receiptId)),\n      cancelledAt: row.cancelledAt, cancellationReason: row.cancellationReason ?? null,\n      history: row.history, revision: this.workspace.state.revision});\n  }\n  async detail(id, query = {}) { return this.workspace.serial(async () => this._detail(id, query)); }\n  async cancel(id, input) {\n    return this.receivables._mutate('payment_request_cancelled', {...input, paymentRequestId: id}, async (data, actor) => {\n      const row = this._request(id);\n      need(!row.cancelledAt, 'PAYMENT_REQUEST_ALREADY_CANCELLED', 'This payment request already has a retained cancellation.', 409);\n      const reason = field(input.reason, 'cancellation reason', 3000), cancelledAt = timestamp();\n      const invoice = this.receivables._invoice(row.invoiceId);\n      row.cancelledAt = cancelledAt; row.cancelledBy = actor; row.cancellationReason = reason;\n      row.history.push({at: cancelledAt, actor, action: 'cancelled', reason});\n      invoice.history.push({at: cancelledAt, actor, action: 'payment_request_cancelled', paymentRequestId: id, reason});\n      invoice.version++; invoice.updatedAt = cancelledAt;\n      return {invoiceId: row.invoiceId, paymentRequestId: id};\n    });\n  }\n  async reportReturn(id, input) {\n    return this.receivables._mutate('payment_return_reported', {...input, paymentRequestId: id}, async (data, actor) => {\n      const row = this._request(id), selected = paymentReturnInput(input);\n      const existing = row.returns.find(item => item.transaction === selected.transaction);\n      if (existing) {\n        // Omitting payer is a replay/reselection of the existing reference. Explicit null\n        // clears an unverified sender constraint so the original envelope can determine it.\n        if (Object.hasOwn(input, 'payer') && (existing.payer ?? null) !== selected.payer) {\n          need(!existing.receiptId && !(existing.observations ?? []).some(observation =>\n            observation.verification?.status === 'VERIFIED'), 'PAYMENT_RETURN_PAYER_LOCKED',\n          'The sending account cannot change after this reference has a verified transfer. Open its original receiving result.', 409);\n          const correctionNote = field(input.note, 'payer correction note', 4000);\n          const previousPayer = existing.payer ?? null, correctedAt = timestamp();\n          existing.payer = selected.payer;\n          row.history.push({at: correctedAt, actor, action: 'transaction_payer_corrected',\n            paymentReturnId: existing.id, transaction: existing.transaction,\n            previousPayer, payer: selected.payer, note: correctionNote});\n        }\n        return {invoiceId: row.invoiceId, paymentRequestId: id, paymentReturnId: existing.id,\n          ...(existing.receiptId ? {receiptId: existing.receiptId} : {}),\n          ...(existing.allocationId ? {allocationId: existing.allocationId} : {})};\n      }\n      const returned = {id: randomUUID(), ...selected, reportedAt: timestamp(), actor,\n        observations: [], receiptId: null, allocationId: null};\n      requireUniqueTransfer(data, row, returned, new Set([sha(selected.transaction)]));\n      row.returns.push(returned);\n      row.history.push({at: returned.reportedAt, actor, action: 'transaction_reported',\n        paymentReturnId: returned.id, transaction: returned.transaction});\n      return {invoiceId: row.invoiceId, paymentRequestId: id, paymentReturnId: returned.id};\n    });\n  }\n  async receive(id, input) {\n    return this.receivables._mutate('invoice_payment_received', {...input, paymentRequestId: id}, async (data, actor) => {\n      const row = this._request(id), returned = this._return(row, input.returnId);\n      if (returned.receiptId) return {invoiceId: row.invoiceId, paymentRequestId: id,\n        paymentReturnId: returned.id, receiptId: returned.receiptId,\n        ...(returned.allocationId ? {allocationId: returned.allocationId} : {})};\n      const prior = returned.observations.at(-1);\n      if (prior?.status === 'TESTNET_VERIFIED' || prior?.status?.startsWith('TRANSFER_'))\n        return {invoiceId: row.invoiceId, paymentRequestId: id, paymentReturnId: returned.id};\n      need(typeof this.verifyTransfer === 'function', 'NATIVE_INVOICE_VERIFIER_REQUIRED',\n        'Connect the original native invoice transfer verifier before receiving this transaction.', 503);\n      const verification = validatePaymentVerification(row.proposal, returned,\n        await this.verifyTransfer({request: clone(row.proposal), returned: clone(returned)}));\n      const recordedAt = timestamp();\n      let status = verification.status;\n      if (status === 'FAILED' && verification.proof.transactionResponse?.status !== 'FAILED')\n        status = 'VERIFICATION_UNAVAILABLE';\n      if (status === 'VERIFIED') {\n        // Ledger closeTime has whole-second precision; compare the same time unit.\n        const seconds = value => Math.floor(Date.parse(value) / 1000);\n        status = seconds(verification.closedAt) < seconds(row.issuedAt) ? 'TRANSFER_PRECEDES_REQUEST' :\n          row.proposal.expiresAt && seconds(verification.closedAt) > seconds(row.proposal.expiresAt) ? 'TRANSFER_AFTER_EXPIRY' :\n          row.cancelledAt && seconds(verification.closedAt) > seconds(row.cancelledAt) ? 'TRANSFER_AFTER_CANCELLATION' :\n          row.proposal.network === 'stellar:testnet' ? 'TESTNET_VERIFIED' : 'RECORDED';\n      }\n      const observationId = randomUUID();\n      let planned = null;\n      if (status === 'RECORDED' || status === 'TESTNET_VERIFIED')\n        requireUniqueTransfer(data, row, returned, new Set(verification.transactionFingerprints));\n      if (status === 'RECORDED') {\n        const invoice = this.receivables._invoice(row.invoiceId);\n        await this.receivables._file(row.invoiceId, 'invoice.json');\n        planned = receiptPlan(data, invoice, row, returned, verification, input, actor, recordedAt);\n      }\n      const artifact = await this._retainProof(verification, observationId);\n      const compact = retainedVerification(verification, artifact);\n      const observation = {id: observationId, recordedAt, actor, status, verification: compact};\n      if (planned) {\n        planned.receipt.source.proof = clone(compact.proof);\n        planned.receipt.source.proofArtifact = clone(artifact);\n      }\n      // All native matching, document checks and dated conservation precede journal mutation.\n      returned.observations.push(observation);\n      row.history.push({at: recordedAt, actor, action: 'transaction_observed',\n        paymentReturnId: returned.id, transaction: returned.transaction, status});\n      if (planned) {\n        const {receipt, allocation} = planned, invoice = this.receivables._invoice(row.invoiceId);\n        data.receipts.unshift(receipt); returned.receiptId = receipt.id;\n        if (allocation) {\n          data.allocations.unshift(allocation); returned.allocationId = allocation.id;\n          invoice.history.push({at: recordedAt, actor, action: 'payment_allocated',\n            paymentRequestId: id, allocationId: allocation.id, receiptId: receipt.id,\n            amount: allocation.amount, allocatedDate: allocation.allocatedDate});\n        }\n        invoice.version++; invoice.updatedAt = recordedAt;\n        row.history.push({at: recordedAt, actor, action: 'receipt_recorded', paymentReturnId: returned.id,\n          receiptId: receipt.id, allocationId: allocation?.id ?? null, amount: receipt.amount,\n          allocatedAmount: allocation?.amount ?? money(0n, receipt.currency)});\n      }\n      return {invoiceId: row.invoiceId, paymentRequestId: id, paymentReturnId: returned.id,\n        ...(planned ? {receiptId: planned.receipt.id} : {}),\n        ...(planned?.allocation ? {allocationId: planned.allocation.id} : {})};\n    });\n  }\n  async file(id, name) {\n    return this.workspace.serial(async () => {\n      const row = this._request(id), data = this.data(), detail = this._detail(id);\n      let bytes, type = 'application/json; charset=utf-8';\n      if (name === 'payment-request.json') bytes = Buffer.from(json(paymentDocument(row)));\n      else if (name === 'payment-request.html') {\n        bytes = Buffer.from(paymentRequestHtml(row, data)); type = 'text/html; charset=utf-8';\n      } else if (name === 'payment-request.uri') {\n        bytes = Buffer.from(row.proposal.uri + '\\n'); type = 'text/plain; charset=utf-8';\n      } else if (name === 'status.json') {\n        bytes = Buffer.from(json({schema: 'stellar-forge.invoice-payment-status.v1',\n          revision: detail.revision, paymentRequest: detail.paymentRequest, history: detail.history}));\n      } else if (name === 'receiving.json') {\n        const completeReturns = [];\n        for (const returned of detail.returns) completeReturns.push(await this._fullReturn(returned));\n        bytes = Buffer.from(json({schema: 'stellar-forge.invoice-payment-receiving.v1',\n          originalRequest: paymentDocument(row), originalRequestSha256: row.documentSha256, ...detail,\n          returns: completeReturns}));\n      } else if (typeof name === 'string' && /^proof-[a-f0-9-]{36}\\.json$/.test(name)) {\n        const returned = await this._fullReturn(this._return(row, name.slice(6, -5)));\n        bytes = Buffer.from(json({schema: 'stellar-forge.invoice-payment-proof.v1',\n          paymentRequestId: row.id, originalRequestSha256: row.documentSha256,\n          originalRequest: paymentDocument(row), returned,\n          receipt: detail.receipts.find(item => item.id === returned.receiptId) ?? null,\n          allocations: detail.allocations.filter(item => item.receiptId === returned.receiptId)}));\n      } else need(false, 'PAYMENT_REQUEST_FILE_NOT_FOUND', 'Choose a retained payment-request or native receiving file.', 404);\n      return {bytes, name: row.proposal.invoice.number + '-' + row.id + '-' + name, type};\n    });\n  }\n}\n"
